        assert!(
            pcfg.changelog
                .as_ref()
                .map(|p| p.ends_with("FIRST.md"))
                .unwrap_or(false),
            "First MATCHING Prefixed entry (npm/pkg) must win (AC-F2): expected changelog ending \
             in FIRST.md. cargo/other skipped (name mismatch); pypi/pkg never reached. \
             Got changelog: {:?}",
            pcfg.changelog
        );
    }

