// CUTOVER-1 owner note: replace this temporary mirror with
// `callisto_model::ProductName::parse` as soon as the successor type is
// promoted; keeping the staged private type private currently prevents the
// graph resolver from calling the model-owned grammar.
fn is_canonical_release_name(value: &str) -> bool {
    !value.is_empty()
        && value.len() <= 63
        && value
            .bytes()
            .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'-')
        && value.bytes().next().is_some_and(|byte| byte.is_ascii_alphanumeric())
        && value.bytes().last().is_some_and(|byte| byte.is_ascii_alphanumeric())
}

fn is_safe_build_workflow(value: &str) -> bool {
    value.starts_with(".github/workflows/")
        && value.ends_with(".yml")
        && !value.contains("..")
        && value
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'_' | b'-' | b'/'))
}

/// Parses and canonicalizes a credential-free HTTP(S) registry endpoint.
///
/// One resolver owns this normalization so observation and dispatch never
/// disagree about a destination because of host casing, a default port, or a
/// trailing slash. Credentials, query parameters, and fragments are rejected
/// rather than normalized away because they must never become durable config.
fn normalize_registry_url(registry: &str, field: &'static str, raw: &str) -> Result<String, ConfigError> {
    let mut url = Url::parse(raw).map_err(|error| ConfigError::InvalidRegistryEndpoint {
        registry: registry.to_string(),
        field,
        value: raw.to_string(),
        reason: error.to_string(),
    })?;
    if !matches!(url.scheme(), "http" | "https") {
        return Err(ConfigError::InvalidRegistryEndpoint {
            registry: registry.to_string(),
            field,
            value: raw.to_string(),
            reason: "scheme must be http or https".to_string(),
        });
    }
    if url.host_str().is_none() || url.cannot_be_a_base() {
        return Err(ConfigError::InvalidRegistryEndpoint {
            registry: registry.to_string(),
            field,
            value: raw.to_string(),
            reason: "URL must have an authority and hierarchical path".to_string(),
        });
    }
    if !url.username().is_empty() || url.password().is_some() {
        return Err(ConfigError::InvalidRegistryEndpoint {
            registry: registry.to_string(),
            field,
            value: raw.to_string(),
            reason: "userinfo is forbidden".to_string(),
        });
    }
    if url.query().is_some() || url.fragment().is_some() {
        return Err(ConfigError::InvalidRegistryEndpoint {
            registry: registry.to_string(),
            field,
            value: raw.to_string(),
            reason: "query parameters and fragments are forbidden".to_string(),
        });
    }

    if matches!((url.scheme(), url.port()), ("http", Some(80)) | ("https", Some(443))) {
        url.set_port(None).map_err(|()| ConfigError::InvalidRegistryEndpoint {
            registry: registry.to_string(),
            field,
            value: raw.to_string(),
            reason: "default port could not be normalized".to_string(),
        })?;
    }
    let normalized_path = if url.path() == "/" {
        "/".to_string()
    } else {
        url.path().trim_end_matches('/').to_string()
    };
    url.set_path(&normalized_path);
    Ok(url.to_string())
}

fn complete_registry_endpoints(
    registry: &str,
    kind: Ecosystem,
    raw: &crate::config::raw::RawRegistryConfig,
) -> Result<Option<RegistryEndpoints>, ConfigError> {
    let present = [
        raw.index_url.is_some(),
        raw.api_url.is_some(),
        raw.registry_url.is_some(),
        raw.upload_url.is_some(),
        raw.metadata_url.is_some(),
        raw.simple_url.is_some(),
    ];
    if !present.into_iter().any(|value| value) {
        return Ok(None);
    }

    let invalid_shape = || ConfigError::InvalidRegistryEndpointShape {
        registry: registry.to_string(),
        ecosystem: kind,
    };
    match kind {
        Ecosystem::Cargo
            if raw.index_url.is_some()
                && raw.api_url.is_some()
                && raw.registry_url.is_none()
                && raw.upload_url.is_none()
                && raw.metadata_url.is_none()
                && raw.simple_url.is_none() =>
        {
            Ok(Some(RegistryEndpoints::Cargo {
                index: normalize_registry_url(registry, "index-url", raw.index_url.as_deref().expect("checked"))?,
                api: normalize_registry_url(registry, "api-url", raw.api_url.as_deref().expect("checked"))?,
            }))
        }
        Ecosystem::Npm
            if raw.index_url.is_none()
                && raw.api_url.is_none()
                && raw.registry_url.is_some()
                && raw.upload_url.is_none()
                && raw.metadata_url.is_none()
                && raw.simple_url.is_none() =>
        {
            Ok(Some(RegistryEndpoints::Npm {
                registry: normalize_registry_url(
                    registry,
                    "registry-url",
                    raw.registry_url.as_deref().expect("checked"),
                )?,
            }))
        }
        Ecosystem::Pypi
            if raw.index_url.is_none()
                && raw.api_url.is_none()
                && raw.registry_url.is_none()
                && raw.upload_url.is_some()
                && raw.metadata_url.is_some()
                && raw.simple_url.is_some() =>
        {
            Ok(Some(RegistryEndpoints::Pypi {
                upload: normalize_registry_url(registry, "upload-url", raw.upload_url.as_deref().expect("checked"))?,
                metadata: normalize_registry_url(
                    registry,
                    "metadata-url",
                    raw.metadata_url.as_deref().expect("checked"),
                )?,
                simple: normalize_registry_url(registry, "simple-url", raw.simple_url.as_deref().expect("checked"))?,
            }))
        }
        _ => Err(invalid_shape()),
    }
}

fn registry_binding<'a>(
    registries: &'a BTreeMap<RegistryKey, RegistryConfig>,
    profile: &str,
    key: &str,
    expected: Ecosystem,
) -> Result<(RegistryKey, &'a RegistryEndpoints), ConfigError> {
    let registry_key = RegistryKey(key.to_string());
    let registry = registries
        .get(&registry_key)
        .ok_or_else(|| ConfigError::UnknownReleaseRegistry {
            profile: profile.to_string(),
            registry: key.to_string(),
        })?;
    if registry.kind != expected {
        return Err(ConfigError::ReleaseRegistryEcosystemMismatch {
            profile: profile.to_string(),
            registry: key.to_string(),
            expected,
            found: registry.kind,
        });
    }
    let endpoints = registry
        .endpoints
        .as_ref()
        .ok_or_else(|| ConfigError::IncompleteReleaseRegistry {
            profile: profile.to_string(),
            registry: key.to_string(),
        })?;
    Ok((registry_key, endpoints))
}

fn resolve_release_config(
    raw: crate::config::raw::RawReleaseConfig,
    registries: &BTreeMap<RegistryKey, RegistryConfig>,
) -> Result<ReleaseConfig, ConfigError> {
    if !is_canonical_release_name(&raw.product.name) {
        return Err(ConfigError::InvalidReleaseProductName { name: raw.product.name });
    }
    let provenance_repository = GitHubRepository::parse(&raw.product.provenance_repository).map_err(|error| {
        ConfigError::InvalidReleaseRepository {
            field: "release.product.provenance-repository",
            value: raw.product.provenance_repository.clone(),
            reason: error.to_string(),
        }
    })?;
    if !is_safe_build_workflow(&raw.product.build_workflow) {
        return Err(ConfigError::InvalidReleaseWorkflow {
            workflow: raw.product.build_workflow,
        });
    }
    let product = ReleaseProductConfig {
        name: raw.product.name,
        provenance_repository,
        build_workflow: raw.product.build_workflow,
    };

    let mut profiles = BTreeMap::new();
    let mut production_profile = None;
    let mut rehearsal_count = 0usize;
    for (name, raw_profile) in raw.profiles {
        if !is_canonical_release_name(&name) {
            return Err(ConfigError::InvalidReleaseProfileName { name });
        }
        let kind = match raw_profile.kind.as_str() {
            "production" => ReleaseProfileKind::Production,
            "rehearsal" => ReleaseProfileKind::Rehearsal,
            _ => {
                return Err(ConfigError::InvalidReleaseProfileKind {
                    profile: name,
                    kind: raw_profile.kind,
                })
            }
        };
        let forge_repository = GitHubRepository::parse(&raw_profile.forge_repository).map_err(|error| {
            ConfigError::InvalidReleaseRepository {
                field: "release.profiles.*.forge-repository",
                value: raw_profile.forge_repository.clone(),
                reason: error.to_string(),
            }
        })?;
        let (cargo_registry, _) = registry_binding(registries, &name, &raw_profile.cargo_registry, Ecosystem::Cargo)?;
        let (npm_registry, _) = registry_binding(registries, &name, &raw_profile.npm_registry, Ecosystem::Npm)?;
        let (pypi_registry, _) = registry_binding(registries, &name, &raw_profile.pypi_registry, Ecosystem::Pypi)?;

        if kind == ReleaseProfileKind::Production {
            if production_profile.replace(name.clone()).is_some() {
                return Err(ConfigError::InvalidProductionProfileCount { found: 2 });
            }
        } else {
            rehearsal_count += 1;
        }
        profiles.insert(
            name,
            ReleaseProfileConfig {
                kind,
                forge_repository,
                cargo_registry,
                npm_registry,
                pypi_registry,
            },
        );
    }

    let production_profile = production_profile.ok_or(ConfigError::InvalidProductionProfileCount { found: 0 })?;
    if rehearsal_count == 0 {
        return Err(ConfigError::InvalidRehearsalProfileCount { found: 0 });
    }
    let production = profiles
        .get(&production_profile)
        .expect("production profile name came from this map");
    for (name, rehearsal) in profiles
        .iter()
        .filter(|(_, profile)| profile.kind == ReleaseProfileKind::Rehearsal)
    {
        if rehearsal.forge_repository == production.forge_repository {
            return Err(ConfigError::RehearsalDestinationNotIsolated {
                profile: name.clone(),
                destination: "forge repository",
            });
        }
        for (ecosystem, rehearsal_key, production_key) in [
            (Ecosystem::Cargo, &rehearsal.cargo_registry, &production.cargo_registry),
            (Ecosystem::Npm, &rehearsal.npm_registry, &production.npm_registry),
            (Ecosystem::Pypi, &rehearsal.pypi_registry, &production.pypi_registry),
        ] {
            let rehearsal_endpoints = registries
                .get(rehearsal_key)
                .and_then(|registry| registry.endpoints.as_ref())
                .expect("profile registry was validated above");
            let production_endpoints = registries
                .get(production_key)
                .and_then(|registry| registry.endpoints.as_ref())
                .expect("profile registry was validated above");
            if rehearsal_endpoints
                .urls()
                .iter()
                .any(|candidate| production_endpoints.urls().contains(candidate))
            {
                return Err(ConfigError::RehearsalDestinationNotIsolated {
                    profile: name.clone(),
                    destination: match ecosystem {
                        Ecosystem::Cargo => "Cargo endpoint set",
                        Ecosystem::Npm => "npm endpoint set",
                        Ecosystem::Pypi => "PyPI endpoint set",
                        _ => unreachable!("only releasable registry ecosystems are compared"),
                    },
                });
            }
        }
    }

    Ok(ReleaseConfig {
        product,
        profiles,
        production_profile,
    })
}
