#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ConfigProvenance {
    Default,
    Explicit,
}

impl ResolvedConfig {
    pub(crate) fn with_promoted_siblings(
        &self,
        promoted_siblings: BTreeMap<String, Vec<(PackageId, BTreeSet<Ecosystem>)>>,
    ) -> ResolvedConfig {
        let mut overlay = self.clone();
        overlay.promoted_siblings = promoted_siblings;
        overlay
    }

    pub fn provenance(&self, key: &ConfigKey) -> ConfigProvenance {
        self.provenance.get(key).copied().unwrap_or(ConfigProvenance::Default)
    }

    /// Resolves an allowlisted release profile without permitting callers to
    /// supply destination fields independently.
    pub fn release_profile(&self, name: &str) -> Result<(&ReleaseProductConfig, &ReleaseProfileConfig), ConfigError> {
        let release = self.release.as_ref().ok_or(ConfigError::ReleaseConfigurationMissing)?;
        let profile = release
            .profile(name)
            .ok_or_else(|| ConfigError::UnknownReleaseProfile {
                profile: name.to_string(),
            })?;
        Ok((&release.product, profile))
    }

    /// Returns the immutable, normalized endpoint set selected by a named
    /// profile for one supported ecosystem. This is the only durable release
    /// lookup; callers must not fall back to `RegistryConfig::url`.
    pub fn release_registry(
        &self,
        profile_name: &str,
        ecosystem: Ecosystem,
    ) -> Result<(&RegistryKey, &RegistryEndpoints), ConfigError> {
        let (_, profile) = self.release_profile(profile_name)?;
        let key = profile
            .registry_for(ecosystem)
            .ok_or(ConfigError::UnsupportedReleaseRegistryEcosystem { ecosystem })?;
        let endpoints = self
            .registries
            .get(key)
            .and_then(|registry| registry.endpoints.as_ref())
            .expect("release profile bindings are fully validated during config load");
        Ok((key, endpoints))
    }

    pub fn rendered_value(&self, key: &ConfigKey) -> Option<String> {
        if key == &ConfigKey::CASCADE_MODE {
            Some(match self.cascade.mode {
                CascadeMode::OutOfRange => "out-of-range".to_string(),
                CascadeMode::Always => "always".to_string(),
            })
        } else if key == &ConfigKey::CASCADE_BUMP_SEVERITY {
            Some(match self.cascade.bump_severity {
                CascadeBumpSeverity::Patch => "patch".to_string(),
                CascadeBumpSeverity::Minor => "minor".to_string(),
            })
        } else if key == &ConfigKey::CASCADE_PEER_ESCALATION {
            Some(self.cascade.peer_escalation.to_string())
        } else if key == &ConfigKey::CASCADE_PRESERVE_NPM_RANGES {
            Some(self.cascade.preserve_npm_ranges.to_string())
        } else if key == &ConfigKey::VALIDATION_ALLOW_EMPTY_CHANGESETS {
            Some(self.validation.allow_empty_changesets.to_string())
        } else {
            None
        }
    }
}

