impl ReleaseExecutionState {
    pub const SCHEMA_VERSION: u8 = 1;

    pub fn pending(intent: &ReleaseIntent) -> Self {
        Self {
            schema_version: Self::SCHEMA_VERSION,
            intent_digest: intent.digest.clone(),
            operations: intent
                .operations
                .iter()
                .map(|operation| (operation.id.clone(), ReleaseOperationState::Pending))
                .collect(),
        }
    }

    pub fn intent_digest(&self) -> &IntentDigest {
        &self.intent_digest
    }

    pub fn operation_state(&self, id: &ReleaseOperationId) -> Option<ReleaseOperationState> {
        self.operations.get(id).copied()
    }

    pub fn validate_for_intent(&self, intent: &ReleaseIntent) -> Result<(), ReleaseExecutionStateError> {
        if self.schema_version != Self::SCHEMA_VERSION {
            return Err(ReleaseExecutionStateError::UnsupportedSchema {
                found: self.schema_version,
            });
        }
        if self.intent_digest != intent.digest {
            return Err(ReleaseExecutionStateError::MismatchedIntent);
        }
        let expected = intent
            .operations
            .iter()
            .map(|operation| operation.id.clone())
            .collect::<BTreeSet<_>>();
        let actual = self.operations.keys().cloned().collect::<BTreeSet<_>>();
        if actual != expected {
            return Err(ReleaseExecutionStateError::MismatchedOperationRoster);
        }
        Ok(())
    }

    pub fn mark_attempting(&mut self, id: &ReleaseOperationId) -> Result<(), ReleaseExecutionStateError> {
        let state = self
            .operations
            .get_mut(id)
            .ok_or_else(|| ReleaseExecutionStateError::UnknownOperation {
                id: Box::new(id.clone()),
            })?;
        if *state != ReleaseOperationState::Pending {
            return Err(ReleaseExecutionStateError::InvalidTransition {
                id: Box::new(id.clone()),
                from: *state,
            });
        }
        *state = ReleaseOperationState::Attempting;
        "destination",
        serde_json::to_vec(destination).expect("closed destination binding serializes"),
    );
    for registry in approved {
        transcript.push_bytes(
            "approved-registry",
            serde_json::to_vec(registry).expect("closed roster serializes"),
        );
    }
    for operation in operations {
        transcript.push_bytes(
            "operation",
            serde_json::to_vec(&operation.id).expect("closed operation serializes"),
        );
        for prerequisite in &operation.prerequisites {
            transcript.push_bytes(
                "prerequisite",
                serde_json::to_vec(prerequisite).expect("closed operation serializes"),
            );
        }
    }
    for slot in slots {
        transcript.push_bytes("slot", serde_json::to_vec(slot).expect("closed slot serializes"));
    }
    IntentDigest::from_transcript(&transcript)
}

