    #[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, JsonSchema)]
    #[schemars(with = "String")]
    pub struct NpmDistTag(String);

    impl NpmDistTag {
        pub fn parse(raw: impl AsRef<str>) -> Result<Self, SuccessorError> {
            let raw = raw.as_ref();
            let valid = !raw.is_empty()
                && raw.len() <= 63
                && raw
                    .bytes()
                    .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'-')
                && raw.bytes().next().is_some_and(|byte| byte.is_ascii_lowercase())
                && raw.bytes().last().is_some_and(|byte| byte.is_ascii_alphanumeric());
            if !valid || semver::VersionReq::parse(raw).is_ok() {
                return Err(SuccessorError::InvalidNpmDistTag { raw: raw.to_string() });
            }
            Ok(Self(raw.to_string()))
        }

        pub fn as_str(&self) -> &str {
            &self.0
        }
    }

    impl<'de> Deserialize<'de> for NpmDistTag {
        fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
        where
            D: Deserializer<'de>,
        {
            Self::parse(String::deserialize(deserializer)?).map_err(serde::de::Error::custom)
        }
    }

    #[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize, JsonSchema)]
    #[serde(
        rename_all = "camelCase",
        rename_all_fields = "camelCase",
        tag = "kind",
        deny_unknown_fields
    )]
    pub enum RegistryPublicationPolicy {
        Cargo,
        Npm { access: NpmAccess, dist_tag: NpmDistTag },
        Pypi,
    }

    impl PartialOrd for RegistryPublicationPolicy {
        fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
            Some(self.cmp(other))
        }
    }

    impl Ord for RegistryPublicationPolicy {
        fn cmp(&self, other: &Self) -> Ordering {
            fn key(policy: &RegistryPublicationPolicy) -> (u8, u8, &str) {
                match policy {
                    RegistryPublicationPolicy::Cargo => (0, 0, ""),
                    RegistryPublicationPolicy::Npm { access, dist_tag } => (
                        1,
                        match access {
                            NpmAccess::Public => 0,
                            NpmAccess::Restricted => 1,
                        },
                        dist_tag.as_str(),
                    ),
                    RegistryPublicationPolicy::Pypi => (2, 0, ""),
                }
            }
            key(self).cmp(&key(other))
        }
    }

    impl RegistryPublicationPolicy {
        pub const fn cargo() -> Self {
            Self::Cargo
        }

        pub fn npm(access: NpmAccess, dist_tag: impl AsRef<str>) -> Result<Self, SuccessorError> {
            Ok(Self::Npm {
                access,
                dist_tag: NpmDistTag::parse(dist_tag)?,
            })
        }

        pub const fn pypi() -> Self {
            Self::Pypi
        }

        pub const fn ecosystem(&self) -> Ecosystem {
            match self {
                Self::Cargo => Ecosystem::Cargo,
                Self::Npm { .. } => Ecosystem::Npm,
                Self::Pypi => Ecosystem::Pypi,
            }
        }
    }

    /// The graph-derived, closed registry portion of the coordinated decision.
    #[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, JsonSchema)]
    #[serde(rename_all = "camelCase", deny_unknown_fields)]
