#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase", tag = "kind", deny_unknown_fields)]
pub enum ReleaseOperationId {
    RegistryArtifactPublish {
        package: ReleasePackageId,
        version: Version,
        #[serde(flatten)]
        registry: RegistryBindingId,
        slot: ReleaseArtifactSlot,
    },
    ProductTag {
        release: ProductReleaseId,
        tag: String,
    },
    ForgePrepare {
        release: ProductReleaseId,
        repository: GitHubRepository,
    },
    ArtifactUpload {
        release: ProductReleaseId,
        slot: ReleaseArtifactSlot,
    },
    ForgePublish {
        release: ProductReleaseId,
        repository: GitHubRepository,
    },
}

impl ReleaseOperationId {
    pub fn release(&self) -> Option<&ProductReleaseId> {
        match self {
            Self::RegistryArtifactPublish { .. } => None,
            Self::ProductTag { release, .. }
            | Self::ForgePrepare { release, .. }
            | Self::ArtifactUpload { release, .. }
            | Self::ForgePublish { release, .. } => Some(release),
        }
    }

    pub fn validate(&self, release: &ProductReleaseId) -> Result<(), SuccessorError> {
        match self {
            Self::RegistryArtifactPublish {
                package,
                version,
                registry,
                slot:
                    ReleaseArtifactSlot::RegistryPackage {
                        package: slot_package,
                        version: slot_version,
                        registry: slot_registry,
                        ..
                    },
            } if package == slot_package && version == slot_version && registry == slot_registry => Ok(()),
            Self::RegistryArtifactPublish { .. } => Err(SuccessorError::InvalidPackageOperation),
            Self::ProductTag { release: id, tag } if id == release && tag == &release.tag() => Ok(()),
            Self::ForgePrepare { release: id, .. } | Self::ForgePublish { release: id, .. } if id == release => {
                Ok(())
            }
            Self::ArtifactUpload { release: id, slot } if id == release && slot.release() == Some(id) => Ok(()),
            _ => Err(SuccessorError::InvalidProductOperation),
        }
    }
}

impl PartialOrd for ReleaseOperationId {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for ReleaseOperationId {
    fn cmp(&self, other: &Self) -> Ordering {
        fn rank(id: &ReleaseOperationId) -> u8 {
            match id {
                ReleaseOperationId::RegistryArtifactPublish { .. } => 0,
                ReleaseOperationId::ProductTag { .. } => 1,
                ReleaseOperationId::ForgePrepare { .. } => 2,
                ReleaseOperationId::ArtifactUpload { .. } => 3,
                ReleaseOperationId::ForgePublish { .. } => 4,
            }
        }
        match (self, other) {
            (
                Self::RegistryArtifactPublish {
                    package: left_package,
                    version: left_version,
                    registry: left_registry,
                    slot: left_slot,
                },
                Self::RegistryArtifactPublish {
                    package: right_package,
                    version: right_version,
                    registry: right_registry,
                    slot: right_slot,
                },
            ) => (left_package, version_ord_key(left_version), left_registry, left_slot).cmp(&(
                right_package,
                version_ord_key(right_version),
                right_registry,
                right_slot,
            )),
            (
                Self::ProductTag {
                    release: left_release,
                    tag: left_tag,
                },
                Self::ProductTag {
                    release: right_release,
                    tag: right_tag,
                },
            ) => (left_release, left_tag).cmp(&(right_release, right_tag)),
            (
                Self::ForgePrepare {
                    release: left_release,
                    repository: left_repository,
                },
                Self::ForgePrepare {
                    release: right_release,
                    repository: right_repository,
                },
            )
            | (
                Self::ForgePublish {
                    release: left_release,
                    repository: left_repository,
                },
                Self::ForgePublish {
                    release: right_release,
                    repository: right_repository,
                },
            ) => (left_release, left_repository.owner(), left_repository.repo()).cmp(&(
                right_release,
                right_repository.owner(),
                right_repository.repo(),
            )),
            (
                Self::ArtifactUpload {
                    release: left_release,
                    slot: left_slot,
                },
                Self::ArtifactUpload {
                    release: right_release,
                    slot: right_slot,
                },
            ) => (left_release, left_slot).cmp(&(right_release, right_slot)),
            _ => rank(self).cmp(&rank(other)),
        }
    }
}

