    },
    ForgePublish {
        release: ProductReleaseId,
        repository: GitHubRepository,
    },
}

impl ReleaseOperationId {
    pub fn release(&self) -> Option<&ProductReleaseId> {
        match self {
            Self::RegistryArtifactPublish { .. } => None,
            Self::ProductTag { release, .. }
            | Self::ForgePrepare { release, .. }
            | Self::ArtifactUpload { release, .. }
            | Self::ForgePublish { release, .. } => Some(release),
        }
    }

    pub fn validate(&self, release: &ProductReleaseId) -> Result<(), SuccessorError> {
        match self {
            Self::RegistryArtifactPublish {
                package,
                version,
                registry,
                slot:
                    ReleaseArtifactSlot::RegistryPackage {
                        package: slot_package,
                        version: slot_version,
                        registry: slot_registry,
                        ..
                    },
            } if package == slot_package && version == slot_version && registry == slot_registry => Ok(()),
            Self::RegistryArtifactPublish { .. } => Err(SuccessorError::InvalidPackageOperation),
            Self::ProductTag { release: id, tag } if id == release && tag == &release.tag() => Ok(()),
            Self::ForgePrepare { release: id, .. } | Self::ForgePublish { release: id, .. } if id == release => {
                Ok(())
            }
            Self::ArtifactUpload { release: id, slot } if id == release && slot.release() == Some(id) => Ok(()),
            _ => Err(SuccessorError::InvalidProductOperation),
        }
    }
}

