    operations: Vec<ReleaseOperation>,
    slots: Vec<ReleaseArtifactSlot>,
    digest: IntentDigest,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct ReleaseIntentWire {
    schema_version: u8,
    decision: ReleaseDecisionV1,
    product_release: ProductReleaseId,
    source_commit: CommitSha,
    destination: ReleaseDestinationBinding,
    registry_artifacts: Vec<ApprovedRegistryArtifact>,
    operations: Vec<ReleaseOperation>,
    slots: Vec<ReleaseArtifactSlot>,
    digest: IntentDigest,
}

impl ReleaseIntent {
    pub const SCHEMA_VERSION: u8 = 1;

    pub fn new(
        decision: ReleaseDecisionV1,
        product_release: ProductReleaseId,
        source_commit: CommitSha,
        destination: ReleaseDestinationBinding,
        mut registry_artifacts: Vec<ApprovedRegistryArtifact>,
        operations: Vec<ReleaseOperation>,
        mut slots: Vec<ReleaseArtifactSlot>,
    ) -> Result<Self, SuccessorError> {
        slots.sort();
        registry_artifacts.sort();
        let unique_registry_artifacts = registry_artifacts
            .iter()
            .map(|entry| (entry.package.clone(), entry.format, entry.file_name.clone()))
            .collect::<BTreeSet<_>>();
        if unique_registry_artifacts.len() != registry_artifacts.len() {
            return Err(SuccessorError::DuplicateRegistryArtifact);
        }
        let mut singular_artifacts = BTreeSet::new();
        if registry_artifacts.iter().any(|artifact| {
            artifact.format != RegistryArtifactFormat::PythonWheel
                && !singular_artifacts.insert((artifact.package.clone(), artifact.format))
        }) {
            return Err(SuccessorError::DuplicateRegistryArtifact);
        }
        validate_decision(&decision, &product_release, &registry_artifacts)?;
        validate_slot_roster(&product_release, &destination, &registry_artifacts, &slots)?;
        validate_operations(&product_release, &destination, &registry_artifacts, &operations, &slots)?;
        let digest = digest_intent(
            &decision,
            &product_release,
            &source_commit,
            &destination,
            &registry_artifacts,
            &operations,
            &slots,
        );
        Ok(Self {
            schema_version: Self::SCHEMA_VERSION,
            decision,
            product_release,
            source_commit,
            destination,
            registry_artifacts,
            operations,
            slots,
            digest,
        })
    }

    pub fn decision(&self) -> &ReleaseDecisionV1 {
        &self.decision
    }

    pub fn schema_version(&self) -> u8 {
        self.schema_version
    }

    pub fn product_release(&self) -> &ProductReleaseId {
        &self.product_release
    }

    pub fn source_commit(&self) -> &CommitSha {
        &self.source_commit
    }

    pub fn destination(&self) -> &ReleaseDestinationBinding {
        &self.destination
    }

    pub fn registry_artifacts(&self) -> &[ApprovedRegistryArtifact] {
        &self.registry_artifacts
    }

    pub fn operations(&self) -> &[ReleaseOperation] {
        &self.operations
    }

    pub fn slots(&self) -> &[ReleaseArtifactSlot] {
        &self.slots
    }

    pub fn digest(&self) -> &IntentDigest {
        &self.digest
    }
}

impl<'de> Deserialize<'de> for ReleaseIntent {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        let wire = ReleaseIntentWire::deserialize(deserializer)?;
        if wire.schema_version != Self::SCHEMA_VERSION {
            return Err(serde::de::Error::custom("unsupported successor release intent schema"));
        }
        let intent = Self::new(
            wire.decision,
            wire.product_release,
            wire.source_commit,
            wire.destination,
            wire.registry_artifacts,
            wire.operations,
            wire.slots,
        )
        .map_err(serde::de::Error::custom)?;

item.stdout:
            destination(),
            vec![ApprovedRegistryArtifact::new(
                package,
                mirror,
                RegistryArtifactFormat::CargoCrate,
                RegistryPublicationPolicy::cargo(),
                "callisto-model-1.2.3.crate",
            )
            .unwrap()],
            operations_for(&release, &destination(), &cross_bound_slots),
            cross_bound_slots,
        ),
        Err(SuccessorError::RegistryDestinationMismatch)
    ));
}

