    let mut missing = intent.slots.clone();
    missing.pop();
    assert!(matches!(
        ReleaseIntent::new(
            intent.decision.clone(),
            intent.product_release.clone(),
            commit(),
            intent.destination.clone(),
            intent.registry_artifacts.clone(),
            operations_for(&intent.product_release, &intent.destination, &missing),
            missing
        ),
        Err(SuccessorError::InvalidProductRoster)
    ));
    let mut duplicate = intent.slots.clone();
    duplicate.push(duplicate[0].clone());
    assert!(matches!(
        ReleaseIntent::new(
            intent.decision.clone(),
            intent.product_release.clone(),
            commit(),
            intent.destination.clone(),
            intent.registry_artifacts.clone(),
            operations_for(&intent.product_release, &intent.destination, &duplicate),
            duplicate
        ),
        Err(SuccessorError::DuplicateSlot)
    ));
    let mut heterogeneous_provenance = intent.slots.clone();
    if let ReleaseArtifactSlot::ProductAsset { provenance_policy, .. } = heterogeneous_provenance
        .iter_mut()
        .find(|slot| matches!(slot, ReleaseArtifactSlot::ProductAsset { .. }))
        .unwrap()
    {
        *provenance_policy = policy_for("callisto-rs/alternate-build-origin");
    }
    assert!(matches!(
        ReleaseIntent::new(
            intent.decision.clone(),
            intent.product_release.clone(),
            commit(),
            intent.destination.clone(),
            intent.registry_artifacts.clone(),
            operations_for(&intent.product_release, &intent.destination, &heterogeneous_provenance),
            heterogeneous_provenance,
        ),
        Err(SuccessorError::HeterogeneousProductProvenance)
    ));
    let mut wrong_target = intent.slots.clone();
    if let ReleaseArtifactSlot::ProductAsset { target, .. } = wrong_target
        .iter_mut()
        .find(|slot| matches!(slot, ReleaseArtifactSlot::ProductAsset { .. }))
        .unwrap()
    {
        *target = ProductTarget::Wasm32Wasip1;
    }
    assert!(matches!(
        ReleaseIntent::new(
            intent.decision.clone(),
            intent.product_release.clone(),
            commit(),
            intent.destination.clone(),
            intent.registry_artifacts.clone(),
            operations_for(&intent.product_release, &intent.destination, &wrong_target),
            wrong_target
        ),
        Err(SuccessorError::MismatchedProductPayload)
    ));
    let mut unsafe_slot = intent.slots.clone();
    if let ReleaseArtifactSlot::ProductAsset { file_name, .. } = unsafe_slot
        .iter_mut()
        .find(|slot| matches!(slot, ReleaseArtifactSlot::ProductAsset { .. }))
        .unwrap()
    {
        *file_name = "../callisto.tar.gz".to_string();
    }
    assert!(matches!(
        ReleaseIntent::new(
            intent.decision.clone(),
            intent.product_release.clone(),
            commit(),
            intent.destination.clone(),
            intent.registry_artifacts.clone(),
            operations_for(&intent.product_release, &intent.destination, &unsafe_slot),
            unsafe_slot
        ),
        Err(SuccessorError::UnsafeArtifactSlot)
    ));
    let mut swapped_names = intent.slots.clone();
    let product_indexes = swapped_names
        .iter()
        .enumerate()
        .filter_map(|(index, slot)| matches!(slot, ReleaseArtifactSlot::ProductAsset { .. }).then_some(index))
        .collect::<Vec<_>>();
    let first_name = swapped_names[product_indexes[0]].file_name().to_string();
    let second_name = swapped_names[product_indexes[1]].file_name().to_string();
    if let ReleaseArtifactSlot::ProductAsset { file_name, .. } = &mut swapped_names[product_indexes[0]] {
        *file_name = second_name;
    }
    if let ReleaseArtifactSlot::ProductAsset { file_name, .. } = &mut swapped_names[product_indexes[1]] {
        *file_name = first_name;
    }
    assert!(matches!(
        ReleaseIntent::new(
            intent.decision.clone(),
            intent.product_release.clone(),
            commit(),
            intent.destination.clone(),
            intent.registry_artifacts.clone(),
            operations_for(&intent.product_release, &intent.destination, &swapped_names),
            swapped_names
        ),
        Err(SuccessorError::MismatchedProductPayload)
    ));
    let mut safe_alternate_name = intent.slots.clone();
    if let ReleaseArtifactSlot::ProductAsset { file_name, .. } = safe_alternate_name
        .iter_mut()
        .find(|slot| matches!(slot, ReleaseArtifactSlot::ProductAsset { .. }))
        .unwrap()
    {
        *file_name = "callisto-arm64.tar.gz".to_string();
    }
    assert!(matches!(
        ReleaseIntent::new(
            intent.decision.clone(),
            intent.product_release.clone(),
            commit(),
            intent.destination.clone(),
            intent.registry_artifacts.clone(),
            operations_for(&intent.product_release, &intent.destination, &safe_alternate_name),
            safe_alternate_name
        ),
        Err(SuccessorError::MismatchedProductPayload)
    ));
    let mut wrong_kind = intent.slots.clone();
    if let ReleaseArtifactSlot::ProductAsset { artifact_kind, .. } = wrong_kind
        .iter_mut()
        .find(|slot| {
            matches!(
                slot,
                ReleaseArtifactSlot::ProductAsset {
                    target: ProductTarget::Wasm32Wasip1,
                    ..
                }
            )
        })
        .unwrap()
    {
        *artifact_kind = ProductArtifactKind::NativeArchive;
    }
    assert!(matches!(
        ReleaseIntent::new(
            intent.decision.clone(),
            intent.product_release.clone(),
            commit(),
            intent.destination.clone(),
            intent.registry_artifacts.clone(),
            operations_for(&intent.product_release, &intent.destination, &wrong_kind),
            wrong_kind
        ),
        Err(SuccessorError::MismatchedProductPayload)
    ));
    let mut fifth_target = intent.slots.clone();
    let fifth_slot = ReleaseArtifactSlot::ProductAsset {
        release: intent.product_release.clone(),
        target: ProductTarget::Aarch64AppleDarwin,
        artifact_kind: ProductArtifactKind::NativeArchive,
        file_name: ProductTarget::Aarch64AppleDarwin.file_name().to_string(),
        provenance_policy: policy(),
    };
    fifth_target.push(fifth_slot.clone());
    assert!(matches!(
        ReleaseIntent::new(
            intent.decision.clone(),
            intent.product_release.clone(),
            commit(),
            intent.destination.clone(),
            intent.registry_artifacts.clone(),
            operations_for(&intent.product_release, &intent.destination, &fifth_target),
            fifth_target
        ),
        Err(SuccessorError::DuplicateSlot)
    ));
    let mut malformed_policy = serde_json::to_value(&intent).unwrap();
    let slot = malformed_policy["slots"]
        .as_array_mut()
        .unwrap()
        .iter_mut()
        .find(|slot| slot["kind"] == "productAsset")
        .unwrap();
    assert!(slot.get("provenancePolicy").is_some());
    slot["provenancePolicy"]["githubAttestationRequired"] = serde_json::Value::Bool(false);
    let error = serde_json::from_value::<ReleaseIntent>(malformed_policy).unwrap_err();
    assert!(error.to_string().contains("artifact slot provenance is invalid"));
    let mut direct_policy = policy();
    direct_policy.github_attestation_required = false;
    assert!(matches!(
        direct_policy.validate(),
        Err(SuccessorError::InvalidProvenance)
    ));
    let mut wrong_forge = intent.operations.clone();
    if let ReleaseOperationId::ForgePublish { repository, .. } = &mut wrong_forge
        .iter_mut()
        .find(|operation| matches!(operation.id, ReleaseOperationId::ForgePublish { .. }))
        .unwrap()
        .id
    {
        *repository = GitHubRepository::parse("callisto-rs/other").unwrap();
    }
    assert!(ReleaseIntent::new(
        intent.decision.clone(),
        intent.product_release.clone(),
        commit(),
        intent.destination.clone(),
        intent.registry_artifacts.clone(),
        wrong_forge,
        intent.slots.clone()
    )
    .is_err());
}

#[test]
fn manifest_metadata_and_checksum_are_bound_without_circularity() {
    let intent = intent();
    let entries = intent
        .slots
        .iter()
        .filter(|slot| {
            matches!(
                slot,
                ReleaseArtifactSlot::RegistryPackage { .. } | ReleaseArtifactSlot::ProductAsset { .. }
            )
        })
        .cloned()
        .map(|slot| ReleaseArtifactEntry {
            digest: ArtifactDigest::from_bytes(slot.file_name().as_bytes()),
            byte_length: slot.file_name().len() as u64,
            source_commit: commit(),
            provenance: slot.policy().clone(),
            slot,
        })
        .collect::<Vec<_>>();
    let payloads = ValidatedPayloadEntries::new(&intent, entries).unwrap();
    let other_intent = ReleaseIntent::new(
        intent.decision.clone(),
        intent.product_release.clone(),
        CommitSha::parse(&"b".repeat(40)).unwrap(),
        intent.destination.clone(),
        intent.registry_artifacts.clone(),
        intent.operations.clone(),
        intent.slots.clone(),
    )
    .unwrap();
    assert!(ReleaseDistributionMetadataV1::from_payloads(&other_intent, &payloads).is_err());
    let metadata = ReleaseDistributionMetadataV1::from_payloads(&intent, &payloads).unwrap();
    let bundle = ReleaseArtifactManifest::complete_with_generated_files(&intent, &payloads).unwrap();
    let manifest = bundle.manifest().clone();
    assert_eq!(manifest.entries.len(), 6);
    assert!(manifest.validate_for_intent(&intent).is_ok());
    assert_eq!(
        ReleaseDistributionMetadataV1::from_canonical_json(bundle.metadata_bytes()).unwrap(),
        metadata
    );
    let metadata_entry = manifest
        .entries()
        .iter()
        .find(|entry| matches!(entry.slot(), ReleaseArtifactSlot::ReleaseMetadata { .. }))
        .unwrap();
    assert_eq!(
        metadata_entry.digest(),
        &ArtifactDigest::from_bytes(bundle.metadata_bytes())
    );
    assert_eq!(metadata_entry.byte_length(), bundle.metadata_bytes().len() as u64);
    let checksum_entry = manifest
        .entries()
        .iter()
        .find(|entry| matches!(entry.slot(), ReleaseArtifactSlot::ChecksumManifest { .. }))
        .unwrap();
    assert_eq!(
        checksum_entry.digest(),
        &ArtifactDigest::from_bytes(bundle.checksum_bytes())
    );
    assert_eq!(checksum_entry.byte_length(), bundle.checksum_bytes().len() as u64);
    let checksum_text = std::str::from_utf8(bundle.checksum_bytes()).unwrap();
    assert_eq!(checksum_text.lines().count(), 5);
    assert!(checksum_text.contains(METADATA_FILE_NAME));
    assert!(!checksum_text.contains(CHECKSUM_FILE_NAME));
    assert_eq!(
        serde_json::from_value::<ReleaseArtifactManifest>(serde_json::to_value(&manifest).unwrap()).unwrap(),
        manifest
    );
    assert_eq!(
        ReleaseDistributionMetadataV1::from_canonical_json(&metadata.canonical_json()).unwrap(),
        metadata
    );
    let pretty = serde_json::to_vec_pretty(&metadata).unwrap();
    assert!(matches!(
        ReleaseDistributionMetadataV1::from_canonical_json(&pretty),
        Err(SuccessorError::NonCanonicalMetadataBytes)
    ));
    let value = serde_json::to_value(&metadata).unwrap();
    let reordered = format!(
        "{{\"sourceCommit\":{},\"schemaVersion\":1,\"productRelease\":{},\"intentDigest\":{},\"payloads\":{},\"verificationPolicy\":{}}}",
        serde_json::to_string(&value["sourceCommit"]).unwrap(),
        serde_json::to_string(&value["productRelease"]).unwrap(),
        serde_json::to_string(&value["intentDigest"]).unwrap(),
        serde_json::to_string(&value["payloads"]).unwrap(),
        serde_json::to_string(&value["verificationPolicy"]).unwrap(),
    );
    assert!(matches!(
        ReleaseDistributionMetadataV1::from_canonical_json(reordered.as_bytes()),
        Err(SuccessorError::NonCanonicalMetadataBytes)
    ));
    let mut forged = manifest.clone();
    forged.entries[0].source_commit = CommitSha::parse(&"b".repeat(40)).unwrap();
    assert!(forged.validate_for_intent(&intent).is_err());
    let mut forged_metadata = manifest.clone();
    forged_metadata
        .entries
        .iter_mut()
        .find(|entry| matches!(entry.slot, ReleaseArtifactSlot::ReleaseMetadata { .. }))
        .unwrap()
        .byte_length += 1;
    assert!(forged_metadata.validate_for_intent(&intent).is_err());
    let mut forged_checksum = manifest.clone();
    forged_checksum
        .entries
        .iter_mut()
        .find(|entry| matches!(entry.slot, ReleaseArtifactSlot::ChecksumManifest { .. }))
        .unwrap()
        .digest = ArtifactDigest::from_bytes("forged");
    assert!(forged_checksum.validate_for_intent(&intent).is_err());
    let mut metadata_wire = serde_json::to_value(metadata).unwrap();
    metadata_wire["unknown"] = serde_json::Value::Bool(true);
    assert!(matches!(
        ReleaseDistributionMetadataV1::from_canonical_json(&serde_json::to_vec(&metadata_wire).unwrap()),
        Err(SuccessorError::InvalidMetadata)
    ));
}

#[test]
fn checksum_roster_covers_every_registry_and_product_payload_plus_metadata() {
    let intent = intent_with_source_and_registry(commit(), true);
    let entries = payload_entries_for(&intent);
    let payloads = ValidatedPayloadEntries::new(&intent, entries.clone()).unwrap();
    let bundle = ReleaseArtifactManifest::complete_with_generated_files(&intent, &payloads).unwrap();
    let checksum = std::str::from_utf8(bundle.checksum_bytes()).unwrap();
    assert_eq!(checksum.lines().count(), payloads.entries().len() + 1);
    for entry in payloads.entries() {
        assert!(checksum.lines().any(|line| line.ends_with(entry.slot().file_name())));
    }
    assert!(checksum.lines().any(|line| line.ends_with(METADATA_FILE_NAME)));
    assert!(!checksum.lines().any(|line| line.ends_with(CHECKSUM_FILE_NAME)));

    let mut missing = entries.clone();
    missing.pop();
    assert!(matches!(
        ValidatedPayloadEntries::new(&intent, missing),
        Err(SuccessorError::MismatchedManifest)
    ));
    let mut duplicate = entries;
    duplicate.push(duplicate[0].clone());
    assert!(matches!(
        ValidatedPayloadEntries::new(&intent, duplicate),
        Err(SuccessorError::MismatchedManifest)
    ));
}

