#[test]
fn manifest_metadata_and_checksum_are_bound_without_circularity() {
    let intent = intent();
    let entries = intent
        .slots
        .iter()
        .filter(|slot| {
            matches!(
                slot,
                ReleaseArtifactSlot::RegistryPackage { .. } | ReleaseArtifactSlot::ProductAsset { .. }
            )
        })
        .cloned()
        .map(|slot| ReleaseArtifactEntry {
            digest: ArtifactDigest::from_bytes(slot.file_name().as_bytes()),
            byte_length: slot.file_name().len() as u64,
            source_commit: commit(),
            provenance: slot.policy().clone(),
            slot,
        })
        .collect::<Vec<_>>();
    let payloads = ValidatedPayloadEntries::new(&intent, entries).unwrap();
    let other_intent = ReleaseIntent::new(
        intent.decision.clone(),
        intent.product_release.clone(),
        CommitSha::parse(&"b".repeat(40)).unwrap(),
        intent.destination.clone(),
        intent.registry_artifacts.clone(),
        intent.operations.clone(),
        intent.slots.clone(),
    )
    .unwrap();
    assert!(ReleaseDistributionMetadataV1::from_payloads(&other_intent, &payloads).is_err());
    let metadata = ReleaseDistributionMetadataV1::from_payloads(&intent, &payloads).unwrap();
    let bundle = ReleaseArtifactManifest::complete_with_generated_files(&intent, &payloads).unwrap();
    let manifest = bundle.manifest().clone();
    assert_eq!(manifest.entries.len(), 6);
    assert!(manifest.validate_for_intent(&intent).is_ok());
    assert_eq!(
        ReleaseDistributionMetadataV1::from_canonical_json(bundle.metadata_bytes()).unwrap(),
        metadata
    );
    let metadata_entry = manifest
        .entries()
        .iter()
        .find(|entry| matches!(entry.slot(), ReleaseArtifactSlot::ReleaseMetadata { .. }))
        .unwrap();
    assert_eq!(
        metadata_entry.digest(),
        &ArtifactDigest::from_bytes(bundle.metadata_bytes())
    );
    assert_eq!(metadata_entry.byte_length(), bundle.metadata_bytes().len() as u64);
    let checksum_entry = manifest
        .entries()
        .iter()
        .find(|entry| matches!(entry.slot(), ReleaseArtifactSlot::ChecksumManifest { .. }))
        .unwrap();
    assert_eq!(
        checksum_entry.digest(),
        &ArtifactDigest::from_bytes(bundle.checksum_bytes())
    );
    assert_eq!(checksum_entry.byte_length(), bundle.checksum_bytes().len() as u64);
    let checksum_text = std::str::from_utf8(bundle.checksum_bytes()).unwrap();
    assert_eq!(checksum_text.lines().count(), 5);
    assert!(checksum_text.contains(METADATA_FILE_NAME));
    assert!(!checksum_text.contains(CHECKSUM_FILE_NAME));
    assert_eq!(
        serde_json::from_value::<ReleaseArtifactManifest>(serde_json::to_value(&manifest).unwrap()).unwrap(),
        manifest
    );
    assert_eq!(
        ReleaseDistributionMetadataV1::from_canonical_json(&metadata.canonical_json()).unwrap(),
        metadata
    );
    let pretty = serde_json::to_vec_pretty(&metadata).unwrap();
    assert!(matches!(
        ReleaseDistributionMetadataV1::from_canonical_json(&pretty),
        Err(SuccessorError::NonCanonicalMetadataBytes)
    ));
    let value = serde_json::to_value(&metadata).unwrap();
    let reordered = format!(
        "{{\"sourceCommit\":{},\"schemaVersion\":1,\"productRelease\":{},\"intentDigest\":{},\"payloads\":{},\"verificationPolicy\":{}}}",
        serde_json::to_string(&value["sourceCommit"]).unwrap(),
        serde_json::to_string(&value["productRelease"]).unwrap(),
        serde_json::to_string(&value["intentDigest"]).unwrap(),
        serde_json::to_string(&value["payloads"]).unwrap(),
        serde_json::to_string(&value["verificationPolicy"]).unwrap(),
    );
    assert!(matches!(
        ReleaseDistributionMetadataV1::from_canonical_json(reordered.as_bytes()),
        Err(SuccessorError::NonCanonicalMetadataBytes)
    ));
    let mut forged = manifest.clone();
    forged.entries[0].source_commit = CommitSha::parse(&"b".repeat(40)).unwrap();
    assert!(forged.validate_for_intent(&intent).is_err());
    let mut forged_metadata = manifest.clone();
    forged_metadata
        .entries
        .iter_mut()
        .find(|entry| matches!(entry.slot, ReleaseArtifactSlot::ReleaseMetadata { .. }))
        .unwrap()
        .byte_length += 1;
    assert!(forged_metadata.validate_for_intent(&intent).is_err());
    let mut forged_checksum = manifest.clone();
    forged_checksum
        .entries
        .iter_mut()
        .find(|entry| matches!(entry.slot, ReleaseArtifactSlot::ChecksumManifest { .. }))
        .unwrap()
        .digest = ArtifactDigest::from_bytes("forged");
    assert!(forged_checksum.validate_for_intent(&intent).is_err());
    let mut metadata_wire = serde_json::to_value(metadata).unwrap();
    metadata_wire["unknown"] = serde_json::Value::Bool(true);
    assert!(matches!(
        ReleaseDistributionMetadataV1::from_canonical_json(&serde_json::to_vec(&metadata_wire).unwrap()),
        Err(SuccessorError::InvalidMetadata)
    ));
}

