#[cfg(test)]
mod tests {
    use super::*;

    fn commit() -> CommitSha {
        CommitSha::parse(&"a".repeat(40)).unwrap()
    }

    fn policy() -> ProvenancePolicy {
        policy_for("callisto-rs/callisto")
    }

    fn policy_for(repository: &str) -> ProvenancePolicy {
        ProvenancePolicy::new(
            GitHubRepository::parse(repository).unwrap(),
            ".github/workflows/callisto-release.yml",
            commit(),
        )
        .unwrap()
    }

    fn release() -> ProductReleaseId {
        ProductReleaseId::from_coordinated_versions(
            ProductName::parse("callisto").unwrap(),
            [Version::semver(1, 2, 3), Version::semver(1, 2, 3)],
        )
        .unwrap()
    }

    fn slots(release: &ProductReleaseId) -> Vec<ReleaseArtifactSlot> {
        ProductTarget::ALL
            .iter()
            .map(|target| ReleaseArtifactSlot::product_asset(release.clone(), *target, policy()))
            .chain([
                ReleaseArtifactSlot::checksum_manifest(release.clone(), policy()),
                ReleaseArtifactSlot::release_metadata(release.clone(), policy()),
            ])
            .collect()
    }

    fn registry_binding() -> RegistryBindingId {
        RegistryBindingId::new(
            "cratesIo",
            RegistryBindingDigest::from_normalized_binding("https://index.crates.io/"),
        )
        .unwrap()
    }

    fn destination() -> ReleaseDestinationBinding {
        ReleaseDestinationBinding::new(
            "production",
            ReleaseDestinationKind::Production,
            GitHubRepository::parse("callisto-rs/callisto").unwrap(),
            registry_binding(),
            RegistryBindingId::new(
                "npm",
                RegistryBindingDigest::from_normalized_binding("https://registry.npmjs.org/"),
            )
            .unwrap(),
            RegistryBindingId::new(
                "pypi",
                RegistryBindingDigest::from_normalized_binding("https://upload.pypi.org/legacy/"),
            )
            .unwrap(),
        )
        .unwrap()
    }

    fn decision_for(
        release: &ProductReleaseId,
        packages: impl IntoIterator<Item = ReleasePackageId>,
    ) -> ReleaseDecisionV1 {
        ReleaseDecisionV1::new(
            packages
                .into_iter()
                .map(|package| ReleaseDecisionEntry {
