        let tag = ReleaseOperationId::ProductTag {
            release: release.clone(),
            tag: release.tag(),
        };
        let prepare = ReleaseOperationId::ForgePrepare {
            release: release.clone(),
            repository: GitHubRepository::parse("owner/repository").unwrap(),
        };
        let mut uploads = slots
            .iter()
            .map(|slot| {
                ReleaseOperation::new(
                    ReleaseOperationId::ArtifactUpload {
                        release: release.clone(),
                        slot: slot.clone(),
                    },
                    vec![prepare.clone()],
                )
                .unwrap()
            })
            .collect::<Vec<_>>();
        uploads.sort_by(|left, right| left.id().cmp(right.id()));
        let upload_ids = uploads.iter().map(|operation| operation.id().clone()).collect();
        let mut result = vec![
            ReleaseOperation::new(tag.clone(), vec![]).unwrap(),
            ReleaseOperation::new(prepare, vec![tag]).unwrap(),
        ];
        result.extend(uploads);
        result.push(
            ReleaseOperation::new(
                ReleaseOperationId::ForgePublish {
                    release: release.clone(),
                    repository: GitHubRepository::parse("owner/repository").unwrap(),
                },
                upload_ids,
