fn snapshot_verified_entry(
    artifact_root: &Path,
    slot: &ReleaseArtifactSlot,
    expected: &ValidatedArtifactEntry,
) -> Result<ArtifactSnapshot, GraphError> {
    let path = resolve_asset_path(artifact_root, slot.file_name())?;
    if path != expected.path {
        return Err(GraphError::UnsafeArtifactPath {
            path,
            reason: "artifact path changed after validation",
        });
    }
    let bytes = fs::read(&path).map_err(|error| GraphError::ArtifactRead {
        path: path.clone(),
        message: error.to_string(),
    })?;
    if ArtifactDigest::from_bytes(&bytes) != expected.digest || bytes.len() as u64 != expected.byte_length {
        return Err(GraphError::ArtifactBytesMismatch { path });
    }
    Ok(ArtifactSnapshot {
        slot: slot.clone(),
        bytes,
    })
}

/// Verifies every manifest entry against the exact artifact directory.
///
/// The artifact directory and every candidate are canonicalized, and symbolic
/// links are rejected, so a manifest asset name cannot escape the supplied
/// build-output directory. Each asset is streamed once for a bounded-memory
/// SHA-256 and size comparison. `gh attestation verify` then validates the
/// repository, workflow path and commit, source commit, and hosted-runner
    fn write_fixture(fixture: &Fixture, root: &Path) {
        for (slot, bytes) in &fixture.files {
            fs::write(root.join(slot.file_name()), bytes).unwrap();
        }
    }

    #[test]
    fn verifies_complete_roster_and_pinned_github_policy() {
        let fixture = fixture('a');
        let directory = tempdir().unwrap();
        write_fixture(&fixture, directory.path());
        let runner = RecordingRunner::default();

        let (_, root, entries) =
            verify_artifact_manifest_for_intent(&fixture.intent, fixture.manifest, directory.path(), &runner).unwrap();
        let calls = runner.calls.lock().unwrap();
        assert_eq!(calls.len(), fixture.files.len());
        assert!(calls.iter().all(|(program, args)| {
            program == "gh"
                && args.windows(2).any(|pair| pair == ["--repo", "owner/repository"])
                && args
                    .windows(2)
                    .any(|pair| pair == ["--signer-workflow", "owner/repository/.github/workflows/release.yml"])
                && args
                    .windows(2)
                    .any(|pair| pair == ["--signer-digest", "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"])
                && args
                    .windows(2)
                    .any(|pair| pair == ["--source-digest", "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"])
                && args.contains(&"--deny-self-hosted-runners".to_owned())
        }));
        drop(calls);

        let slot = fixture.files.keys().next().unwrap();
        let snapshot = snapshot_verified_entry(&root, slot, &entries[slot]).unwrap();
        assert_eq!(snapshot.slot(), slot);
        assert_eq!(snapshot.bytes(), fixture.files[slot]);
    }

    #[test]
    fn final_corrupt_entry_prevents_every_attestation_lookup() {
        let fixture = fixture('a');
        let directory = tempdir().unwrap();
        write_fixture(&fixture, directory.path());
        let final_entry = fixture.manifest.entries().last().unwrap();
        fs::write(
            directory.path().join(final_entry.slot().file_name()),
            b"corrupt final entry",
        )
        .unwrap();
        let runner = RecordingRunner::default();

        assert!(matches!(
            verify_artifact_manifest_for_intent(&fixture.intent, fixture.manifest, directory.path(), &runner),
            Err(GraphError::ArtifactBytesMismatch { .. })
        ));
        assert!(runner.calls.lock().unwrap().is_empty());
    }

