    fn rejects_manifest_bound_to_another_intent_before_attestation() {
        let fixture = fixture('a');
        let other_intent = intent('c');
        let directory = tempdir().unwrap();
        write_fixture(&fixture, directory.path());
        let runner = RecordingRunner::default();

        assert!(matches!(
            verify_artifact_manifest_for_intent(&other_intent, fixture.manifest, directory.path(), &runner),
            Err(GraphError::ArtifactManifest { .. })
        ));
        assert!(runner.calls.lock().unwrap().is_empty());
    }

