    fn snapshot_rejects_bytes_changed_after_validation() {
        let fixture = fixture('a');
        let directory = tempdir().unwrap();
        write_fixture(&fixture, directory.path());
        let runner = RecordingRunner::default();
        let (_, root, entries) =
            verify_artifact_manifest_for_intent(&fixture.intent, fixture.manifest, directory.path(), &runner).unwrap();
        let slot = fixture.files.keys().next().unwrap();
        fs::write(root.join(slot.file_name()), b"changed after validation").unwrap();

        assert!(matches!(
            snapshot_verified_entry(&root, slot, &entries[slot]),
            Err(GraphError::ArtifactBytesMismatch { .. })
        ));
    }

    #[test]
    fn snapshot_rejects_slot_drift() {
        let fixture = fixture('a');
        let directory = tempdir().unwrap();
        write_fixture(&fixture, directory.path());
        let runner = RecordingRunner::default();
        let (_, root, entries) =
