        let mut slots = fixture.files.keys();
        let expected_slot = slots.next().unwrap();
        let different_slot = slots.next().unwrap();

        assert!(matches!(
            snapshot_verified_entry(&root, different_slot, &entries[expected_slot]),
            Err(GraphError::UnsafeArtifactPath { .. })
        ));
    }

