/// Process-backed adapter used only by direct native [`GitRepository`]
/// remote calls. Production code should use [`GitAccess`], which passes the
/// caller's own command runner to [`ShellGit`] instead.
#[cfg(not(target_arch = "wasm32"))]
struct NativeCommandRunner;

#[cfg(not(target_arch = "wasm32"))]
impl callisto_model::CommandRunner for NativeCommandRunner {
    fn run(&self, program: &str, args: &[&str], cwd: &Path) -> Result<callisto_model::CommandOutput, CommandError> {
        let output = std::process::Command::new(program)
            .args(args)
            .current_dir(cwd)
            .output()
            .map_err(|error| CommandError::Io {
                program: program.to_string(),
                message: error.to_string(),
            })?;
        Ok(callisto_model::CommandOutput {
            exit_code: output.status.code(),
            stdout: String::from_utf8_lossy(&output.stdout).into_owned(),
            stderr: String::from_utf8_lossy(&output.stderr).into_owned(),
        })
    }
}

/// Diffs `commit_obj`'s tree against its first parent's tree (or the empty
/// tree, for a root commit) and reports whether any changed path falls
/// under one of `pathspecs`.
#[cfg(not(target_arch = "wasm32"))]
fn commit_touches_pathspecs(
    repo: &gix::Repository,
    info: &gix::revision::walk::Info<'_>,
    commit_obj: &gix::Commit<'_>,
    pathspecs: &[PathBuf],
) -> Result<bool, VcsError> {
    let commit_tree = commit_obj
        .tree()
        .map_err(|e| VcsError::Git(format!("Failed to load commit tree: {e}")))?;

    let parent_tree = match info.parent_ids().next() {
        Some(parent_id) => {
            let parent_commit = parent_id
                .object()
        if let Some(repo) = &self.native {
            if let Ok(value) = native(repo) {
                return Ok(value);
            }
        }
        shell()
    }
}

impl GitDataSource for GitAccess<'_> {
    fn head_sha(&self) -> Result<CommitSha, VcsError> {
        self.read_with_fallback(|repo| repo.head_sha(), || self.shell.head_sha())
    }

    fn list_tags(&self, glob: Option<&str>) -> Result<Vec<TagName>, VcsError> {
        self.read_with_fallback(|repo| repo.list_tags(glob), || self.shell.list_tags(glob))
    }

    fn resolve_commit(&self, refname: &str) -> Result<Option<CommitSha>, VcsError> {
        self.read_with_fallback(
            |repo| repo.resolve_commit(refname),
            || self.shell.resolve_commit(refname),
        )
    }

    fn commits_since(&self, since_ref: Option<&str>, pathspecs: &[PathBuf]) -> Result<Vec<GitCommit>, VcsError> {
        self.read_with_fallback(
            |repo| repo.commits_since(since_ref, pathspecs),
            || self.shell.commits_since(since_ref, pathspecs),
        )
    }

    fn create_tag(
        &self,
        name: &str,
        target_sha: &CommitSha,
        message: Option<&str>,
        sign: crate::TagSignPolicy,
        permit: &ApplyPermit,
    ) -> Result<(), VcsError> {
        if let Some(repo) = &self.native {
            // Authoritative: a genuine gix failure must not be masked by
            // silently retrying through the shell.
            return repo.create_tag(name, target_sha, message, sign, permit);
        }
        self.shell.create_tag(name, target_sha, message, sign, permit)
    }

    fn create_floating_major(
        &self,
        major_name: &str,
        target_sha: &CommitSha,
        permit: &ApplyPermit,
    ) -> Result<(), VcsError> {
        if let Some(repo) = &self.native {
            return repo.create_floating_major(major_name, target_sha, permit);
        }
        self.shell.create_floating_major(major_name, target_sha, permit)
    }

    fn observe_remote_annotated_tag(
        &self,
        remote: &str,
        name: &TagName,
        target_sha: &CommitSha,
        annotation_digest: &TagAnnotationDigest,
    ) -> Result<RemoteAnnotatedTagObservation, VcsError> {
        // The invocation-owned ShellGit is canonical here. It preserves the
        // caller's command-routing/credential policy while using the same
        // fetch-and-readback protocol that direct GitRepository calls share.
        self.shell
            .observe_remote_annotated_tag(remote, name, target_sha, annotation_digest)
    }

    fn push_annotated_tag_and_confirm(
        &self,
        remote: &str,
        name: &TagName,
        target_sha: &CommitSha,
        annotation_digest: &TagAnnotationDigest,
        permit: &ApplyPermit,
    ) -> Result<RemoteAnnotatedTagObservation, VcsError> {
        // Push is a mutation and must be paired with the shell transport's
        // mandatory remote readback. Do not try native first: gix cannot
        // provide that paired protocol, and a retry could double-apply it.
        self.shell
            .push_annotated_tag_and_confirm(remote, name, target_sha, annotation_digest, permit)
    }
}

