            },
        ) if release == evidence_release && asset_roster_digest == &expected.asset_roster_digest => Ok(()),
        (
            ReleaseOperationId::ArtifactUpload { release, slot },
            ReleaseObservationEvidence::ForgeAsset {
                schema_version: 1,
                release: evidence_release,
                slot: evidence_slot,
                digest,
                byte_length,
            },
        ) if release == evidence_release
            && slot == evidence_slot
            && expected.entries.get(slot) == Some(&(digest.clone(), *byte_length)) =>
        {
            Ok(())
        }
