            if !format_matches_ecosystem(format, package.ecosystem()) {
                return Err(SuccessorError::RegistryFormatMismatch);
            }
            if publication_policy.ecosystem() != package.ecosystem() {
                return Err(SuccessorError::RegistryPublicationPolicyMismatch);
            }
            let file_name = file_name.into();
            if !is_safe_artifact_component(&file_name) || !format_matches_file_name(format, &file_name) {
                return Err(SuccessorError::UnsafeRegistryArtifactFileName);
            }
            Ok(Self {
                package,
                registry,
                format,
                publication_policy,
                file_name,
            })
        }

        pub fn package(&self) -> &ReleasePackageId {
            &self.package
        }

        pub fn registry(&self) -> &RegistryBindingId {
            &self.registry
        }

        pub fn format(&self) -> RegistryArtifactFormat {
            self.format
        }

        pub fn publication_policy(&self) -> &RegistryPublicationPolicy {
            &self.publication_policy
        }

        pub fn file_name(&self) -> &str {
            &self.file_name
        }
    }

