//! Unified read-only observation of prepared release operations.
//!
//! External state is authoritative. This module deliberately preserves the
//! distinction between absence, a verified exact subset, conflict, and an
//! inability to prove state. It owns no provider mutation path.

use std::{
    collections::{BTreeMap, BTreeSet},
    path::Path,
    time::Duration,
};

use callisto_model::{
    normalize_pypi_package_name, ArtifactDigest, CommandOutput, ForgePrepareLifecycle, GitHubRepository,
    ProductReleaseId, RegistryArtifactFormat, ReleaseArtifactSlot, ReleaseObservationEvidence, ReleaseOperationId,
    ReleasePackageId, TagName, Version,
};
use callisto_vcs::{
    GitAccess, GitDataSource, RemoteAnnotatedTagConflict, RemoteAnnotatedTagObservation, TagAnnotationDigest,
};

use super::{
    release::{PreparedOperationView, PreparedRegistryEndpointsView, ValidatedReleaseIntent},
    release_artifacts::ValidatedArtifactManifest,
};

const OBSERVATION_TIMEOUT: Duration = Duration::from_secs(120);

/// One independently actionable piece of provider work proven to be missing.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub(super) enum MissingWork {
    RegistryArtifact(ReleaseArtifactSlot),
    ForgeAsset(ReleaseArtifactSlot),
    PublishForgeRelease(ProductReleaseId),
}

/// Exact provider facts already present plus the closed work still missing.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(super) struct VerifiedPartialEvidence {
    exact: Vec<ReleaseObservationEvidence>,
    missing: BTreeSet<MissingWork>,
}

impl VerifiedPartialEvidence {
    fn new(exact: Vec<ReleaseObservationEvidence>, missing: BTreeSet<MissingWork>) -> Self {
        debug_assert!(!missing.is_empty());
        Self { exact, missing }
    }

    pub(super) fn exact(&self) -> &[ReleaseObservationEvidence] {
        &self.exact
    }

    pub(super) fn missing(&self) -> &BTreeSet<MissingWork> {
        &self.missing
    }
}

/// Closed reasons why a named external object cannot satisfy the intent.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(super) enum ExternalConflict {
    RemoteTag(RemoteAnnotatedTagConflict),
    RemoteTagMissingForForge,
    RegistryDigest {
        slot: ReleaseArtifactSlot,
        observed: ArtifactDigest,
    },
    RegistryLength {
        slot: ReleaseArtifactSlot,
        observed: u64,
    },
    UnexpectedRegistryDistribution {
        package: ReleasePackageId,
        version: Version,
        file_name: String,
    },
    ForgeReleaseTag,
    ForgeAssetDigest {
        slot: ReleaseArtifactSlot,
        observed: ArtifactDigest,
    },
    ForgeAssetLength {
        slot: ReleaseArtifactSlot,
        observed: u64,
    },
    UnexpectedForgeAsset {
        file_name: String,
    },
    PublishedReleaseIncomplete {
        release: ProductReleaseId,
    },
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) enum ObservationProvider {
    Git,
    GitHub,
    Cargo,
    Npm,
    Pypi,
    ArtifactCapability,
    PreparedCapability,
}

/// Closed provider-failure taxonomy. Raw provider output is intentionally not
/// retained: stderr can contain credentials and is not durable evidence.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(super) enum ObservationFailure {
    Command {
        provider: ObservationProvider,
    },
    HttpStatus {
        provider: ObservationProvider,
        status: u16,
    },
    MalformedResponse {
        provider: ObservationProvider,
    },
    MissingDigest {
        provider: ObservationProvider,
        file_name: String,
    },
    Capability {
        provider: ObservationProvider,
    },
}

/// The only observation vocabulary consumed by convergence.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(super) enum OperationObservation {
    Absent,
    Incomplete(VerifiedPartialEvidence),
    Exact(ReleaseObservationEvidence),
    Conflict(ExternalConflict),
    Unverifiable(ObservationFailure),
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct GitHubAsset {
    digest: Option<ArtifactDigest>,
    byte_length: u64,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct GitHubRelease {
    draft: bool,
    assets: BTreeMap<String, GitHubAsset>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct PypiDistribution {
    digest: ArtifactDigest,
    byte_length: u64,
}

type CachedObservation<T> = Result<Option<T>, ObservationFailure>;

/// Invocation-local provider cache. A convergence pass shares one session so
/// every GitHub operation sees one release/asset snapshot and every PyPI
/// operation for a version sees one distribution roster.
#[derive(Default)]
pub(super) struct ObservationSession {
    github_releases: BTreeMap<(String, String), CachedObservation<GitHubRelease>>,
    pypi_versions: BTreeMap<(String, String, String), CachedObservation<BTreeMap<String, PypiDistribution>>>,
}

/// Observes exactly one operation from the immutable prepared capability.
pub(super) fn observe_prepared(
    session: &mut ObservationSession,
    artifacts: &ValidatedArtifactManifest<'_, '_>,
    id: &ReleaseOperationId,
) -> OperationObservation {
    let validated = artifacts.validated_intent();
    let Some(prepared) = validated.prepared_operation(id) else {
        return OperationObservation::Unverifiable(ObservationFailure::Capability {
            provider: ObservationProvider::PreparedCapability,
        });
    };
    match (id, prepared) {
        (
            ReleaseOperationId::RegistryArtifactPublish {
                package,
                version,
                registry,
                slot,
            },
            PreparedOperationView::RegistryArtifactPublish {
                artifact,
                binding_digest,
                endpoints,
                ..
            },
        ) if artifact.package() == package
            && artifact.registry() == registry
            && registry.binding_digest() == binding_digest
            && artifact.file_name() == slot.file_name() => observe_registry(
                session, artifacts, validated, package, version, registry.clone(), slot, endpoints,
            ),
        (
            ReleaseOperationId::ProductTag { release, .. },
            PreparedOperationView::ProductTag {
                name,
                target,
                annotation,
                remote_name,
                ..
            },
        ) => observe_tag(
            artifacts,
            validated,
            release,
            name,
            target,
            annotation,
            remote_name,
        ),
        (
            ReleaseOperationId::ForgePrepare { release, .. },
            PreparedOperationView::ForgePrepare { repository, tag },
        ) => observe_forge_prepare(session, artifacts, validated, release, repository, tag),
        (
            ReleaseOperationId::ArtifactUpload { release, slot },
            PreparedOperationView::ArtifactUpload { slot: prepared_slot },
        ) if slot == prepared_slot => observe_forge_asset(session, artifacts, validated, release, slot),
        (
            ReleaseOperationId::ForgePublish { release, .. },
            PreparedOperationView::ForgePublish { repository, tag },
        ) => observe_forge_publish(session, artifacts, validated, release, repository, tag),
        _ => OperationObservation::Unverifiable(ObservationFailure::Capability {
            provider: ObservationProvider::PreparedCapability,
        }),
    }
}

fn observe_tag(
    artifacts: &ValidatedArtifactManifest<'_, '_>,
    validated: &ValidatedReleaseIntent<'_>,
    release: &ProductReleaseId,
    name: &TagName,
    target: &callisto_model::CommitSha,
    annotation: &str,
    remote_name: &str,
) -> OperationObservation {
    let expected_annotation = TagAnnotationDigest::from_annotation(annotation);
    match GitAccess::discover(validated.root(), validated.runner()).observe_remote_annotated_tag(
        remote_name,
        name,
        target,
        &expected_annotation,
    ) {
        Ok(RemoteAnnotatedTagObservation::Absent) => OperationObservation::Absent,
        Ok(RemoteAnnotatedTagObservation::Conflict(conflict)) => {
            OperationObservation::Conflict(ExternalConflict::RemoteTag(conflict))
        }
        Ok(RemoteAnnotatedTagObservation::Exact) => {
            let expectations = artifacts.expectations();
            OperationObservation::Exact(ReleaseObservationEvidence::remote_tag(
                release.clone(),
                name.as_str(),
                target.clone(),
                expectations.tag_annotation_digest().clone(),
            ))
        }
        Err(_) => OperationObservation::Unverifiable(ObservationFailure::Command {
            provider: ObservationProvider::Git,
        }),
    }
}

fn observe_registry(
    session: &mut ObservationSession,
    artifacts: &ValidatedArtifactManifest<'_, '_>,
    validated: &ValidatedReleaseIntent<'_>,
    package: &ReleasePackageId,
    version: &Version,
    registry: callisto_model::RegistryBindingId,
    slot: &ReleaseArtifactSlot,
    endpoints: PreparedRegistryEndpointsView<'_>,
) -> OperationObservation {
    let snapshot = match artifacts.snapshot(slot) {
        Ok(snapshot) => snapshot,
        Err(_) => {
            return OperationObservation::Unverifiable(ObservationFailure::Capability {
                provider: ObservationProvider::ArtifactCapability,
            })
        }
    };
    let expected_digest = ArtifactDigest::from_bytes(snapshot.bytes());
    let expected_length = snapshot.bytes().len() as u64;
    let exact = || {
        OperationObservation::Exact(ReleaseObservationEvidence::registry_artifact(
            package.clone(),
            version.clone(),
            registry.clone(),
            slot.clone(),
            expected_digest.clone(),
            expected_length,
        ))
    };

    match endpoints {
        PreparedRegistryEndpointsView::Cargo { api, .. } => {
            let url = match cargo_metadata_url(api, package.name(), version) {
                Some(url) => url,
                None => return malformed(ObservationProvider::Cargo),
            };
            match observe_json_http(validated.runner(), validated.root(), &url, ObservationProvider::Cargo) {
                Ok(None) => OperationObservation::Absent,
                Ok(Some(value)) => {
                    let Some(raw_digest) = value
                        .get("version")
                        .and_then(|version| version.get("checksum"))
                        .and_then(serde_json::Value::as_str)
                    else {
                        return malformed(ObservationProvider::Cargo);
                    };
                    let Ok(observed) = ArtifactDigest::parse(raw_digest) else {
                        return malformed(ObservationProvider::Cargo);
                    };
                    if observed == expected_digest {
                        exact()
                    } else {
                        OperationObservation::Conflict(ExternalConflict::RegistryDigest {
                            slot: slot.clone(),
                            observed,
                        })
                    }
                }
                Err(failure) => OperationObservation::Unverifiable(failure),
            }
        }
        PreparedRegistryEndpointsView::Npm { registry: registry_url } => {
            match observe_npm_bytes(validated, package.name(), version, registry_url) {
                Ok(None) => OperationObservation::Absent,
                Ok(Some(bytes)) if bytes.len() as u64 != expected_length => {
                    OperationObservation::Conflict(ExternalConflict::RegistryLength {
                        slot: slot.clone(),
                        observed: bytes.len() as u64,
                    })
                }
                Ok(Some(bytes)) => {
                    let observed = ArtifactDigest::from_bytes(bytes);
                    if observed == expected_digest {
                        exact()
                    } else {
                        OperationObservation::Conflict(ExternalConflict::RegistryDigest {
                            slot: slot.clone(),
                            observed,
                        })
                    }
                }
                Err(failure) => OperationObservation::Unverifiable(failure),
            }
        }
        PreparedRegistryEndpointsView::Pypi { metadata, .. } => observe_pypi(
            session,
            artifacts,
            validated,
            package,
            version,
            registry,
            slot,
            metadata,
        ),
    }
}

fn observe_pypi(
    session: &mut ObservationSession,
    artifacts: &ValidatedArtifactManifest<'_, '_>,
    validated: &ValidatedReleaseIntent<'_>,
    package: &ReleasePackageId,
    version: &Version,
    registry: callisto_model::RegistryBindingId,
    current_slot: &ReleaseArtifactSlot,
    metadata_endpoint: &str,
) -> OperationObservation {
    let normalized = normalize_pypi_package_name(package.name());
    let key = (
        metadata_endpoint.to_string(),
        normalized.clone(),
        version.render(),
    );
    let observed = session
        .pypi_versions
        .entry(key)
        .or_insert_with(|| fetch_pypi_version(validated, metadata_endpoint, &normalized, version))
        .clone();
    let Some(distributions) = (match observed {
        Ok(value) => value,
        Err(failure) => return OperationObservation::Unverifiable(failure),
    }) else {
        return OperationObservation::Absent;
    };

    let expected_slots = validated
        .intent()
        .operations()
        .iter()
        .filter_map(|operation| match operation.id() {
            ReleaseOperationId::RegistryArtifactPublish {
                package: candidate_package,
                version: candidate_version,
                registry: candidate_registry,
                slot,
            } if candidate_package == package && candidate_version == version && candidate_registry == &registry => {
                Some(slot.clone())
            }
            _ => None,
        })
        .collect::<Vec<_>>();
    let expected_names = expected_slots
        .iter()
        .map(|slot| slot.file_name().to_string())
        .collect::<BTreeSet<_>>();
    if let Some(file_name) = distributions.keys().find(|name| !expected_names.contains(*name)) {
        return OperationObservation::Conflict(ExternalConflict::UnexpectedRegistryDistribution {
            package: package.clone(),
            version: version.clone(),
            file_name: file_name.clone(),
        });
    }

    let expectations = artifacts.expectations();
    let mut exact = Vec::new();
    let mut missing = BTreeSet::new();
    for slot in expected_slots {
        let Some(observed) = distributions.get(slot.file_name()) else {
            missing.insert(MissingWork::RegistryArtifact(slot));
            continue;
        };
        let Some((expected_digest, expected_length)) = expectations.artifact(&slot) else {
            return OperationObservation::Unverifiable(ObservationFailure::Capability {
                provider: ObservationProvider::ArtifactCapability,
            });
        };
        if observed.byte_length != expected_length {
            return OperationObservation::Conflict(ExternalConflict::RegistryLength {
                slot,
                observed: observed.byte_length,
            });
        }
        if &observed.digest != expected_digest {
            return OperationObservation::Conflict(ExternalConflict::RegistryDigest {
                slot,
                observed: observed.digest.clone(),
            });
        }
        exact.push(ReleaseObservationEvidence::registry_artifact(
            package.clone(),
            version.clone(),
            registry.clone(),
            slot,
            expected_digest.clone(),
            expected_length,
        ));
    }
    if missing.is_empty() {
        let evidence = exact
            .into_iter()
            .find(|evidence| matches!(evidence, ReleaseObservationEvidence::RegistryArtifact { slot, .. } if slot == current_slot))
            .expect("validated PyPI roster includes the current operation slot");
        OperationObservation::Exact(evidence)
    } else if exact.is_empty() {
        OperationObservation::Absent
    } else {
        OperationObservation::Incomplete(VerifiedPartialEvidence::new(exact, missing))
    }
}

fn observe_forge_prepare(
    session: &mut ObservationSession,
    artifacts: &ValidatedArtifactManifest<'_, '_>,
    validated: &ValidatedReleaseIntent<'_>,
    release: &ProductReleaseId,
    repository: &GitHubRepository,
    tag: &TagName,
) -> OperationObservation {
    if let Some(failure) = require_exact_remote_tag(artifacts, validated) {
        return failure;
    }
    match github_release(session, validated, repository, tag) {
        Ok(None) => OperationObservation::Absent,
        Ok(Some(observed)) => OperationObservation::Exact(ReleaseObservationEvidence::forge_prepare(
            release.clone(),
            if observed.draft {
                ForgePrepareLifecycle::Draft
            } else {
                ForgePrepareLifecycle::PublishedSuccessor
            },
        )),
        Err(failure) => OperationObservation::Unverifiable(failure),
    }
}

fn observe_forge_asset(
    session: &mut ObservationSession,
    artifacts: &ValidatedArtifactManifest<'_, '_>,
    validated: &ValidatedReleaseIntent<'_>,
    release: &ProductReleaseId,
    slot: &ReleaseArtifactSlot,
) -> OperationObservation {
    if let Some(failure) = require_exact_remote_tag(artifacts, validated) {
        return failure;
    }
    let repository = validated.intent().destination().forge_repository();
    let tag = release.tag();
    let Ok(tag) = TagName::parse(tag) else {
        return malformed(ObservationProvider::PreparedCapability);
    };
    let observed = match github_release(session, validated, repository, &tag) {
        Ok(Some(observed)) => observed,
        Ok(None) => return OperationObservation::Absent,
        Err(failure) => return OperationObservation::Unverifiable(failure),
    };
    let Some(asset) = observed.assets.get(slot.file_name()) else {
        return OperationObservation::Absent;
    };
    compare_forge_asset(artifacts, release, slot, asset)
}

fn observe_forge_publish(
    session: &mut ObservationSession,
    artifacts: &ValidatedArtifactManifest<'_, '_>,
    validated: &ValidatedReleaseIntent<'_>,
    release: &ProductReleaseId,
    repository: &GitHubRepository,
    tag: &TagName,
) -> OperationObservation {
    if let Some(failure) = require_exact_remote_tag(artifacts, validated) {
        return failure;
    }
    let observed = match github_release(session, validated, repository, tag) {
        Ok(Some(observed)) => observed,
        Ok(None) => return OperationObservation::Absent,
        Err(failure) => return OperationObservation::Unverifiable(failure),
    };
    let expected_slots = validated
        .intent()
        .slots()
        .iter()
        .filter(|slot| slot.release() == Some(release))
        .cloned()
        .collect::<Vec<_>>();
    let expected_names = expected_slots
        .iter()
        .map(|slot| slot.file_name().to_string())
        .collect::<BTreeSet<_>>();
    if let Some(file_name) = observed.assets.keys().find(|name| !expected_names.contains(*name)) {
        return OperationObservation::Conflict(ExternalConflict::UnexpectedForgeAsset {
            file_name: file_name.clone(),
        });
    }
    let mut exact = Vec::new();
    let mut missing = BTreeSet::new();
    for slot in expected_slots {
        let Some(asset) = observed.assets.get(slot.file_name()) else {
            missing.insert(MissingWork::ForgeAsset(slot));
            continue;
        };
        match compare_forge_asset(artifacts, release, &slot, asset) {
            OperationObservation::Exact(evidence) => exact.push(evidence),
            other => return other,
        }
    }
    if observed.draft {
        missing.insert(MissingWork::PublishForgeRelease(release.clone()));
        return OperationObservation::Incomplete(VerifiedPartialEvidence::new(exact, missing));
    }
    if !missing.is_empty() {
        return OperationObservation::Conflict(ExternalConflict::PublishedReleaseIncomplete {
            release: release.clone(),
        });
    }
    OperationObservation::Exact(ReleaseObservationEvidence::forge_publish(
        release.clone(),
        artifacts.expectations().asset_roster_digest().clone(),
    ))
}

fn compare_forge_asset(
    artifacts: &ValidatedArtifactManifest<'_, '_>,
    release: &ProductReleaseId,
    slot: &ReleaseArtifactSlot,
    observed: &GitHubAsset,
) -> OperationObservation {
    let expectations = artifacts.expectations();
    let Some((expected_digest, expected_length)) = expectations.artifact(slot) else {
        return OperationObservation::Unverifiable(ObservationFailure::Capability {
            provider: ObservationProvider::ArtifactCapability,
        });
    };
    if observed.byte_length != expected_length {
        return OperationObservation::Conflict(ExternalConflict::ForgeAssetLength {
            slot: slot.clone(),
            observed: observed.byte_length,
        });
    }
    let Some(observed_digest) = &observed.digest else {
        return OperationObservation::Unverifiable(ObservationFailure::MissingDigest {
            provider: ObservationProvider::GitHub,
            file_name: slot.file_name().to_string(),
        });
    };
    if observed_digest != expected_digest {
        return OperationObservation::Conflict(ExternalConflict::ForgeAssetDigest {
            slot: slot.clone(),
            observed: observed_digest.clone(),
        });
    }
    OperationObservation::Exact(ReleaseObservationEvidence::forge_asset(
        release.clone(),
        slot.clone(),
        expected_digest.clone(),
        expected_length,
    ))
}

fn require_exact_remote_tag(
    artifacts: &ValidatedArtifactManifest<'_, '_>,
    validated: &ValidatedReleaseIntent<'_>,
) -> Option<OperationObservation> {
    let operation = validated
        .intent()
        .operations()
        .iter()
        .find(|operation| matches!(operation.id(), ReleaseOperationId::ProductTag { .. }))?;
    match validated.prepared_operation(operation.id()) {
        Some(PreparedOperationView::ProductTag {
            name,
            target,
            annotation,
            remote_name,
            ..
        }) => match operation.id() {
            ReleaseOperationId::ProductTag { release, .. } => {
                match observe_tag(artifacts, validated, release, name, target, annotation, remote_name) {
                    OperationObservation::Exact(_) => None,
                    OperationObservation::Absent => {
                        Some(OperationObservation::Conflict(ExternalConflict::RemoteTagMissingForForge))
                    }
                    other => Some(other),
                }
            }
            _ => unreachable!("product-tag predicate returned another operation"),
        },
        _ => Some(OperationObservation::Unverifiable(ObservationFailure::Capability {
            provider: ObservationProvider::PreparedCapability,
        })),
    }
}

fn github_release(
    session: &mut ObservationSession,
    validated: &ValidatedReleaseIntent<'_>,
    repository: &GitHubRepository,
    tag: &TagName,
) -> CachedObservation<GitHubRelease> {
    let key = (repository.as_slug(), tag.as_str().to_string());
    session
        .github_releases
        .entry(key)
        .or_insert_with(|| fetch_github_release(validated, repository, tag))
        .clone()
}

fn fetch_github_release(
    validated: &ValidatedReleaseIntent<'_>,
    repository: &GitHubRepository,
    tag: &TagName,
) -> CachedObservation<GitHubRelease> {
    let endpoint = format!("repos/{}/releases/tags/{}", repository.as_slug(), tag.as_str());
    let args = ["api", "--include", "--method", "GET", endpoint.as_str()];
    let output = validated
        .runner()
        .run_quiet("gh", &args, validated.root(), OBSERVATION_TIMEOUT)
        .map_err(|_| ObservationFailure::Command {
            provider: ObservationProvider::GitHub,
        })?;
    let (status, body) = parse_http_response(&output).ok_or(ObservationFailure::MalformedResponse {
        provider: ObservationProvider::GitHub,
    })?;
    if status == 404 {
        return Ok(None);
    }
    if status != 200 || !output.success() {
        return Err(ObservationFailure::HttpStatus {
            provider: ObservationProvider::GitHub,
            status,
        });
    }
    let value: serde_json::Value = serde_json::from_str(body).map_err(|_| ObservationFailure::MalformedResponse {
        provider: ObservationProvider::GitHub,
    })?;
    if value.get("tag_name").and_then(serde_json::Value::as_str) != Some(tag.as_str()) {
        return Err(ObservationFailure::Capability {
            provider: ObservationProvider::GitHub,
        });
    }
    let draft = value
        .get("draft")
        .and_then(serde_json::Value::as_bool)
        .ok_or(ObservationFailure::MalformedResponse {
            provider: ObservationProvider::GitHub,
        })?;
    let assets = parse_github_assets(value.get("assets")).ok_or(ObservationFailure::MalformedResponse {
        provider: ObservationProvider::GitHub,
    })?;
    Ok(Some(GitHubRelease { draft, assets }))
}

fn parse_github_assets(value: Option<&serde_json::Value>) -> Option<BTreeMap<String, GitHubAsset>> {
    let mut parsed = BTreeMap::new();
    for asset in value?.as_array()? {
        let name = asset.get("name")?.as_str()?.to_string();
        let byte_length = asset.get("size")?.as_u64()?;
        let digest = match asset.get("digest") {
            Some(serde_json::Value::String(raw)) => {
                let raw = raw.strip_prefix("sha256:")?;
                Some(ArtifactDigest::parse(raw).ok()?)
            }
            Some(serde_json::Value::Null) | None => None,
            _ => return None,
        };
        if parsed.insert(name, GitHubAsset { digest, byte_length }).is_some() {
            return None;
        }
    }
    Some(parsed)
}

fn fetch_pypi_version(
    validated: &ValidatedReleaseIntent<'_>,
    metadata_endpoint: &str,
    package: &str,
    version: &Version,
) -> CachedObservation<BTreeMap<String, PypiDistribution>> {
    let url = append_url_segments(metadata_endpoint, &[package, &version.render(), "json"]).ok_or(
        ObservationFailure::MalformedResponse {
            provider: ObservationProvider::Pypi,
        },
    )?;
    let Some(value) = observe_json_http(validated.runner(), validated.root(), &url, ObservationProvider::Pypi)? else {
        return Ok(None);
    };
    let urls = value
        .get("urls")
        .and_then(serde_json::Value::as_array)
        .ok_or(ObservationFailure::MalformedResponse {
            provider: ObservationProvider::Pypi,
        })?;
    let mut distributions = BTreeMap::new();
    for file in urls {
        let file_name = file
            .get("filename")
            .and_then(serde_json::Value::as_str)
            .ok_or(ObservationFailure::MalformedResponse {
                provider: ObservationProvider::Pypi,
            })?
            .to_string();
        let byte_length = file
            .get("size")
            .and_then(serde_json::Value::as_u64)
            .ok_or(ObservationFailure::MalformedResponse {
                provider: ObservationProvider::Pypi,
            })?;
        let digest = file
            .get("digests")
            .and_then(|digests| digests.get("sha256"))
            .and_then(serde_json::Value::as_str)
            .and_then(|raw| ArtifactDigest::parse(raw).ok())
            .ok_or_else(|| ObservationFailure::MissingDigest {
                provider: ObservationProvider::Pypi,
                file_name: file_name.clone(),
            })?;
        if distributions
            .insert(digest_file_name(file_name), PypiDistribution { digest, byte_length })
            .is_some()
        {
            return Err(ObservationFailure::MalformedResponse {
                provider: ObservationProvider::Pypi,
            });
        }
    }
    Ok(Some(distributions))
}

fn digest_file_name(file_name: String) -> String {
    file_name
}

fn observe_npm_bytes(
    validated: &ValidatedReleaseIntent<'_>,
    package: &str,
    version: &Version,
    registry: &str,
) -> Result<Option<Vec<u8>>, ObservationFailure> {
    let directory = tempfile::tempdir().map_err(|_| ObservationFailure::Capability {
        provider: ObservationProvider::Npm,
    })?;
    let spec = format!("{package}@{}", version.render());
    let destination = directory.path().to_string_lossy();
    let args = [
        "pack",
        spec.as_str(),
        "--json",
        "--ignore-scripts",
        "--pack-destination",
        destination.as_ref(),
        "--registry",
        registry,
    ];
    let output = validated
        .runner()
        .run_quiet("npm", &args, validated.root(), OBSERVATION_TIMEOUT)
        .map_err(|_| ObservationFailure::Command {
            provider: ObservationProvider::Npm,
        })?;
    if !output.success() {
        let lower = format!("{}\n{}", output.stdout, output.stderr).to_ascii_lowercase();
        if lower.contains("e404") || lower.contains("etarget") || lower.contains("no matching version") {
            return Ok(None);
        }
        return Err(ObservationFailure::Command {
            provider: ObservationProvider::Npm,
        });
    }
    let value: serde_json::Value = serde_json::from_str(&output.stdout).map_err(|_| {
        ObservationFailure::MalformedResponse {
            provider: ObservationProvider::Npm,
        }
    })?;
    let entries = value.as_array().ok_or(ObservationFailure::MalformedResponse {
        provider: ObservationProvider::Npm,
    })?;
    if entries.len() != 1 {
        return Err(ObservationFailure::MalformedResponse {
            provider: ObservationProvider::Npm,
        });
    }
    let file_name = entries[0]
        .get("filename")
        .and_then(serde_json::Value::as_str)
        .ok_or(ObservationFailure::MalformedResponse {
            provider: ObservationProvider::Npm,
        })?;
    if Path::new(file_name).components().count() != 1 {
        return Err(ObservationFailure::MalformedResponse {
            provider: ObservationProvider::Npm,
        });
    }
    std::fs::read(directory.path().join(file_name))
        .map(Some)
        .map_err(|_| ObservationFailure::MalformedResponse {
            provider: ObservationProvider::Npm,
        })
}

fn observe_json_http(
    runner: &dyn callisto_model::CommandRunner,
    root: &Path,
    url: &str,
    provider: ObservationProvider,
) -> Result<Option<serde_json::Value>, ObservationFailure> {
    let args = [
        "--silent",
        "--show-error",
        "--location",
        "--include",
        "--request",
        "GET",
        url,
    ];
    let output = runner
        .run_quiet("curl", &args, root, OBSERVATION_TIMEOUT)
        .map_err(|_| ObservationFailure::Command { provider })?;
    if !output.success() {
        return Err(ObservationFailure::Command { provider });
    }
    let (status, body) = parse_http_response(&output).ok_or(ObservationFailure::MalformedResponse { provider })?;
    if status == 404 {
        return Ok(None);
    }
    if status != 200 {
        return Err(ObservationFailure::HttpStatus { provider, status });
    }
    serde_json::from_str(body)
        .map(Some)
        .map_err(|_| ObservationFailure::MalformedResponse { provider })
}

fn parse_http_response(output: &CommandOutput) -> Option<(u16, &str)> {
    parse_http_stream(&output.stdout).or_else(|| parse_http_stream(&output.stderr))
}

fn parse_http_stream(stream: &str) -> Option<(u16, &str)> {
    let (headers, body) = stream.rsplit_once("\r\n\r\n").or_else(|| stream.rsplit_once("\n\n"))?;
    let status = headers
        .lines()
        .rev()
        .find(|line| line.trim_end_matches('\r').starts_with("HTTP/"))?
        .split_whitespace()
        .nth(1)?
        .parse()
        .ok()?;
    Some((status, body))
}

fn cargo_metadata_url(endpoint: &str, package: &str, version: &Version) -> Option<String> {
    let mut url = url::Url::parse(endpoint).ok()?;
    {
        let mut segments = url.path_segments_mut().ok()?;
        segments.pop_if_empty();
        if segments.pop() != Some("new") {
            return None;
        }
        segments.extend([package, version.render().as_str()]);
    }
    Some(url.into())
}

fn append_url_segments(base: &str, segments: &[&str]) -> Option<String> {
    let mut url = url::Url::parse(base).ok()?;
    {
        let mut path = url.path_segments_mut().ok()?;
        path.pop_if_empty();
        path.extend(segments.iter().copied());
    }
    Some(url.into())
}

fn malformed(provider: ObservationProvider) -> OperationObservation {
    OperationObservation::Unverifiable(ObservationFailure::MalformedResponse { provider })
}

#[cfg(test)]
mod tests {
    use std::{
        collections::VecDeque,
        path::Path,
        sync::{Arc, Mutex},
    };

    use callisto_model::{CommandError, CommandRunner};

    use super::*;

    #[derive(Clone, Default)]
    struct RecordingRunner {
        calls: Arc<Mutex<Vec<(String, Vec<String>)>>>,
        outputs: Arc<Mutex<VecDeque<Result<CommandOutput, CommandError>>>>,
    }

    impl CommandRunner for RecordingRunner {
        fn run(&self, program: &str, args: &[&str], _cwd: &Path) -> Result<CommandOutput, CommandError> {
            self.calls
                .lock()
                .unwrap()
                .push((program.to_string(), args.iter().map(|value| value.to_string()).collect()));
            self.outputs.lock().unwrap().pop_front().unwrap()
        }
    }

    fn output(exit_code: i32, stdout: &str, stderr: &str) -> Result<CommandOutput, CommandError> {
        Ok(CommandOutput {
            exit_code: Some(exit_code),
            stdout: stdout.to_string(),
            stderr: stderr.to_string(),
        })
    }

    #[test]
    fn github_parser_accepts_real_nonzero_404_response_without_accepting_bare_error_text() {
        let response = CommandOutput {
            exit_code: Some(1),
            stdout: "HTTP/2 404 Not Found\r\ncontent-type: application/json\r\n\r\n{\"message\":\"Not Found\"}".into(),
            stderr: "gh: Not Found (HTTP 404)".into(),
        };
        assert_eq!(parse_http_response(&response).map(|(status, _)| status), Some(404));
        let bare = CommandOutput {
            exit_code: Some(1),
            stdout: String::new(),
            stderr: "gh: Not Found (HTTP 404)".into(),
        };
        assert_eq!(parse_http_response(&bare), None);
    }

    #[test]
    fn github_asset_parser_requires_sha256_and_rejects_duplicate_names() {
        let digest = "a".repeat(64);
        let assets = serde_json::json!([
            {"name":"callisto.tar.gz","size":12,"digest":format!("sha256:{digest}")}
        ]);
        let parsed = parse_github_assets(Some(&assets)).unwrap();
        assert_eq!(parsed["callisto.tar.gz"].digest.as_ref().unwrap().as_str(), digest);
        let duplicate = serde_json::json!([
            {"name":"same","size":1,"digest":format!("sha256:{digest}")},
            {"name":"same","size":1,"digest":format!("sha256:{digest}")}
        ]);
        assert!(parse_github_assets(Some(&duplicate)).is_none());
    }

    #[test]
    fn github_release_uses_supported_api_argv_and_caches_release_with_assets() {
        let runner = RecordingRunner::default();
        runner.outputs.lock().unwrap().push_back(output(
            0,
            &format!(
                "HTTP/2 200 OK\r\ncontent-type: application/json\r\n\r\n{{\"tag_name\":\"callisto@1.2.3\",\"draft\":true,\"assets\":[{{\"name\":\"a\",\"size\":1,\"digest\":\"sha256:{}\"}}]}}",
                "a".repeat(64)
            ),
            "",
        ));
        let repository = GitHubRepository::parse("owner/repository").unwrap();
        let tag = TagName::parse("callisto@1.2.3").unwrap();
        let endpoint = format!("repos/{}/releases/tags/{}", repository.as_slug(), tag.as_str());
        let args = ["api", "--include", "--method", "GET", endpoint.as_str()];
        let first = runner.run_quiet("gh", &args, Path::new("."), OBSERVATION_TIMEOUT).unwrap();
        assert_eq!(parse_http_response(&first).unwrap().0, 200);
        let calls = runner.calls.lock().unwrap();
        assert_eq!(calls[0].1, args);
        assert!(!calls[0].1.contains(&"--repo".to_string()));
    }

    #[test]
    fn provider_failures_are_not_classified_as_absence() {
        let unauthorized = CommandOutput {
            exit_code: Some(1),
            stdout: "HTTP/2 401 Unauthorized\r\n\r\n{}".into(),
            stderr: String::new(),
        };
        let malformed = CommandOutput {
            exit_code: Some(1),
            stdout: String::new(),
            stderr: "not an HTTP response".into(),
        };
        assert_eq!(parse_http_response(&unauthorized).unwrap().0, 401);
        assert_eq!(parse_http_response(&malformed), None);
    }

    #[test]
    fn registry_urls_preserve_typed_base_and_encode_identity_segments() {
        let version = Version::semver(1, 2, 3);
        assert_eq!(
            cargo_metadata_url("https://crates.example/api/v1/crates/new", "scope/name", &version).unwrap(),
            "https://crates.example/api/v1/crates/scope%2Fname/1.2.3"
        );
        assert_eq!(
            append_url_segments("https://pypi.example/pypi/", &["demo-name", "1.2.3", "json"]).unwrap(),
