        .package_ecosystems
        .get(id)
        .map_or(explicit_ecosystem.as_slice(), Vec::as_slice);
    Ok(cfg
        .package_sets
        .iter()
        .find(|(pattern, _)| pattern.matches_in_ecosystems(id.name(), ecosystems))
        .map(|(_, package)| package))
}

pub fn parse_pre_major_policy(s: &str) -> Result<PreMajorInferencePolicy, ConfigError> {
