                path: callisto_toml.to_path_buf(),
                key: format!("{error_prefix} publish-to: {key}"),
            },
            other => other,
        })?;

    Ok(PackageConfig {
        release_unit,
        release_trigger,
        publish_to,
        tag_template,
        changelog,
        pre_major_inference,
    })
}

