    PackageConfig, PreMajorInferencePolicy, RegistryConfig, RegistryEndpoints, ReleaseConfig, ReleaseProductConfig,
    ReleaseProfileConfig, ReleaseProfileKind, ReleaseUnitClassification, ResolvedConfig, ValidationConfig,
};

