/// Per-package overrides from a `[[package]]` block in `callisto.toml`.
///
/// Every field is `Option<T>` — `None` means "not specified; use the package's default."
/// Only fields that the user explicitly set in the `[[package]]` block are `Some`.
#[derive(Clone, Debug)]
pub struct PackageConfig {
    pub release_unit: Option<ReleaseUnitClassification>,
    pub release_trigger: Option<ReleaseTrigger>,
    pub publish_to: Option<Vec<PublishTarget>>,
    pub tag_template: Option<TagTemplate>,
    /// Changelog path relative to the package's own root directory.
    pub changelog: Option<PathBuf>,
    pub pre_major_inference: Option<PreMajorInferencePolicy>,
}

/// Whether a discovered package participates in durable release authority.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum ReleaseUnitClassification {
    #[default]
    Releasable,
    DevOnly,
}

/// Uses the same effective override as manifest discovery and aggregation.
pub fn is_release_unit(config: &ResolvedConfig, id: &PackageId) -> Result<bool, GraphError> {
    Ok(resolve_package_config(id, config)?
        .and_then(|package| package.release_unit)
        .unwrap_or_default()
        == ReleaseUnitClassification::Releasable)
}

pub(crate) fn release_unit_ids(
    config: &ResolvedConfig,
    graph: &impl crate::DependencyResolver,
) -> Result<BTreeSet<PackageId>, GraphError> {
    let mut ids = BTreeSet::new();
    for package in graph.packages() {
        if is_release_unit(config, &package.id)? {
            ids.insert(package.id.clone());
        }
    }
    Ok(ids)
}

/// Pre-1.0 (`0.y.z`) severity-downgrade policy. A closed 3-state choice --
/// modeled as an enum rather than two independent bools so the type system
/// rules out the unreachable-via-parser 4th combination a `{breaking_to_minor:
/// false, feat_to_patch: true}`-shaped struct literal could otherwise
/// construct.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum PreMajorInferencePolicy {
    #[default]
    Off,
    /// Downgrades an inferred Major bump to Minor.
    Conservative,
    /// Downgrades an inferred Major bump to Minor, and Minor to Patch.
    ConservativeFeat,
}

pub fn parse_publish_target(s: &str) -> Result<PublishTarget, ConfigError> {
    match s {
        "crates-io" => Ok(PublishTarget::CratesIo),
        "npm" => Ok(PublishTarget::Npm {
            registry: None,
            access: None,
        }),
        "pypi" => Ok(PublishTarget::Pypi { index: None }),
        "nuget" => Ok(PublishTarget::NuGet { source: None }),
        "github-release" => Ok(PublishTarget::GitHubRelease),
        "none" => Ok(PublishTarget::None),
        other => Err(ConfigError::UnknownKey {
            path: PathBuf::new(),
            key: format!("publish-to = {other:?}"),
        }),
    }
}

pub fn parse_release_trigger(s: &str) -> Result<ReleaseTrigger, ConfigError> {
    match s {
        "changeset" => Ok(ReleaseTrigger::Changeset),
        "auto" => Ok(ReleaseTrigger::Auto),
        other => Err(ConfigError::UnknownKey {
            path: PathBuf::new(),
            key: format!("release-trigger = {other}"),
        }),
    }
}

/// Two-pass `[[package]]` rule lookup with Prefixed-over-Bare specificity.
///
/// Pass 1: iterate `cfg.packages` in TOML-declaration order, return the
/// first entry where `rule_id.ecosystem().is_some()` AND
/// `rule_id.matches(id)` -- prefixed rules (`cargo/`, `npm/`, `pypi/`)
/// always beat bare ones regardless of declaration order.
///
/// Pass 2 (only if Pass 1 found nothing): same order, first entry where
/// `rule_id.matches(id)` with no ecosystem restriction.
///
/// If neither pass matches, the first matching package-set is the fallback.
///
/// MUST NOT sort or partition `cfg.packages` -- specificity comes solely
/// from two separate linear scans over the unmodified slice.
pub(crate) fn resolve_package_config<'a>(
    id: &PackageId,
    cfg: &'a ResolvedConfig,
) -> Result<Option<&'a PackageConfig>, GraphError> {
    if let Some((_, pcfg)) = cfg
        .packages
        .iter()
        .find(|(rule_id, _)| rule_id.ecosystem().is_some() && rule_id.matches(id))
    {
        return Ok(Some(pcfg));
    }
    if let Some((_, pcfg)) = cfg.packages.iter().find(|(rule_id, _)| rule_id.matches(id)) {
        if let Some(siblings) = cfg.promoted_siblings.get(id.name()) {
            return Err(GraphError::AmbiguousName {
                name: id.name().to_string(),
                candidates: siblings.iter().map(|(pid, _)| pid.clone()).collect(),
            });
        }
        return Ok(Some(pcfg));
    }
    let explicit_ecosystem = id.ecosystem();
    let ecosystems = cfg
        .package_ecosystems
        .get(id)
        .map_or(explicit_ecosystem.as_slice(), Vec::as_slice);
    Ok(cfg
        .package_sets
        .iter()
        .find(|(pattern, _)| pattern.matches_in_ecosystems(id.name(), ecosystems))
        .map(|(_, package)| package))
}

pub fn parse_pre_major_policy(s: &str) -> Result<PreMajorInferencePolicy, ConfigError> {
    match s {
        "off" | "false" => Ok(PreMajorInferencePolicy::Off),
        "conservative" => Ok(PreMajorInferencePolicy::Conservative),
        "conservative-feat" => Ok(PreMajorInferencePolicy::ConservativeFeat),
        _ => Err(ConfigError::InvalidPreMajorInference { found: s.to_string() }),
    }
}

/// Parses the override fields shared by `[[package]]` and
/// `[[package-set]]` blocks (release-unit, release-trigger, tag-template, changelog,
/// pre-major-inference, publish-to) into a `PackageConfig`.
///
/// `RawPackageConfig` and `RawPackageSetConfig` are field-identical raw
/// shapes (see `config::raw`) -- only the pattern type that parses `match`
/// (`PackageId` vs `PackagePattern`, handled by each caller before calling
/// this) and `error_prefix` (naming which block a `publish-to` error came
/// from) differ between the two call sites this factors out of.
#[allow(clippy::too_many_arguments)]
fn parse_package_config_fields(
    callisto_toml: &Path,
    error_prefix: &str,
    pattern_display: &str,
    release_unit: Option<&str>,
    release_trigger: Option<&str>,
    tag_template: Option<&str>,
    changelog: Option<&str>,
    pre_major_inference: Option<&str>,
    publish_to: Option<&[String]>,
) -> Result<PackageConfig, ConfigError> {
    let release_unit = release_unit
        .map(|value| match value {
            "releasable" => Ok(ReleaseUnitClassification::Releasable),
            "dev-only" => Ok(ReleaseUnitClassification::DevOnly),
            other => Err(ConfigError::UnknownKey {
                path: callisto_toml.to_path_buf(),
                key: format!(
                    "{error_prefix} {pattern_display:?} release-unit = {other:?}; expected releasable or dev-only"
                ),
            }),
        })
        .transpose()?;
    let release_trigger = release_trigger.map(parse_release_trigger).transpose()?;

    let tag_template = tag_template
        .map(TagTemplate::parse)
        .transpose()
        .map_err(ConfigError::Tag)?;

    let changelog = changelog
        .map(|s| {
            callisto_model::workspace_relative(s).map_err(|_err| ConfigError::InvalidChangelogPath {
                pattern: pattern_display.to_string(),
                value: s.to_string(),
            })
        })
        .transpose()?;

    let pre_major_inference = pre_major_inference.map(parse_pre_major_policy).transpose()?;

    let publish_to = publish_to
        .map(|targets| {
            targets
                .iter()
                .map(|s| parse_publish_target(s))
                .collect::<Result<Vec<_>, _>>()
        })
        .transpose()
        .map_err(|e| match e {
            ConfigError::UnknownKey { key, .. } => ConfigError::UnknownKey {
                path: callisto_toml.to_path_buf(),
                key: format!("{error_prefix} publish-to: {key}"),
            },
            other => other,
        })?;

    Ok(PackageConfig {
        release_unit,
        release_trigger,
        publish_to,
        tag_template,
        changelog,
        pre_major_inference,
    })
}

