                r#"
[[package]]
match = "pypi/demo"
publish-to = ["pypi", "npm"]
[[package.release-artifact]]
format = "wheel"
file-name = "demo-{version}-py3-none-any.whl"
"#,
            ),
            (
                "unknown format",
                r#"
[[package]]
match = "pypi/demo"
publish-to = ["pypi"]
[[package.release-artifact]]
format = "egg"
file-name = "demo-{version}.egg"
"#,
            ),
            (
                "format/suffix mismatch",
                r#"
[[package]]
match = "pypi/demo"
publish-to = ["pypi"]
[[package.release-artifact]]
format = "wheel"
file-name = "demo-{version}.tar.gz"
"#,
            ),
            (
                "missing version placeholder",
                r#"
[[package]]
match = "pypi/demo"
publish-to = ["pypi"]
[[package.release-artifact]]
format = "wheel"
file-name = "demo-1.2.3-py3-none-any.whl"
"#,
            ),
            (
                "unknown placeholder",
                r#"
[[package]]
match = "pypi/demo"
publish-to = ["pypi"]
[[package.release-artifact]]
format = "wheel"
file-name = "demo-{version}-{platform}.whl"
"#,
            ),
            (
                "unsafe file name",
                r#"
[[package]]
match = "pypi/demo"
publish-to = ["pypi"]
[[package.release-artifact]]
format = "wheel"
file-name = "../demo-{version}.whl"
"#,
            ),
            (
                "duplicate file name",
                r#"
[[package]]
match = "pypi/demo"
publish-to = ["pypi"]
[[package.release-artifact]]
format = "wheel"
file-name = "demo-{version}-py3-none-any.whl"
[[package.release-artifact]]
format = "wheel"
file-name = "demo-{version}-py3-none-any.whl"
"#,
            ),
            (
                "multiple sdists",
                r#"
[[package]]
match = "pypi/demo"
publish-to = ["pypi"]
[[package.release-artifact]]
format = "sdist"
file-name = "demo-{version}.tar.gz"
[[package.release-artifact]]
format = "sdist"
file-name = "demo-src-{version}.tar.gz"
"#,
            ),
        ];
        for (case, config) in invalid {
            assert!(
                matches!(
                    load_config_text(config),
                    Err(ConfigError::InvalidReleaseArtifactDescriptor { .. })
                ),
                "{case} must be rejected"
            );
        }
    }

    #[test]
    fn release_artifacts_are_not_allowed_on_package_sets() {
        let result = load_config_text(
            r#"
[[package-set]]
match = "pypi/*"
publish-to = ["pypi"]
[[package-set.release-artifact]]
format = "wheel"
file-name = "demo-{version}-py3-none-any.whl"
"#,
        );
        assert!(matches!(result, Err(ConfigError::ParseToml { .. })));
    }

    #[test]
    fn release_artifact_tables_deny_unknown_fields() {
        let result = load_config_text(
            r#"
[[package]]
match = "pypi/demo"
publish-to = ["pypi"]
[[package.release-artifact]]
format = "wheel"
file-name = "demo-{version}-py3-none-any.whl"
platform = "any"
"#,
        );
        assert!(matches!(result, Err(ConfigError::ParseToml { .. })));
    }
}

