//! Artifact-byte and GitHub-attestation verification for durable releases.
//!
//! A manifest is only a claim. This module verifies the actual on-disk bytes
//! and asks GitHub to validate the signing certificate against the policy
//! embedded in the immutable release intent before an executor can upload an
//! asset. It intentionally owns no upload side effect.

use std::{
    collections::BTreeMap,
    fs::{self, File},
    path::{Component, Path, PathBuf},
    time::Duration,
};

use callisto_model::{ArtifactDigest, CommandRunner, ProvenancePolicy, ReleaseArtifactManifest, ReleaseArtifactSlot};

use crate::GraphError;

use super::release::ValidatedReleaseIntent;

const ATTESTATION_TIMEOUT: Duration = Duration::from_secs(120);

#[derive(Debug)]
struct ValidatedArtifactEntry {
    path: PathBuf,
    digest: ArtifactDigest,
    byte_length: u64,
}

/// Intent-bound capability proving that the complete manifest, every local
/// byte sequence, and every required GitHub attestation were verified.
///
/// The raw manifest is deliberately not exposed. Provider dispatch receives
/// bytes only through [`Self::snapshot`], which repeats path containment and
/// byte identity checks immediately before the caller can submit them.
#[derive(Debug)]
#[allow(dead_code)] // the intent/manifest bindings become dispatch inputs in T3-DISPATCH
pub(super) struct ValidatedArtifactManifest<'intent, 'runner> {
    validated_intent: &'intent ValidatedReleaseIntent<'runner>,
    manifest: ReleaseArtifactManifest,
    artifact_root: PathBuf,
    entries: BTreeMap<ReleaseArtifactSlot, ValidatedArtifactEntry>,
}

#[derive(Debug)]
#[allow(dead_code)] // consumed by exact-byte provider dispatch in T3-DISPATCH
pub(super) struct ArtifactSnapshot {
    slot: ReleaseArtifactSlot,
    bytes: Vec<u8>,
}

impl ArtifactSnapshot {
    #[allow(dead_code)] // consumed by exact-byte provider dispatch in T3-DISPATCH
    pub(super) fn slot(&self) -> &ReleaseArtifactSlot {
        &self.slot
    }

    #[allow(dead_code)] // consumed by exact-byte provider dispatch in T3-DISPATCH
    pub(super) fn bytes(&self) -> &[u8] {
        &self.bytes
    }
}

impl ValidatedArtifactManifest<'_, '_> {
    #[allow(dead_code)] // consumed by provider observation and dispatch in T3/T3-DISPATCH
    pub(super) fn validated_intent(&self) -> &ValidatedReleaseIntent<'_> {
        self.validated_intent
    }

    #[allow(dead_code)] // consumed by provider observation and receipt assembly in T3/T4
    pub(super) fn expectations(&self) -> callisto_model::ObservationExpectations {
        callisto_model::ObservationExpectations::from_manifest(self.validated_intent.intent(), &self.manifest)
            .expect("validated artifact capability retains its verified intent/manifest binding")
    }

    #[allow(dead_code)] // consumed by exact-byte provider dispatch in T3-DISPATCH
    pub(super) fn snapshot(&self, slot: &ReleaseArtifactSlot) -> Result<ArtifactSnapshot, GraphError> {
        snapshot_from_entries(&self.artifact_root, &self.entries, slot)
    }
}

fn snapshot_from_entries(
    artifact_root: &Path,
    entries: &BTreeMap<ReleaseArtifactSlot, ValidatedArtifactEntry>,
    slot: &ReleaseArtifactSlot,
) -> Result<ArtifactSnapshot, GraphError> {
    let expected = entries.get(slot).ok_or_else(|| GraphError::ArtifactManifest {
        source: callisto_model::SuccessorError::MismatchedManifest,
    })?;
    snapshot_verified_entry(artifact_root, slot, expected)
}

fn snapshot_verified_entry(
    artifact_root: &Path,
    slot: &ReleaseArtifactSlot,
    expected: &ValidatedArtifactEntry,
) -> Result<ArtifactSnapshot, GraphError> {
    let path = resolve_asset_path(artifact_root, slot.file_name())?;
    if path != expected.path {
        return Err(GraphError::UnsafeArtifactPath {
            path,
            reason: "artifact path changed after validation",
        });
    }
    let bytes = fs::read(&path).map_err(|error| GraphError::ArtifactRead {
        path: path.clone(),
        message: error.to_string(),
    })?;
    if ArtifactDigest::from_bytes(&bytes) != expected.digest || bytes.len() as u64 != expected.byte_length {
        return Err(GraphError::ArtifactBytesMismatch { path });
    }
    Ok(ArtifactSnapshot {
        slot: slot.clone(),
        bytes,
    })
}

/// Verifies every manifest entry against the exact artifact directory.
///
/// The artifact directory and every candidate are canonicalized, and symbolic
/// links are rejected, so a manifest asset name cannot escape the supplied
/// build-output directory. Each asset is streamed once for a bounded-memory
/// SHA-256 and size comparison. `gh attestation verify` then validates the
/// repository, workflow path and commit, source commit, and hosted-runner
/// policy declared by the immutable artifact slot.
pub(super) fn verify_artifact_manifest<'intent, 'runner, R: CommandRunner>(
    validated_intent: &'intent ValidatedReleaseIntent<'runner>,
    manifest: ReleaseArtifactManifest,
    artifact_root: &Path,
    runner: &R,
) -> Result<ValidatedArtifactManifest<'intent, 'runner>, GraphError> {
    verify_artifact_manifest_for_intent(validated_intent.intent(), &manifest, artifact_root, runner).map(
        |(artifact_root, entries)| ValidatedArtifactManifest {
            validated_intent,
            manifest,
            artifact_root,
            entries,
        },
    )
}

fn verify_artifact_manifest_for_intent<R: CommandRunner>(
    intent: &callisto_model::ReleaseIntent,
    manifest: &ReleaseArtifactManifest,
    artifact_root: &Path,
    runner: &R,
) -> Result<(PathBuf, BTreeMap<ReleaseArtifactSlot, ValidatedArtifactEntry>), GraphError> {
    manifest
        .validate_for_intent(intent)
        .map_err(|source| GraphError::ArtifactManifest { source })?;

    let root = canonical_artifact_root(artifact_root)?;
    let mut verified_entries = BTreeMap::new();
    for entry in manifest.entries() {
        let path = resolve_asset_path(&root, entry.slot().file_name())?;
        let file = File::open(&path).map_err(|error| GraphError::ArtifactRead {
            path: path.clone(),
            message: error.to_string(),
        })?;
        let (digest, length) =
            callisto_model::ArtifactDigest::from_reader(file).map_err(|error| GraphError::ArtifactRead {
                path: path.clone(),
                message: error.to_string(),
            })?;
        if digest != *entry.digest() || length != entry.byte_length() {
            return Err(GraphError::ArtifactBytesMismatch { path });
        }
        verified_entries.insert(
            entry.slot().clone(),
            ValidatedArtifactEntry {
                path,
                digest,
                byte_length: length,
            },
        );
    }

    // Attestation lookup is intentionally a second phase. No external command
    // runs until every manifest entry has passed all local checks.
    for entry in manifest.entries() {
        let verified = verified_entries
            .get(entry.slot())
            .expect("complete manifest entry was inserted during the local verification phase");
        verify_github_attestation(&verified.path, entry.provenance(), manifest.source_commit(), runner)?;
    }
    Ok((root, verified_entries))
}

fn canonical_artifact_root(artifact_root: &Path) -> Result<PathBuf, GraphError> {
    let metadata = fs::metadata(artifact_root).map_err(|error| GraphError::ArtifactRead {
        path: artifact_root.to_path_buf(),
        message: error.to_string(),
    })?;
    if !metadata.is_dir() {
        return Err(GraphError::UnsafeArtifactPath {
            path: artifact_root.to_path_buf(),
            reason: "artifact root is not a directory",
        });
    }
    artifact_root.canonicalize().map_err(|error| GraphError::ArtifactRead {
        path: artifact_root.to_path_buf(),
        message: error.to_string(),
    })
}

fn resolve_asset_path(root: &Path, asset_name: &str) -> Result<PathBuf, GraphError> {
    let relative = Path::new(asset_name);
    if relative.components().count() != 1 || !matches!(relative.components().next(), Some(Component::Normal(_))) {
        return Err(GraphError::UnsafeArtifactPath {
            path: relative.to_path_buf(),
            reason: "asset name is not a single relative file name",
        });
    }
    let candidate = root.join(relative);
    let metadata = fs::symlink_metadata(&candidate).map_err(|error| GraphError::ArtifactRead {
        path: candidate.clone(),
        message: error.to_string(),
    })?;
    if metadata.file_type().is_symlink() {
        return Err(GraphError::UnsafeArtifactPath {
            path: candidate,
            reason: "symbolic links are not accepted as artifacts",
        });
    }
    if !metadata.is_file() {
        return Err(GraphError::UnsafeArtifactPath {
            path: candidate,
            reason: "artifact is not a regular file",
        });
    }
    let canonical = candidate.canonicalize().map_err(|error| GraphError::ArtifactRead {
        path: candidate.clone(),
        message: error.to_string(),
    })?;
    if !canonical.starts_with(root) {
        return Err(GraphError::UnsafeArtifactPath {
            path: canonical,
            reason: "artifact resolves outside artifact root",
        });
    }
    Ok(canonical)
}

fn verify_github_attestation<R: CommandRunner>(
    path: &Path,
    policy: &ProvenancePolicy,
    source_commit: &callisto_model::CommitSha,
    runner: &R,
) -> Result<(), GraphError> {
    let repository_slug = policy.repository().as_slug();
    let workflow = format!("{repository_slug}/{}", policy.workflow_path());
    let path_argument = path.to_string_lossy();
    let args = [
        "attestation",
        "verify",
        path_argument.as_ref(),
        "--repo",
        repository_slug.as_str(),
        "--signer-workflow",
        workflow.as_str(),
        "--signer-digest",
        policy.workflow_commit().as_str(),
        "--source-digest",
        source_commit.as_str(),
        "--deny-self-hosted-runners",
    ];
    let output = runner
        .run_with_timeout(
            "gh",
            &args,
            path.parent().unwrap_or_else(|| Path::new(".")),
            ATTESTATION_TIMEOUT,
        )
        .map_err(|error| GraphError::ArtifactAttestation {
            path: path.to_path_buf(),
            message: error.to_string(),
        })?;
    if output.success() {
        Ok(())
    } else {
        Err(GraphError::ArtifactAttestation {
            path: path.to_path_buf(),
            message: "GitHub attestation verification failed".to_owned(),
        })
    }
}

