/// Per-package overrides from a `[[package]]` block in `callisto.toml`.
///
/// Every field is `Option<T>` — `None` means "not specified; use the package's default."
/// Only fields that the user explicitly set in the `[[package]]` block are `Some`.
#[derive(Clone, Debug)]
pub struct PackageConfig {
    pub release_unit: Option<ReleaseUnitClassification>,
    pub release_trigger: Option<ReleaseTrigger>,
    pub publish_to: Option<Vec<PublishTarget>>,
    pub tag_template: Option<TagTemplate>,
    /// Changelog path relative to the package's own root directory.
    pub changelog: Option<PathBuf>,
    pub pre_major_inference: Option<PreMajorInferencePolicy>,
    /// Exact PyPI distribution descriptors. `None` means the package did not
    /// opt into durable PyPI release; Callisto never infers wheel tags or an
    /// sdist name from mutable build output.
    pub release_artifacts: Option<Vec<ReleaseArtifactDescriptor>>,
}

/// One exact, immutable PyPI distribution expected from a release build.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ReleaseArtifactDescriptor {
    format: RegistryArtifactFormat,
    file_name_template: String,
}

impl ReleaseArtifactDescriptor {
    pub fn format(&self) -> RegistryArtifactFormat {
        self.format
    }

    /// Renders and revalidates the exact distribution basename for one
    /// coordinated product version. `None` prevents an unexpectedly long or
    /// otherwise unsafe SemVer rendering from becoming provider authority.
    pub fn file_name_for(&self, version: &callisto_model::Version) -> Option<String> {
        let rendered = self.file_name_template.replace("{version}", version.render());
        release_artifact_file_name_is_safe(&rendered, self.format).then_some(rendered)
    }
}

/// Whether a discovered package participates in durable release authority.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum ReleaseUnitClassification {
    #[default]
    Releasable,
    DevOnly,
}

/// Uses the same effective override as manifest discovery and aggregation.
pub fn is_release_unit(config: &ResolvedConfig, id: &PackageId) -> Result<bool, GraphError> {
    Ok(resolve_package_config(id, config)?
        .and_then(|package| package.release_unit)
        .unwrap_or_default()
        == ReleaseUnitClassification::Releasable)
}

pub(crate) fn release_unit_ids(
    config: &ResolvedConfig,
    graph: &impl crate::DependencyResolver,
) -> Result<BTreeSet<PackageId>, GraphError> {
    let mut ids = BTreeSet::new();
    for package in graph.packages() {
        if is_release_unit(config, &package.id)? {
            ids.insert(package.id.clone());
        }
    }
    Ok(ids)
}

/// Pre-1.0 (`0.y.z`) severity-downgrade policy. A closed 3-state choice --
/// modeled as an enum rather than two independent bools so the type system
/// rules out the unreachable-via-parser 4th combination a `{breaking_to_minor:
