fn parse_release_artifacts(
    pattern: &PackageId,
    package: &PackageConfig,
    raw: Option<&[RawReleaseArtifactConfig]>,
) -> Result<Option<Vec<ReleaseArtifactDescriptor>>, ConfigError> {
    let Some(raw) = raw else {
        return Ok(None);
    };
    if raw.is_empty() {
        return Err(invalid_release_artifact(
            pattern,
            "declare at least one nested [[package.release-artifact]] table",
        ));
    }
    if pattern.ecosystem() != Some(Ecosystem::Pypi) {
        return Err(invalid_release_artifact(
            pattern,
            "descriptors are valid only on an explicit pypi/<name> package match",
        ));
    }
    if package.release_unit == Some(ReleaseUnitClassification::DevOnly) {
        return Err(invalid_release_artifact(
            pattern,
            "descriptors are not valid on a dev-only release unit",
        ));
    }
    if !package
        .publish_to
        .as_ref()
        .is_some_and(|targets| targets.iter().any(|target| target.ecosystem() == Some(Ecosystem::Pypi)))
    {
        return Err(invalid_release_artifact(
            pattern,
            "descriptors require publish-to = [\"pypi\"]",
        ));
    }
    if package.publish_to.as_ref().is_some_and(|targets| {
        targets
            .iter()
            .filter_map(PublishTarget::ecosystem)
            .any(|ecosystem| ecosystem != Ecosystem::Pypi)
    }) {
        return Err(invalid_release_artifact(
            pattern,
            "a descriptor-bearing package cannot target a non-PyPI registry",
        ));
    }

    let mut descriptors = Vec::with_capacity(raw.len());
    let mut file_names = BTreeSet::new();
    let mut sdist_count = 0;
    for descriptor in raw {
        let format = match descriptor.format.as_str() {
            "wheel" => RegistryArtifactFormat::PythonWheel,
            "sdist" => {
                sdist_count += 1;
                RegistryArtifactFormat::PythonSdist
            }
            other => {
                return Err(invalid_release_artifact(
                    pattern,
                    format!("unsupported format {other:?}; expected wheel or sdist"),
                ))
            }
        };
        let template = descriptor.file_name.as_str();
        if template.matches("{version}").count() != 1
            || template
                .replace("{version}", "")
                .chars()
                .any(|character| matches!(character, '{' | '}'))
        {
            return Err(invalid_release_artifact(
                pattern,
                format!("file-name {template:?} must contain exactly one {{version}} placeholder and no others"),
            ));
        }
        let representative = template.replace("{version}", "1.0.0");
        if !release_artifact_file_name_is_safe(&representative, format) {
            return Err(invalid_release_artifact(
                pattern,
                format!(
                    "file-name {template:?} is unsafe or does not match format {:?}",
                    descriptor.format
                ),
            ));
        }
        if !file_names.insert(template.to_string()) {
            return Err(invalid_release_artifact(
                pattern,
                format!("file-name {template:?} is duplicated"),
            ));
        }
        descriptors.push(ReleaseArtifactDescriptor {
            format,
            file_name_template: template.to_string(),
        });
    }
    if sdist_count > 1 {
        return Err(invalid_release_artifact(
            pattern,
            "at most one sdist descriptor is allowed",
        ));
    }
    Ok(Some(descriptors))
}

fn release_artifact_file_name_is_safe(file_name: &str, format: RegistryArtifactFormat) -> bool {
    let safe = !file_name.is_empty()
        && file_name.len() <= 255
        && !file_name.contains("..")
        && file_name
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'_' | b'-'));
    safe && match format {
