        struct CountingRunner(AtomicUsize);

        impl CommandRunner for CountingRunner {
            fn run(&self, program: &str, _args: &[&str], _cwd: &Path) -> Result<CommandOutput, CommandError> {
                self.0.fetch_add(1, Ordering::SeqCst);
                Err(CommandError::Io {
                    program: program.to_owned(),
                    message: "membership failure must happen before any command".to_owned(),
                })
            }
        }

        let dir = tempfile::tempdir().unwrap();
        let root = dir.path();
        std::fs::write(root.join("Cargo.toml"), "[workspace]\nmembers = [\"").unwrap();
        std::fs::create_dir_all(root.join("crates/discoverable")).unwrap();
        std::fs::write(
            root.join("crates/discoverable/Cargo.toml"),
            "[package]\nname = \"discoverable\"\nversion = \"1.0.0\"\n",
        )
        .unwrap();

        let runner = CountingRunner(AtomicUsize::new(0));
        let locator = crate::IgnoreWalkLocator::new(root);
        let decision = ReleaseDecisionV1::new(vec![callisto_model::ReleaseDecisionEntry {
            package: ReleasePackageId::new(Ecosystem::Cargo, "discoverable").unwrap(),
            target_version: Version::parse("1.0.0", VersionGrammar::SemVer).unwrap(),
            reasons: vec![callisto_model::ReleaseInclusionReason::ExplicitSelection],
        }])
        .unwrap();
        let result = build_release_intent(root, &locator, &runner, &decision, "production");

        assert!(matches!(
            result,
            Err(GraphError::Locate(crate::LocateError::MembershipParse { .. }))
