mod tests {
    use callisto_model::{
        Ecosystem, ExecutionTrustProfileV1, OperationBlockReason, OperationOutcome, RegistryBindingDigest,
        RegistryBindingId, ReleaseInputSnapshotV1, ReleaseOperation, ReleasePackageId, SourceIdentity, Version,
    };

    use super::*;

    fn intent() -> ReleaseIntentV1 {
        let package = ReleasePackageId::new(Ecosystem::Cargo, "demo").unwrap();
        let version = Version::semver(1, 0, 0);
        let registry = RegistryBindingId::new(
            "crates",
            RegistryBindingDigest::from_normalized_binding(b"crates-default"),
        )
        .unwrap();
        let publish = ReleaseOperation::registry_publish(package.clone(), version.clone(), registry, vec![]).unwrap();
        let tag = ReleaseOperation::tag(package.clone(), version.clone(), vec![publish.id().clone()]).unwrap();
        let forge = ReleaseOperation::forge_release(package.clone(), version.clone(), vec![tag.id().clone()]).unwrap();
        ReleaseIntentV1::new(
            callisto_model::ReleaseDecisionV1::new(vec![callisto_model::ReleaseDecisionEntry {
                package: package.clone(),
                target_version: version.clone(),
                reasons: vec![callisto_model::ReleaseInclusionReason::ExplicitSelection],
            }])
            .unwrap(),
            ReleaseInputSnapshotV1::new(SourceIdentity::git_commit("a".repeat(40)).unwrap(), vec![]).unwrap(),
            ExecutionTrustProfileV1::GitCommit,
            vec![publish, tag, forge],
            vec![],
        )
        .unwrap()
    }

    fn artifact_slot(package: &ReleasePackageId, version: &Version) -> callisto_model::ArtifactSlotId {
        callisto_model::ArtifactSlotId::new(
            package.clone(),
            version.clone(),
            "x86_64-unknown-linux-gnu",
            "demo.tar.gz",
            callisto_model::GitHubRepository::parse("orin-dx/callisto").unwrap(),
            ".github/workflows/release.yml",
            callisto_model::CommitSha::parse(&"b".repeat(40)).unwrap(),
        )
        .unwrap()
    }

    /// An intent that declares exactly one compiled-binary artifact slot.
    fn intent_with_artifact_slot() -> (ReleaseIntentV1, callisto_model::ArtifactSlotId) {
        intent_with_artifact_slot_named("demo")
    }

    fn intent_with_artifact_slot_named(name: &str) -> (ReleaseIntentV1, callisto_model::ArtifactSlotId) {
        let package = ReleasePackageId::new(Ecosystem::Cargo, name).unwrap();
        let version = Version::semver(1, 0, 0);
        let slot = artifact_slot(&package, &version);
        let upload = ReleaseOperation::artifact_upload(slot.clone(), vec![]).unwrap();
        let intent = ReleaseIntentV1::new(
            callisto_model::ReleaseDecisionV1::new(vec![callisto_model::ReleaseDecisionEntry {
                package: package.clone(),
                target_version: version.clone(),
                reasons: vec![callisto_model::ReleaseInclusionReason::ExplicitSelection],
            }])
            .unwrap(),
            ReleaseInputSnapshotV1::new(SourceIdentity::git_commit("a".repeat(40)).unwrap(), vec![]).unwrap(),
            ExecutionTrustProfileV1::GitCommit,
            vec![upload],
            vec![slot.clone()],
        )
        .unwrap();
        (intent, slot)
    }

    /// A manifest that validates against `intent`.
    fn matching_artifact_manifest(
        intent: &ReleaseIntentV1,
        slot: callisto_model::ArtifactSlotId,
    ) -> callisto_model::ArtifactManifestV1 {
        let digest = callisto_model::ArtifactDigest::from_bytes(b"binary");
        callisto_model::ArtifactManifestV1::new(
            intent,
            vec![callisto_model::ArtifactManifestEntryV1 {
                slot,
                digest: digest.clone(),
                byte_length: 6,
                attestation: callisto_model::GitHubArtifactAttestationV1 {
                    repository: callisto_model::GitHubRepository::parse("orin-dx/callisto").unwrap(),
                    workflow_path: ".github/workflows/release.yml".to_string(),
                    workflow_commit: callisto_model::CommitSha::parse(&"b".repeat(40)).unwrap(),
                    subject_digest: digest,
                    source_commit: callisto_model::CommitSha::parse(&"a".repeat(40)).unwrap(),
                },
            }],
        )
        .unwrap()
    }

    /// Regression coverage for the confirmed bug: an intent declaring
    /// artifact slots but given no manifest at all must fail with a real,
    /// specific precondition -- not the unrelated `ReleaseIntentStale`.
    #[test]
    fn require_artifact_manifest_matches_intent_rejects_missing_manifest_for_slotted_intent() {
        let (intent, _slot) = intent_with_artifact_slot();
        let err = require_artifact_manifest_matches_intent(&intent, None).unwrap_err();
        assert!(
            matches!(
                err,
                GraphError::ReleasePreconditionUnmet {
                    requirement: ReleasePreconditionRequirement::ArtifactManifestProvided
                }
            ),
            "expected ReleasePreconditionUnmet(ArtifactManifestProvided), got {err:?}"
        );
    }

    /// Regression coverage: a manifest that fails validation (here, bound to
    /// a different intent) must surface the real `ArtifactManifestError`
    /// cause via `GraphError::ArtifactManifest`, not `ReleaseIntentStale`.
    #[test]
    fn require_artifact_manifest_matches_intent_rejects_a_manifest_that_fails_validation() {
        let (intent, slot) = intent_with_artifact_slot();
        let manifest = matching_artifact_manifest(&intent, slot);

        let (other_intent, _other_slot) = intent_with_artifact_slot_named("other-demo");
        let err = require_artifact_manifest_matches_intent(&other_intent, Some(&manifest)).unwrap_err();
        match err {
            GraphError::ArtifactManifest { source } => {
                assert_eq!(source, callisto_model::ArtifactManifestError::MismatchedIntent);
            }
            other => panic!("expected ArtifactManifest{{source: MismatchedIntent}}, got {other:?}"),
        }
    }

    /// A slot-less intent given no manifest must succeed (no behavior
    /// change from before this PR).
    #[test]
    fn require_artifact_manifest_matches_intent_accepts_no_manifest_for_slotless_intent() {
        let intent = intent();
        assert!(require_artifact_manifest_matches_intent(&intent, None).is_ok());
    }

    /// A slot-less intent given a valid, matching manifest must still
    /// succeed -- a manifest is never silently ignored just because the
    /// intent declared zero slots.
    #[test]
    fn require_artifact_manifest_matches_intent_accepts_a_valid_manifest_for_slotted_intent() {
        let (intent, slot) = intent_with_artifact_slot();
        let manifest = matching_artifact_manifest(&intent, slot);
        assert!(require_artifact_manifest_matches_intent(&intent, Some(&manifest)).is_ok());
    }

    #[test]
    fn reconciliation_requires_transitive_exact_successes() {
        let intent = intent();
        let mut state = ReleaseExecutionStateV1::pending(&intent);
        let publish = intent.operations[0].id().clone();
        let tag = intent.operations[1].id().clone();
        let forge = intent.operations[2].id().clone();

        assert_eq!(
            reconcile_release_execution(&intent, &state).unwrap().eligible(),
            std::slice::from_ref(&publish)
        );
        state.mark_attempting(&publish).unwrap();
        state.mark_terminal(&publish, OperationOutcome::Published).unwrap();
        assert_eq!(
            reconcile_release_execution(&intent, &state).unwrap().eligible(),
            std::slice::from_ref(&tag)
        );
        state.mark_attempting(&tag).unwrap();
        state.mark_terminal(&tag, OperationOutcome::AlreadySatisfied).unwrap();
        assert_eq!(
            reconcile_release_execution(&intent, &state).unwrap().eligible(),
            &[forge]
        );
    }

    #[test]
    fn non_successful_or_attempting_prerequisites_never_make_dependents_eligible() {
        let intent = intent();
        let publish = intent.operations[0].id().clone();
        let tag = intent.operations[1].id().clone();
        let mut state = ReleaseExecutionStateV1::pending(&intent);
        state.mark_attempting(&publish).unwrap();
        assert!(reconcile_release_execution(&intent, &state)
            .unwrap()
            .eligible()
            .is_empty());
        state
            .mark_terminal(
                &publish,
                OperationOutcome::Blocked {
                    reason: OperationBlockReason::IndeterminateAttempt,
                },
            )
            .unwrap();
        assert!(reconcile_release_execution(&intent, &state)
            .unwrap()
            .eligible()
            .is_empty());
        assert_eq!(state.operation_state(&tag), Some(OperationState::Pending));
    }

    #[test]
    fn direct_success_cannot_hide_an_unsatisfied_transitive_prerequisite() {
        let intent = intent();
        let publish = intent.operations[0].id().clone();
        let tag = intent.operations[1].id().clone();
        let forge = intent.operations[2].id().clone();
        let mut state = ReleaseExecutionStateV1::pending(&intent);

        // The model state machine deliberately does not own DAG policy. This
        // represents a corrupted or legacy executor having recorded tag
        // success before its publish prerequisite. Reconciliation must still
        // fail closed for the forge operation.
        state.mark_attempting(&tag).unwrap();
        state.mark_terminal(&tag, OperationOutcome::Published).unwrap();
        assert_eq!(state.operation_state(&publish), Some(OperationState::Pending));
        let reconciled = reconcile_release_execution(&intent, &state).unwrap();
        assert_eq!(reconciled.eligible(), &[publish]);
        assert!(!reconciled.eligible().contains(&forge));
    }
}
//! Narrow, explicit-path persistence for durable release execution state.
//!
//! The store owns no release policy and does not derive paths from mutable
//! workspace configuration. Callers must supply the state path deliberately.

use std::path::{Path, PathBuf};

use callisto_model::{atomic::atomic_write, ApplyPermit, ReleaseExecutionState, ReleaseIntent};

use crate::GraphError;

/// The only write seam used by [`ReleaseStateStore`]. Production writes use
/// Callisto's crash-safe atomic replacement primitive; tests can inject a
/// pre-rename failure without weakening that production path.
pub trait ReleaseStateWriter {
    fn write(&self, path: &Path, content: &str, permit: &ApplyPermit) -> std::io::Result<()>;
}

/// Production state writer backed by [`callisto_model::atomic::atomic_write`].
#[derive(Clone, Copy, Debug, Default)]
pub struct AtomicReleaseStateWriter;

impl ReleaseStateWriter for AtomicReleaseStateWriter {
    fn write(&self, path: &Path, content: &str, permit: &ApplyPermit) -> std::io::Result<()> {
        atomic_write(path, content, permit)
    }
}

/// Durable state store at one caller-chosen path.
#[derive(Debug)]
pub struct ReleaseStateStore<W = AtomicReleaseStateWriter> {
    path: PathBuf,
    writer: W,
}

impl ReleaseStateStore {
    /// Creates a production store at an explicit path.
    pub fn new(path: impl Into<PathBuf>) -> Self {
        Self::with_writer(path, AtomicReleaseStateWriter)
    }

    /// Creates a local state store outside the checkout, keyed by the exact
    /// durable intent. CI should use [`Self::new`] with an explicit path so a
    /// workflow artifact can hand state between jobs without using a cache.
    pub fn default_for(canonical_root: &Path, intent: &ReleaseIntent) -> Result<Self, GraphError> {
        let root = dunce::canonicalize(canonical_root).map_err(|error| GraphError::ReleaseStateRead {
            path: canonical_root.to_path_buf(),
            message: error.to_string(),
        })?;
        let mut transcript = callisto_model::CanonicalTranscript::semantic_input_v1();
        transcript.push_str("workspace-root", &root.to_string_lossy());
        let root_key = callisto_model::SemanticInputDigest::from_transcript(&transcript);
        let base = callisto_vcs::release_lock::platform_state_directory()?;
        Ok(Self::new(
            base.join("callisto")
                .join("release-state")
                .join(root_key.as_str())
                .join(format!("{}.json", intent.digest().as_str())),
        ))
    }
}

impl<W> ReleaseStateStore<W>
where
    W: ReleaseStateWriter,
{
    /// Creates a store with a narrow writer seam, primarily for deterministic
    /// failure tests. The path remains explicit and is never config-derived.
    pub fn with_writer(path: impl Into<PathBuf>, writer: W) -> Self {
        Self {
            path: path.into(),
            writer,
        }
    }

    /// Returns the caller-chosen durable state location.
    pub fn path(&self) -> &Path {
        &self.path
    }

    /// Loads state if it exists and rejects any state not exactly bound to
    /// `intent`. A missing file is not evidence of a completed release.
    pub fn load(&self, intent: &ReleaseIntent) -> Result<Option<ReleaseExecutionState>, GraphError> {
        let content = match std::fs::read_to_string(&self.path) {
            Ok(content) => content,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
            Err(error) => {
                return Err(GraphError::ReleaseStateRead {
                    path: self.path.clone(),
                    message: error.to_string(),
                });
            }
        };
        let state: ReleaseExecutionState =
            serde_json::from_str(&content).map_err(|error| GraphError::ReleaseStateDecode {
                path: self.path.clone(),
                message: error.to_string(),
            })?;
        state
            .validate_for_intent(intent)
            .map_err(|source| GraphError::ReleaseExecutionState { source })?;
        Ok(Some(state))
    }

    /// Loads existing state or atomically writes the exact pending roster.
    pub fn load_or_initialize(
        &self,
        intent: &ReleaseIntent,
        permit: &ApplyPermit,
    ) -> Result<ReleaseExecutionState, GraphError> {
        if let Some(state) = self.load(intent)? {
            return Ok(state);
        }
        let state = ReleaseExecutionState::pending(intent);
        self.save(intent, &state, permit)?;
        Ok(state)
    }

    /// Atomically persists only state proven to belong to `intent`.
    pub fn save(
        &self,
        intent: &ReleaseIntent,
        state: &ReleaseExecutionState,
        permit: &ApplyPermit,
    ) -> Result<(), GraphError> {
        state
            .validate_for_intent(intent)
            .map_err(|source| GraphError::ReleaseExecutionState { source })?;
        let content = serde_json::to_string_pretty(state).expect("release state serialization is infallible") + "\n";
        self.writer
            .write(&self.path, &content, permit)
            .map_err(|error| GraphError::ReleaseStateWrite {
                path: self.path.clone(),
                message: error.to_string(),
            })
    }
}

#[cfg(test)]
mod tests {
    use std::io;

    use callisto_model::{
        Ecosystem, GitHubRepository, ProductName, ProductReleaseId, ProductTarget, ProvenancePolicy,
        RegistryBindingDigest, RegistryBindingId, ReleaseArtifactSlot, ReleaseDecisionEntry, ReleaseDecisionV1,
        ReleaseDestinationBinding, ReleaseDestinationKind, ReleaseInclusionReason, ReleaseOperation,
        ReleaseOperationId, ReleasePackageId, Version,
    };
    use tempfile::tempdir;

    use super::*;

    fn intent(sha: char) -> ReleaseIntent {
        let package = ReleasePackageId::new(Ecosystem::Cargo, "demo").unwrap();
        let version = Version::semver(1, 0, 0);
        let release = ProductReleaseId::new(ProductName::parse("callisto").unwrap(), version.clone()).unwrap();
        let source = callisto_model::CommitSha::parse(&sha.to_string().repeat(40)).unwrap();
        let repository = GitHubRepository::parse("callisto-rs/callisto").unwrap();
        let binding = |name: &str| {
            RegistryBindingId::new(name, RegistryBindingDigest::from_normalized_binding(name.as_bytes())).unwrap()
        };
        let destination = ReleaseDestinationBinding::new(
            "production",
            ReleaseDestinationKind::Production,
            repository.clone(),
            binding("cargo"),
            binding("npm"),
            binding("pypi"),
        )
        .unwrap();
        let policy =
            ProvenancePolicy::new(repository, ".github/workflows/callisto-release.yml", source.clone()).unwrap();
        let mut slots = ProductTarget::ALL
            .into_iter()
            .map(|target| ReleaseArtifactSlot::product_asset(release.clone(), target, policy.clone()))
            .collect::<Vec<_>>();
        slots.push(ReleaseArtifactSlot::checksum_manifest(release.clone(), policy.clone()));
        slots.push(ReleaseArtifactSlot::release_metadata(release.clone(), policy));
        let tag = ReleaseOperationId::ProductTag {
            release: release.clone(),
            tag: release.tag(),
        };
        let prepare = ReleaseOperationId::ForgePrepare {
            release: release.clone(),
            repository: destination.forge_repository().clone(),
        };
        let mut operations = vec![
            ReleaseOperation::new(tag.clone(), vec![]).unwrap(),
            ReleaseOperation::new(prepare.clone(), vec![tag]).unwrap(),
        ];
        let mut uploads = slots
            .iter()
            .map(|slot| {
                ReleaseOperation::new(
                    ReleaseOperationId::ArtifactUpload {
                        release: release.clone(),
                        slot: slot.clone(),
                    },
                    vec![prepare.clone()],
                )
                .unwrap()
            })
            .collect::<Vec<_>>();
        uploads.sort_by(|left, right| left.id().cmp(right.id()));
        let upload_ids = uploads.iter().map(|operation| operation.id().clone()).collect();
        operations.extend(uploads);
        operations.push(
            ReleaseOperation::new(
                ReleaseOperationId::ForgePublish {
                    release: release.clone(),
                    repository: destination.forge_repository().clone(),
                },
                upload_ids,
            )
            .unwrap(),
        );
        ReleaseIntent::new(
            ReleaseDecisionV1::new(vec![ReleaseDecisionEntry {
                package: package.clone(),
                target_version: version,
                reasons: vec![ReleaseInclusionReason::ExplicitSelection],
            }])
            .unwrap(),
            release,
            source,
            destination,
            vec![],
            operations,
            slots,
        )
        .unwrap()
    }

    #[test]
    fn initializes_then_loads_exact_intent_bound_state() {
        let directory = tempdir().unwrap();
        let store = ReleaseStateStore::new(directory.path().join("state.json"));
        let intent = intent('a');
        let permit = ApplyPermit::force_for_tests();
        let initial = store.load_or_initialize(&intent, &permit).unwrap();
        assert_eq!(store.load(&intent).unwrap(), Some(initial));
        assert!(std::fs::read_to_string(store.path()).unwrap().contains("intentDigest"));
    }

    #[test]
    fn mismatched_intent_is_never_loaded_as_state() {
        let directory = tempdir().unwrap();
        let store = ReleaseStateStore::new(directory.path().join("state.json"));
        let permit = ApplyPermit::force_for_tests();
        store.load_or_initialize(&intent('a'), &permit).unwrap();
        assert!(matches!(
            store.load(&intent('b')),
            Err(GraphError::ReleaseExecutionState { .. })
        ));
    }

    #[test]
    fn default_state_path_is_outside_the_checkout_and_intent_bound() {
        let directory = tempdir().unwrap();
        let first = ReleaseStateStore::default_for(directory.path(), &intent('a')).unwrap();
        let second = ReleaseStateStore::default_for(directory.path(), &intent('b')).unwrap();
        assert_ne!(first.path(), second.path());
        assert!(!first.path().starts_with(directory.path()));
    }

    #[derive(Clone, Copy, Debug)]
    struct FailBeforeRename;

    impl ReleaseStateWriter for FailBeforeRename {
        fn write(&self, _path: &Path, _content: &str, _permit: &ApplyPermit) -> io::Result<()> {
