#[cfg(test)]
mod tests {
    use std::io;

    use callisto_model::{
        Ecosystem, GitHubRepository, ProductName, ProductReleaseId, ProductTarget, ProvenancePolicy,
        RegistryBindingDigest, RegistryBindingId, ReleaseArtifactSlot, ReleaseDecisionEntry, ReleaseDecisionV1,
        ReleaseDestinationBinding, ReleaseDestinationKind, ReleaseInclusionReason, ReleaseOperation,
        ReleaseOperationId, ReleasePackageId, Version,
    };
    use tempfile::tempdir;

    use super::*;

    fn intent(sha: char) -> ReleaseIntent {
        let package = ReleasePackageId::new(Ecosystem::Cargo, "demo").unwrap();
        let version = Version::semver(1, 0, 0);
        let release = ProductReleaseId::new(ProductName::parse("callisto").unwrap(), version.clone()).unwrap();
        let source = callisto_model::CommitSha::parse(&sha.to_string().repeat(40)).unwrap();
        let repository = GitHubRepository::parse("callisto-rs/callisto").unwrap();
        let binding = |name: &str| {
            RegistryBindingId::new(name, RegistryBindingDigest::from_normalized_binding(name.as_bytes())).unwrap()
        };
        let destination = ReleaseDestinationBinding::new(
            "production",
            ReleaseDestinationKind::Production,
            repository.clone(),
            binding("cargo"),
            binding("npm"),
            binding("pypi"),
        )
        .unwrap();
        let policy =
            ProvenancePolicy::new(repository, ".github/workflows/callisto-release.yml", source.clone()).unwrap();
        let mut slots = ProductTarget::ALL
            .into_iter()
            .map(|target| ReleaseArtifactSlot::product_asset(release.clone(), target, policy.clone()))
            .collect::<Vec<_>>();
        slots.push(ReleaseArtifactSlot::checksum_manifest(release.clone(), policy.clone()));
        slots.push(ReleaseArtifactSlot::release_metadata(release.clone(), policy));
        let tag = ReleaseOperationId::ProductTag {
            release: release.clone(),
            tag: release.tag(),
        };
        let prepare = ReleaseOperationId::ForgePrepare {
            release: release.clone(),
            repository: destination.forge_repository().clone(),
        };
        let mut operations = vec![
            ReleaseOperation::new(tag.clone(), vec![]).unwrap(),
            ReleaseOperation::new(prepare.clone(), vec![tag]).unwrap(),
        ];
        let mut uploads = slots
            .iter()
            .map(|slot| {
                ReleaseOperation::new(
                    ReleaseOperationId::ArtifactUpload {
                        release: release.clone(),
                        slot: slot.clone(),
                    },
                    vec![prepare.clone()],
                )
                .unwrap()
            })
            .collect::<Vec<_>>();
        uploads.sort_by(|left, right| left.id().cmp(right.id()));
        let upload_ids = uploads.iter().map(|operation| operation.id().clone()).collect();
        operations.extend(uploads);
        operations.push(
            ReleaseOperation::new(
                ReleaseOperationId::ForgePublish {
                    release: release.clone(),
                    repository: destination.forge_repository().clone(),
                },
                upload_ids,
            )
            .unwrap(),
        );
        ReleaseIntent::new(
            ReleaseDecisionV1::new(vec![ReleaseDecisionEntry {
                package: package.clone(),
                target_version: version,
                reasons: vec![ReleaseInclusionReason::ExplicitSelection],
            }])
            .unwrap(),
            release,
            source,
            destination,
            vec![],
            operations,
            slots,
        )
        .unwrap()
    }

    #[test]
    fn initializes_then_loads_exact_intent_bound_state() {
        let directory = tempdir().unwrap();
        let store = ReleaseStateStore::new(directory.path().join("state.json"));
        let intent = intent('a');
        let permit = ApplyPermit::force_for_tests();
        let initial = store.load_or_initialize(&intent, &permit).unwrap();
        assert_eq!(store.load(&intent).unwrap(), Some(initial));
        assert!(std::fs::read_to_string(store.path()).unwrap().contains("intentDigest"));
    }

    #[test]
    fn mismatched_intent_is_never_loaded_as_state() {
        let directory = tempdir().unwrap();
        let store = ReleaseStateStore::new(directory.path().join("state.json"));
        let permit = ApplyPermit::force_for_tests();
        store.load_or_initialize(&intent('a'), &permit).unwrap();
        assert!(matches!(
            store.load(&intent('b')),
            Err(GraphError::ReleaseExecutionState { .. })
        ));
    }

    #[test]
    fn default_state_path_is_outside_the_checkout_and_intent_bound() {
        let directory = tempdir().unwrap();
        let first = ReleaseStateStore::default_for(directory.path(), &intent('a')).unwrap();
        let second = ReleaseStateStore::default_for(directory.path(), &intent('b')).unwrap();
        assert_ne!(first.path(), second.path());
        assert!(!first.path().starts_with(directory.path()));
    }

    #[derive(Clone, Copy, Debug)]
    struct FailBeforeRename;

    impl ReleaseStateWriter for FailBeforeRename {
        fn write(&self, _path: &Path, _content: &str, _permit: &ApplyPermit) -> io::Result<()> {
            Err(io::Error::other("injected pre-rename failure"))
        }
    }

    #[test]
    fn injected_pre_rename_failure_never_becomes_successful_state() {
        let directory = tempdir().unwrap();
        let path = directory.path().join("state.json");
        let store = ReleaseStateStore::with_writer(&path, FailBeforeRename);
        let permit = ApplyPermit::force_for_tests();
        assert!(matches!(
            store.load_or_initialize(&intent('a'), &permit),
            Err(GraphError::ReleaseStateWrite { .. })
        ));
        assert_eq!(
            std::fs::read_to_string(path).unwrap_err().kind(),
            io::ErrorKind::NotFound
        );
    }

    #[test]
    fn failed_replacement_preserves_the_last_durable_state() {
        let directory = tempdir().unwrap();
        let path = directory.path().join("state.json");
        let permit = ApplyPermit::force_for_tests();
        let release_intent = intent('a');
        let production = ReleaseStateStore::new(&path);
        let pending = production.load_or_initialize(&release_intent, &permit).unwrap();

        let failing = ReleaseStateStore::with_writer(&path, FailBeforeRename);
        let operation = release_intent.operations()[0].id().clone();
        let mut changed = pending.clone();
        changed.mark_attempting(&operation).unwrap();
        assert!(matches!(
            failing.save(&release_intent, &changed, &permit),
            Err(GraphError::ReleaseStateWrite { .. })
        ));
        assert_eq!(production.load(&release_intent).unwrap(), Some(pending));
    }
}
