    pub(super) fn capability_workspace() -> (tempfile::TempDir, ReleaseDecisionV1) {
        let directory = tempfile::tempdir().unwrap();
        let root = directory.path();
        std::fs::write(
            root.join("Cargo.toml"),
            "[package]\nname = \"release-fixture\"\nversion = \"1.2.3\"\nedition = \"2021\"\n",
        )
        .unwrap();
        std::fs::write(
            root.join("package.json"),
            r#"{"name":"release-fixture","version":"1.2.3"}"#,
        )
        .unwrap();
        std::fs::write(
            root.join("pyproject.toml"),
            "[project]\nname = \"release-fixture\"\nversion = \"1.2.3\"\n",
        )
        .unwrap();
        std::fs::write(root.join("CHANGELOG.md"), "# Changelog\n\n## 1.2.3\n").unwrap();
        std::fs::write(
            root.join("callisto.toml"),
            r#"[release.product]
name = "release-fixture"
provenance-repository = "example/release-fixture"
build-workflow = ".github/workflows/release.yml"

[release.profiles.production]
kind = "production"
forge-repository = "example/release-fixture"
cargo-registry = "cargo"
npm-registry = "npm"
pypi-registry = "pypi"

[release.profiles.rehearsal]
kind = "rehearsal"
forge-repository = "example/release-fixture-rehearsal"
cargo-registry = "test-cargo"
npm-registry = "test-npm"
pypi-registry = "test-pypi"

[registries.cargo]
kind = "cargo"
index-url = "https://index.crates.io/"
