fn release_artifact_file_name_is_safe(file_name: &str, format: RegistryArtifactFormat) -> bool {
    let safe = !file_name.is_empty()
        && file_name.len() <= 255
        && !file_name.contains("..")
        && file_name
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'_' | b'-'));
    safe && match format {
        RegistryArtifactFormat::PythonWheel => file_name.ends_with(".whl"),
        RegistryArtifactFormat::PythonSdist => file_name.ends_with(".tar.gz"),
        _ => false,
    }
}

