fn resolve_release_config(
    raw: crate::config::raw::RawReleaseConfig,
    registries: &BTreeMap<RegistryKey, RegistryConfig>,
) -> Result<ReleaseConfig, ConfigError> {
    if !is_canonical_release_name(&raw.product.name) {
        return Err(ConfigError::InvalidReleaseProductName { name: raw.product.name });
    }
    let provenance_repository = parse_release_repository(
        "release.product.provenance-repository",
        &raw.product.provenance_repository,
    )?;
    if !is_safe_build_workflow(&raw.product.build_workflow) {
        return Err(ConfigError::InvalidReleaseWorkflow {
            workflow: raw.product.build_workflow,
        });
    }
    let product = ReleaseProductConfig {
        name: raw.product.name,
        provenance_repository,
        build_workflow: raw.product.build_workflow,
    };

    let mut profiles = BTreeMap::new();
    let mut production_profile = None;
    let mut rehearsal_count = 0usize;
    for (name, raw_profile) in raw.profiles {
        if !is_canonical_release_name(&name) {
            return Err(ConfigError::InvalidReleaseProfileName { name });
        }
        let kind = match raw_profile.kind.as_str() {
            "production" => ReleaseProfileKind::Production,
            "rehearsal" => ReleaseProfileKind::Rehearsal,
            _ => {
                return Err(ConfigError::InvalidReleaseProfileKind {
                    profile: name,
                    kind: raw_profile.kind,
                })
            }
        };
        let forge_repository =
            parse_release_repository("release.profiles.*.forge-repository", &raw_profile.forge_repository)?;
        let (cargo_registry, _) = registry_binding(registries, &name, &raw_profile.cargo_registry, Ecosystem::Cargo)?;
        let (npm_registry, _) = registry_binding(registries, &name, &raw_profile.npm_registry, Ecosystem::Npm)?;
        let (pypi_registry, _) = registry_binding(registries, &name, &raw_profile.pypi_registry, Ecosystem::Pypi)?;

        if kind == ReleaseProfileKind::Production {
            if production_profile.replace(name.clone()).is_some() {
                return Err(ConfigError::InvalidProductionProfileCount { found: 2 });
            }
        } else {
            rehearsal_count += 1;
        }
        profiles.insert(
            name,
            ReleaseProfileConfig {
                kind,
                forge_repository,
                cargo_registry,
