            raw_pkg.pre_major_inference.as_deref(),
            raw_pkg.publish_to.as_deref(),
        )?;
        cfg.release_artifacts = parse_release_artifacts(&pattern, &cfg, raw_pkg.release_artifact.as_deref())?;

