/// Validates an intent while placing its workspace lock under an explicit
/// caller-owned state directory.
///
/// CI callers that supply an explicit durable state file must use its parent
/// here as well.  Otherwise validation would still depend on the runner's
/// implicit platform state location, defeating hermetic job handoff.
pub fn validate_release_intent_with_state_directory<'a, L: ProjectLocator, R: CommandRunner>(
    root: &Path,
    locator: &L,
    runner: &'a R,
    state_directory: Option<&Path>,
    received: ReleaseIntent,
) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
    let root = canonical_root(root)?;
    let workspace = Workspace::load(root.clone(), locator, runner)?;
    let initial_trust = observe_git_trust(&workspace)?;
    let lock = ReleaseWorkspaceLock::acquire(&root, state_directory)?;
    let trust = observe_git_trust(&workspace)?;
    if trust != initial_trust {
        return Err(GraphError::ReleaseIntentStale {
            reason: StaleReason::trust_evidence_changed(),
        });
    }
    let source = trust.head().clone();
    let approved_decision = super::release_decision::derive_release_commit_decision(
        &workspace,
        received.source_commit(),
        Path::new(super::release_decision::CANONICAL_RELEASE_DECISION_PATH),
    )?;
    if &approved_decision != received.decision() {
        return Err(GraphError::ReleaseIntentStale {
            reason: StaleReason::intent_differs_from_fresh_derivation(),
        });
    }
    let prepared = derive_product_release(
        &workspace,
        &approved_decision,
        source.clone(),
        received.destination().profile_name(),
    )?;
    let final_trust = observe_git_trust(&workspace)?;
    if prepared.intent != received || final_trust != trust {
        return Err(GraphError::ReleaseIntentStale {
            reason: StaleReason::intent_differs_from_fresh_derivation(),
        });
    }

    Ok(ValidatedReleaseIntent {
        prepared: PreparedReleaseInputs {
            root,
            source,
            trust: final_trust,
        OutputFormat::Json => write_json(&mut std::io::stdout(), report.eligible())?,
        OutputFormat::Text => {
            for operation in report.eligible() {
                println!("eligible: {operation:?}");
            }
        }
    }
    Ok(ExitCode::SUCCESS)
}

fn execute(args: ReleaseExecuteArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let intent = read_intent(&args.intent)?;
    match (
        intent.artifact_slots.is_empty(),
        args.artifact_manifest.as_ref(),
        args.artifact_dir.as_deref(),
    ) {
        (true, None, None) => {}
        (true, _, _) => {
            return Err(CliError::Other(
                "release intent declares no binary artifact slots; omit --artifact-manifest and --artifact-dir"
                    .to_owned(),
            ));
        }
        (false, Some(_), Some(_)) => {}
        (false, _, _) => {
            return Err(CliError::Other(
                "release intent declares binary artifact slots; provide both --artifact-manifest and --artifact-dir"
                    .to_owned(),
            ));
        }
    }

    // Revalidate workspace membership and intent before artifact attestation
    // can invoke the command runner (which snapshots credential environment
    // values) or reach any Git/provider operation.
    let runner = CliCommandRunner;
    let root = dunce::canonicalize(&global.cwd).map_err(|source| CliError::Io {
        source,
        path: Some(global.cwd.clone()),
    })?;
    let locator = IgnoreWalkLocator::new(&root);
    let explicit_state_directory = args.state.as_deref().and_then(std::path::Path::parent);
    let capability =
        validate_release_intent_with_state_directory(&root, &locator, &runner, explicit_state_directory, intent)?;
    let manifest = args
        .artifact_manifest
        .as_deref()
        .map(read_artifact_manifest)
        .transpose()?;
    if let (Some(manifest), Some(directory)) = (manifest.as_ref(), args.artifact_dir.as_deref()) {
        verify_artifact_manifest(capability.intent(), manifest, directory, &runner)?;
    }
    let store = match args.state {
        Some(path) => ReleaseStateStore::new(path),
        None => ReleaseStateStore::default_for(&root, capability.intent())?,
    };
    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run).ok_or_else(|| {
        CliError::Other(
            "release execute cannot run with --dry-run; use release reconcile for a read-only readiness check"
                .to_string(),
        )
    })?;
    let state = execute_release_with_artifacts(&capability, &store, &permit, manifest.as_ref())?;
    match global.format {
        OutputFormat::Json => write_json(&mut std::io::stdout(), &state)?,
        OutputFormat::Text => println!("Release execution state saved to {}", store.path().display()),
    }
    Ok(ExitCode::SUCCESS)
}

