            .ok_or(ObservationFailure::MalformedResponse {
                provider: ObservationProvider::Pypi,
            })?
            .to_string();
        let byte_length =
            file.get("size")
                .and_then(serde_json::Value::as_u64)
                .ok_or(ObservationFailure::MalformedResponse {
                    provider: ObservationProvider::Pypi,
                })?;
        let digest = file
            .get("digests")
            .and_then(|digests| digests.get("sha256"))
            .and_then(serde_json::Value::as_str)
            .and_then(|raw| ArtifactDigest::parse(raw).ok())
            .ok_or_else(|| ObservationFailure::MissingDigest {
                provider: ObservationProvider::Pypi,
                file_name: file_name.clone(),
            })?;
        if distributions
            .insert(file_name, PypiDistribution { digest, byte_length })
            .is_some()
        {
            return Err(ObservationFailure::MalformedResponse {
                provider: ObservationProvider::Pypi,
            });
        }
    }
    Ok(Some(distributions))
}

fn observe_npm_artifact(
    validated: &ValidatedReleaseIntent<'_>,
    package: &str,
    version: &Version,
    registry: &str,
    expected_file_name: &str,
    expected_length: u64,
) -> Result<NpmArtifactObservation, ObservationFailure> {
    let directory = tempfile::tempdir().map_err(|_| ObservationFailure::Capability {
        provider: ObservationProvider::Npm,
    })?;
    let spec = format!("{package}@{}", version.render());
    let destination = directory.path().to_string_lossy();
    let args = [
        "pack",
        spec.as_str(),
        "--json",
        "--ignore-scripts",
        "--pack-destination",
        destination.as_ref(),
        "--registry",
        registry,
    ];
    let output = validated
        .runner()
        .run_quiet("npm", &args, validated.root(), OBSERVATION_TIMEOUT)
        .map_err(|_| ObservationFailure::Command {
            provider: ObservationProvider::Npm,
        })?;
    if !output.success() {
        if npm_structured_error_code(&output).is_some_and(|code| matches!(code.as_str(), "E404" | "ETARGET")) {
            return Ok(NpmArtifactObservation::Absent);
        }
        return Err(ObservationFailure::Command {
            provider: ObservationProvider::Npm,
        });
    }
    let value: serde_json::Value =
        serde_json::from_str(&output.stdout).map_err(|_| ObservationFailure::MalformedResponse {
            provider: ObservationProvider::Npm,
        })?;
    let entries = value.as_array().ok_or(ObservationFailure::MalformedResponse {
        provider: ObservationProvider::Npm,
    })?;
    if entries.len() != 1 {
        return Err(ObservationFailure::MalformedResponse {
            provider: ObservationProvider::Npm,
        });
    }
    let file_name = entries[0].get("filename").and_then(serde_json::Value::as_str).ok_or(
        ObservationFailure::MalformedResponse {
            provider: ObservationProvider::Npm,
        },
    )?;
    let declared_length =
        entries[0]
            .get("size")
            .and_then(serde_json::Value::as_u64)
            .ok_or(ObservationFailure::MalformedResponse {
                provider: ObservationProvider::Npm,
            })?;
    inspect_npm_artifact(
        directory.path(),
        file_name,
        declared_length,
        expected_file_name,
        expected_length,
    )
}

fn inspect_npm_artifact(
    directory: &Path,
    file_name: &str,
    declared_length: u64,
    expected_file_name: &str,
    expected_length: u64,
) -> Result<NpmArtifactObservation, ObservationFailure> {
    let relative = Path::new(file_name);
    if file_name != expected_file_name
        || relative.components().count() != 1
        || !matches!(relative.components().next(), Some(std::path::Component::Normal(_)))
    {
        return Err(ObservationFailure::MalformedResponse {
            provider: ObservationProvider::Npm,
        });
    }
    let path = directory.join(relative);
    let metadata = std::fs::symlink_metadata(&path).map_err(|_| ObservationFailure::MalformedResponse {
        provider: ObservationProvider::Npm,
    })?;
    if metadata.file_type().is_symlink() || !metadata.is_file() || metadata.len() != declared_length {
        return Err(ObservationFailure::MalformedResponse {
            provider: ObservationProvider::Npm,
        });
    }
    if metadata.len() != expected_length {
        return Ok(NpmArtifactObservation::LengthMismatch(metadata.len()));
    }
    let file = File::open(path).map_err(|_| ObservationFailure::MalformedResponse {
        provider: ObservationProvider::Npm,
    })?;
    let (digest, byte_length) =
        ArtifactDigest::from_reader(file).map_err(|_| ObservationFailure::MalformedResponse {
            provider: ObservationProvider::Npm,
        })?;
    if byte_length != expected_length {
        return Ok(NpmArtifactObservation::LengthMismatch(byte_length));
    }
    Ok(NpmArtifactObservation::Bytes(digest))
}

fn npm_structured_error_code(output: &CommandOutput) -> Option<String> {
    [&output.stdout, &output.stderr].into_iter().find_map(|stream| {
        let value: serde_json::Value = serde_json::from_str(stream.trim()).ok()?;
        value
            .get("error")
            .and_then(|error| error.get("code"))
            .or_else(|| value.get("code"))
            .and_then(serde_json::Value::as_str)
            .map(str::to_string)
    })
}

fn observe_json_http(
    runner: &dyn callisto_model::CommandRunner,
    root: &Path,
    url: &str,
    provider: ObservationProvider,
) -> Result<Option<serde_json::Value>, ObservationFailure> {
    let args = [
        "--silent",
        "--show-error",
        "--location",
        "--include",
        "--request",
        "GET",
        url,
    ];
    let output = runner
        .run_quiet("curl", &args, root, OBSERVATION_TIMEOUT)
        .map_err(|_| ObservationFailure::Command { provider })?;
    if !output.success() {
        return Err(ObservationFailure::Command { provider });
    }
    let (status, body) = parse_http_response(&output).ok_or(ObservationFailure::MalformedResponse { provider })?;
    if status == 404 {
        return Ok(None);
    }
    if status != 200 {
        return Err(ObservationFailure::HttpStatus { provider, status });
    }
    serde_json::from_str(body)
        .map(Some)
        .map_err(|_| ObservationFailure::MalformedResponse { provider })
}

fn parse_http_response(output: &CommandOutput) -> Option<(u16, &str)> {
    parse_http_stream(&output.stdout).or_else(|| parse_http_stream(&output.stderr))
}

fn parse_http_stream(stream: &str) -> Option<(u16, &str)> {
    let (headers, body) = stream.rsplit_once("\r\n\r\n").or_else(|| stream.rsplit_once("\n\n"))?;
    let status = headers
        .lines()
        .rev()
        .find(|line| line.trim_end_matches('\r').starts_with("HTTP/"))?
        .split_whitespace()
        .nth(1)?
        .parse()
        .ok()?;
    Some((status, body))
