/// A release-plan command must not turn malformed root membership into a
/// broader roster. The fixture contains a real child package that would be
/// discoverable if Cargo membership were silently treated as absent.
#[test]
fn malformed_root_membership_rejects_release_plan_before_any_intent_or_git_mutation() {
    let (dir, release_commit) = release_commit_fixture();
    let root = dir.path();
    let original_manifest = fs::read_to_string(root.join("Cargo.toml")).unwrap();
    let decision_before = fs::read(root.join(DECISION_PATH)).unwrap();
    let head_before = git(root, &["rev-parse", "HEAD"]);
    let external = tempfile::tempdir().unwrap();
    let out = external.path().join("must-not-exist.json");

    // Preserve the root marker while making the membership field malformed.
    // `crates/core` remains an otherwise discoverable package below it.
    fs::write(root.join("Cargo.toml"), "[workspace]\nmembers = [\"").unwrap();

    let result = callisto(
        root,
        &[
            "release",
            "plan",
            "--from-release-commit",
            &release_commit,
            "--decision",
            DECISION_PATH,
            "--out",
            out.to_str().unwrap(),
        ],
    );

    assert!(
        !result.status.success(),
        "malformed root authority must reject release planning rather than admit crates/core"
    );
    let report: serde_json::Value = serde_json::from_slice(&result.stderr).unwrap();
    assert!(
        report["error"]["code"]
            .as_str()
            .is_some_and(|code| code.contains("E173")),
        "release plan must surface the graph-owned membership parse diagnostic, got: {report}"
    );
    assert!(
        !out.exists(),
        "failed discovery must not construct or persist an executable release intent"
    );
    assert_eq!(
        fs::read(root.join(DECISION_PATH)).unwrap(),
        decision_before,
        "failed discovery must stop before consuming or replacing the persisted release decision"
    );
    assert_eq!(
        git(root, &["rev-parse", "HEAD"]),
        head_before,
        "release planning must not mutate Git before malformed authority is rejected"
    );
    assert_eq!(
        fs::read_to_string(root.join("Cargo.toml")).unwrap(),
        "[workspace]\nmembers = [\"",
        "release planning must not rewrite manifests before malformed authority is rejected"
    );
    assert_ne!(
        original_manifest,
        fs::read_to_string(root.join("Cargo.toml")).unwrap(),
        "the assertion must exercise the malformed authority rather than the valid fixture"
    );
}

