fn policy() -> ProvenancePolicy {
    ProvenancePolicy::new(
        GitHubRepository::parse("owner/repository").unwrap(),
        ".github/workflows/release.yml",
        commit('b'),
    )
    .unwrap()
}

fn release() -> ProductReleaseId {
    ProductReleaseId::new(ProductName::parse("callisto").unwrap(), Version::semver(1, 2, 3)).unwrap()
}

fn binding(key: &str, endpoint: &str) -> RegistryBindingId {
    RegistryBindingId::new(key, RegistryBindingDigest::from_normalized_binding(endpoint)).unwrap()
}

fn destination() -> ReleaseDestinationBinding {
    ReleaseDestinationBinding::new(
        "production",
        ReleaseDestinationKind::Production,
        GitHubRepository::parse("owner/repository").unwrap(),
        binding("cargo", "https://index.crates.io/"),
        binding("npm", "https://registry.npmjs.org/"),
        binding("pypi", "https://upload.pypi.org/legacy/"),
    )
    .unwrap()
}

fn slots(release: &ProductReleaseId) -> Vec<ReleaseArtifactSlot> {
    ProductTarget::ALL
        .into_iter()
        .map(|target| ReleaseArtifactSlot::product_asset(release.clone(), target, policy()))
        .chain([
            ReleaseArtifactSlot::checksum_manifest(release.clone(), policy()),
            ReleaseArtifactSlot::release_metadata(release.clone(), policy()),
        ])
        .collect()
}

fn operations(release: &ProductReleaseId, slots: &[ReleaseArtifactSlot]) -> Vec<ReleaseOperation> {
    let tag = ReleaseOperationId::ProductTag {
        release: release.clone(),
        tag: release.tag(),
    };
    let prepare = ReleaseOperationId::ForgePrepare {
        release: release.clone(),
        repository: GitHubRepository::parse("owner/repository").unwrap(),
    };
    let mut uploads = slots
        .iter()
        .map(|slot| {
            ReleaseOperation::new(
                ReleaseOperationId::ArtifactUpload {
                    release: release.clone(),
                    slot: slot.clone(),
                },
                vec![prepare.clone()],
            )
            .unwrap()
        })
        .collect::<Vec<_>>();
    uploads.sort_by(|left, right| left.id().cmp(right.id()));
    let upload_ids = uploads.iter().map(|operation| operation.id().clone()).collect();
    let mut result = vec![
        ReleaseOperation::new(tag.clone(), vec![]).unwrap(),
        ReleaseOperation::new(prepare, vec![tag]).unwrap(),
    ];
    result.extend(uploads);
    result.push(
        ReleaseOperation::new(
            ReleaseOperationId::ForgePublish {
                release: release.clone(),
                repository: GitHubRepository::parse("owner/repository").unwrap(),
            },
            upload_ids,
        )
        .unwrap(),
    );
    result
}

fn intent(source: char) -> ReleaseIntent {
    let release = release();
    let slots = slots(&release);
    ReleaseIntent::new(
        ReleaseDecisionV1::new(vec![ReleaseDecisionEntry {
            package: ReleasePackageId::parse("cargo/callisto-cli").unwrap(),
            target_version: release.version().clone(),
            reasons: vec![ReleaseInclusionReason::ExplicitSelection],
        }])
        .unwrap(),
        release.clone(),
        commit(source),
        destination(),
        vec![],
        operations(&release, &slots),
        slots,
    )
    .unwrap()
}

struct Fixture {
    intent: ReleaseIntent,
    manifest: ReleaseArtifactManifest,
    files: BTreeMap<ReleaseArtifactSlot, Vec<u8>>,
}

fn fixture(source: char) -> Fixture {
    let intent = intent(source);
    let mut files = BTreeMap::new();
    let entries = intent
        .slots()
        .iter()
        .filter(|slot| matches!(slot, ReleaseArtifactSlot::ProductAsset { .. }))
        .cloned()
        .map(|slot| {
            let bytes = format!("trusted payload:{}", slot.file_name()).into_bytes();
            files.insert(slot.clone(), bytes.clone());
            ReleaseArtifactEntry::new(
                slot.clone(),
                ArtifactDigest::from_bytes(&bytes),
                bytes.len() as u64,
                intent.source_commit().clone(),
                slot.policy().clone(),
            )
            .unwrap()
        })
        .collect();
    let payloads = ValidatedPayloadEntries::new(&intent, entries).unwrap();
    let bundle = ReleaseArtifactManifest::complete_with_generated_files(&intent, &payloads).unwrap();
    let metadata_slot = intent
        .slots()
        .iter()
        .find(|slot| matches!(slot, ReleaseArtifactSlot::ReleaseMetadata { .. }))
        .unwrap()
        .clone();
    files.insert(metadata_slot, bundle.metadata_bytes().to_vec());
    let checksum_slot = intent
        .slots()
        .iter()
        .find(|slot| matches!(slot, ReleaseArtifactSlot::ChecksumManifest { .. }))
        .unwrap()
        .clone();
    files.insert(checksum_slot, bundle.checksum_bytes().to_vec());
    Fixture {
        intent,
        manifest: bundle.manifest().clone(),
        files,
    }
}

fn write_fixture(fixture: &Fixture, root: &Path) {
    for (slot, bytes) in &fixture.files {
        fs::write(root.join(slot.file_name()), bytes).unwrap();
    }
}

