struct Fixture {
    intent: ReleaseIntent,
    manifest: ReleaseArtifactManifest,
    files: BTreeMap<ReleaseArtifactSlot, Vec<u8>>,
}

fn fixture(source: char) -> Fixture {
    let intent = intent(source);
    let mut files = BTreeMap::new();
    let entries = intent
        .slots()
        .iter()
        .filter(|slot| matches!(slot, ReleaseArtifactSlot::ProductAsset { .. }))
        .cloned()
        .map(|slot| {
            let bytes = format!("trusted payload:{}", slot.file_name()).into_bytes();
            files.insert(slot.clone(), bytes.clone());
            ReleaseArtifactEntry::new(
                slot.clone(),
                ArtifactDigest::from_bytes(&bytes),
                bytes.len() as u64,
                intent.source_commit().clone(),
                slot.policy().clone(),
            )
            .unwrap()
        })
        .collect();
    let payloads = ValidatedPayloadEntries::new(&intent, entries).unwrap();
    let bundle = ReleaseArtifactManifest::complete_with_generated_files(&intent, &payloads).unwrap();
    let metadata_slot = intent
        .slots()
        .iter()
        .find(|slot| matches!(slot, ReleaseArtifactSlot::ReleaseMetadata { .. }))
        .unwrap()
        .clone();
    files.insert(metadata_slot, bundle.metadata_bytes().to_vec());
    let checksum_slot = intent
        .slots()
        .iter()
        .find(|slot| matches!(slot, ReleaseArtifactSlot::ChecksumManifest { .. }))
        .unwrap()
        .clone();
    files.insert(checksum_slot, bundle.checksum_bytes().to_vec());
    Fixture {
        intent,
        manifest: bundle.manifest().clone(),
        files,
    }
}

fn write_fixture(fixture: &Fixture, root: &Path) {
    for (slot, bytes) in &fixture.files {
        fs::write(root.join(slot.file_name()), bytes).unwrap();
    }
