fn slot_bytes(slot: &ReleaseArtifactSlot) -> Vec<u8> {
    if let ReleaseArtifactSlot::RegistryPackage {
        package,
        version,
        format: RegistryArtifactFormat::CargoCrate,
        ..
    } = slot
    {
        let encoder = flate2::write::GzEncoder::new(Vec::new(), flate2::Compression::default());
        let mut archive = tar::Builder::new(encoder);
        let manifest = format!(
            "[package]\nname = {:?}\nversion = {:?}\nedition = \"2021\"\n",
            package.name(),
            version.render()
        );
        let mut header = tar::Header::new_gnu();
        header.set_size(manifest.len() as u64);
        header.set_mode(0o644);
        header.set_cksum();
        archive
            .append_data(
                &mut header,
                format!("{}-{}/Cargo.toml", package.name(), version.render()),
                manifest.as_bytes(),
            )
            .unwrap();
        return archive.into_inner().unwrap().finish().unwrap();
    }
    format!("verified bytes for {}\n", slot.file_name()).into_bytes()
}

pub(crate) fn artifact_fixture<'intent, 'runner>(
    validated: &'intent ValidatedReleaseIntent<'runner>,
    runner: &CapabilityRunner,
) -> (tempfile::TempDir, ValidatedArtifactManifest<'intent, 'runner>) {
    let directory = tempfile::tempdir().unwrap();
    let mut entries = Vec::new();
    for slot in validated.intent().slots().iter().filter(|slot| {
        matches!(
            slot,
            ReleaseArtifactSlot::RegistryPackage { .. } | ReleaseArtifactSlot::ProductAsset { .. }
        )
    }) {
        let bytes = slot_bytes(slot);
        std::fs::write(directory.path().join(slot.file_name()), &bytes).unwrap();
        entries.push(
            ReleaseArtifactEntry::new(
                slot.clone(),
                ArtifactDigest::from_bytes(&bytes),
                bytes.len() as u64,
                validated.intent().source_commit().clone(),
                slot.policy().clone(),
            )
            .unwrap(),
        );
    }
    let payloads = ValidatedPayloadEntries::new(validated.intent(), entries).unwrap();
    let bundle =
        callisto_model::ReleaseArtifactManifest::complete_with_generated_files(validated.intent(), &payloads)
            .unwrap();
    for slot in validated.intent().slots() {
        match slot {
            ReleaseArtifactSlot::ReleaseMetadata { .. } => {
                std::fs::write(directory.path().join(slot.file_name()), bundle.metadata_bytes()).unwrap();
            }
            ReleaseArtifactSlot::ChecksumManifest { .. } => {
                std::fs::write(directory.path().join(slot.file_name()), bundle.checksum_bytes()).unwrap();
            }
            _ => {}
        }
    }
    let manifest = bundle.manifest().clone();
    let artifacts =
        super::super::release_artifacts::verify_artifact_manifest(validated, manifest, directory.path(), runner)
            .unwrap();
    (directory, artifacts)
}

