            if prerequisites.windows(2).any(|pair| pair[0] == pair[1]) || prerequisites.contains(&id) {
                return Err(SuccessorError::InvalidPrerequisite);
            }
            Ok(Self { id, prerequisites })
        }

        pub fn id(&self) -> &ReleaseOperationId {
            &self.id
        }

        pub fn prerequisites(&self) -> &[ReleaseOperationId] {
            &self.prerequisites
        }
    }

    #[derive(Clone, Debug, PartialEq, Eq, Serialize, JsonSchema)]
    #[serde(rename_all = "camelCase", deny_unknown_fields)]
    pub struct ReleaseIntent {
        schema_version: u8,
        decision: ReleaseDecisionV1,
        product_release: ProductReleaseId,
        source_commit: CommitSha,
        destination: ReleaseDestinationBinding,
        registry_artifacts: Vec<ApprovedRegistryArtifact>,
        operations: Vec<ReleaseOperation>,
        slots: Vec<ReleaseArtifactSlot>,
        digest: IntentDigest,
    }

    #[derive(Deserialize)]
    #[serde(rename_all = "camelCase", deny_unknown_fields)]
    struct ReleaseIntentWire {
        schema_version: u8,
        decision: ReleaseDecisionV1,
        product_release: ProductReleaseId,
        source_commit: CommitSha,
        destination: ReleaseDestinationBinding,
        registry_artifacts: Vec<ApprovedRegistryArtifact>,
        operations: Vec<ReleaseOperation>,
        slots: Vec<ReleaseArtifactSlot>,
        digest: IntentDigest,
    }

    impl ReleaseIntent {
        pub const SCHEMA_VERSION: u8 = 1;

        pub fn new(
            decision: ReleaseDecisionV1,
            product_release: ProductReleaseId,
            source_commit: CommitSha,
            destination: ReleaseDestinationBinding,
            mut registry_artifacts: Vec<ApprovedRegistryArtifact>,
            operations: Vec<ReleaseOperation>,
            mut slots: Vec<ReleaseArtifactSlot>,
        ) -> Result<Self, SuccessorError> {

        pub fn mark_terminal(
            &mut self,
            id: &ReleaseOperationId,
            outcome: OperationOutcome,
        ) -> Result<(), ReleaseExecutionStateError> {
            let state = self
                .operations
                .get_mut(id)
                .ok_or_else(|| ReleaseExecutionStateError::UnknownOperation {
                    id: Box::new(id.clone()),
                })?;
            if *state != ReleaseOperationState::Attempting {
                return Err(ReleaseExecutionStateError::InvalidTransition {
                    id: Box::new(id.clone()),
                    from: *state,
                });
            }
            *state = match outcome {
                OperationOutcome::Published => ReleaseOperationState::Published,
                OperationOutcome::AlreadySatisfied => ReleaseOperationState::AlreadySatisfied,
                OperationOutcome::Failed => ReleaseOperationState::Failed,
                OperationOutcome::Blocked { reason } => ReleaseOperationState::Blocked { reason },
            };
            Ok(())
        }

        fn from_wire(wire: ReleaseExecutionStateWire) -> Result<Self, ReleaseExecutionStateError> {
            if wire.schema_version != Self::SCHEMA_VERSION {
                return Err(ReleaseExecutionStateError::UnsupportedSchema {
                    found: wire.schema_version,
                });
            }
            let mut operations = BTreeMap::new();
            for entry in wire.operations {
                if operations.insert(entry.operation.clone(), entry.state).is_some() {
                    return Err(ReleaseExecutionStateError::DuplicateOperation {
                        id: Box::new(entry.operation),
                    });
                }
            }
            Ok(Self {
                schema_version: wire.schema_version,
                intent_digest: wire.intent_digest,
                operations,
            })
        }
    }

    #[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
    #[non_exhaustive]
    pub enum ReleaseExecutionStateError {
        #[error("unsupported release execution state schema version {found}")]
        UnsupportedSchema { found: u8 },
        #[error("release state is bound to a different intent")]
        MismatchedIntent,
        #[error("release state operation roster differs from the bound intent")]
        MismatchedOperationRoster,
        #[error("release state contains duplicate operation `{id:?}`")]
        DuplicateOperation { id: Box<ReleaseOperationId> },
        #[error("release state does not contain operation `{id:?}`")]
        UnknownOperation { id: Box<ReleaseOperationId> },
        #[error("operation `{id:?}` cannot transition from {from:?}")]
        InvalidTransition {
            id: Box<ReleaseOperationId>,
            from: ReleaseOperationState,
        },
    }

    fn validate_decision(
        decision: &ReleaseDecisionV1,
        release: &ProductReleaseId,
        approved: &[ApprovedRegistryArtifact],
    ) -> Result<(), SuccessorError> {
        let derived = ProductReleaseId::from_coordinated_versions(
            release.product.clone(),
            decision.entries.iter().map(|entry| entry.target_version.clone()),
        )?;
        if &derived != release {
            return Err(SuccessorError::DecisionProductMismatch);
        }
        let decision_versions = decision
            .entries
            .iter()
            .map(|entry| (&entry.package, &entry.target_version))
            .collect::<BTreeMap<_, _>>();
        if approved.iter().any(|entry| {
            decision_versions
                .get(&entry.package)
                .is_none_or(|version| version.render() != release.version.render())
        }) {
            return Err(SuccessorError::RegistryArtifactOutsideDecision);
        }
        Ok(())
    }

    fn validate_slot_roster(
        release: &ProductReleaseId,
        destination: &ReleaseDestinationBinding,
        approved: &[ApprovedRegistryArtifact],
        slots: &[ReleaseArtifactSlot],
    ) -> Result<(), SuccessorError> {
        if slots.windows(2).any(|pair| pair[0] == pair[1]) {
            return Err(SuccessorError::DuplicateSlot);
        }
        for slot in slots {
            slot.validate(release)?;
        }
        let mut product_policies = slots.iter().filter_map(|slot| match slot {
            ReleaseArtifactSlot::ProductAsset { provenance_policy, .. } => Some(provenance_policy),
            _ => None,
        });
        if let Some(first) = product_policies.next() {
            if product_policies.any(|policy| policy != first) {
                return Err(SuccessorError::HeterogeneousProductProvenance);
            }
        }
        if approved
            .iter()
            .any(|entry| destination.registry_for(entry.package.ecosystem()).ok() != Some(&entry.registry))
        {
            return Err(SuccessorError::RegistryDestinationMismatch);
        }
        let registry_slots = slots
            .iter()
            .filter_map(|slot| match slot {
                ReleaseArtifactSlot::RegistryPackage {
                    package,
                    version,
                    registry,
                    format,
                    publication_policy,
                    file_name,
                    ..
                } if version.render() == release.version.render() => Some(ApprovedRegistryArtifact {
                    package: package.clone(),
                    registry: registry.clone(),
                    format: *format,
                    publication_policy: publication_policy.clone(),
                    file_name: file_name.clone(),
                }),
                _ => None,
            })
            .collect::<BTreeSet<_>>();
        if registry_slots.len()
            != slots
                .iter()
                .filter(|slot| matches!(slot, ReleaseArtifactSlot::RegistryPackage { .. }))
                .count()
            || registry_slots.iter().ne(approved.iter())
        {
            return Err(SuccessorError::RegistrySlotOutsideApprovedRoster);
        }
        let targets: BTreeSet<_> = slots
            .iter()
            .filter_map(|slot| match slot {
                ReleaseArtifactSlot::ProductAsset { target, .. } => Some(*target),
                _ => None,
            })
            .collect();
        if slots
            .iter()
            .filter(|slot| matches!(slot, ReleaseArtifactSlot::ProductAsset { .. }))
            .count()
            != ProductTarget::ALL.len()
            || targets.len() != ProductTarget::ALL.len()
            || !ProductTarget::ALL.iter().all(|target| targets.contains(target))
            || slots
                .iter()
                .filter(|slot| matches!(slot, ReleaseArtifactSlot::ChecksumManifest { .. }))
                .count()
                != 1
            || slots
                .iter()
                .filter(|slot| matches!(slot, ReleaseArtifactSlot::ReleaseMetadata { .. }))
                .count()
                != 1
        {
            return Err(SuccessorError::InvalidProductRoster);
        }
        let mut names = BTreeSet::new();
        if slots.iter().any(|slot| !names.insert(slot.file_name())) {
            return Err(SuccessorError::DuplicateFileName);
        }
        Ok(())
    }

    fn validate_operations(
        release: &ProductReleaseId,
        destination: &ReleaseDestinationBinding,
        approved: &[ApprovedRegistryArtifact],
        operations: &[ReleaseOperation],
        slots: &[ReleaseArtifactSlot],
    ) -> Result<(), SuccessorError> {
        let ids: BTreeSet<_> = operations.iter().map(|operation| operation.id.clone()).collect();
        if ids.len() != operations.len() {
            return Err(SuccessorError::DuplicateOperation);
        }
        for operation in operations {
            operation.id.validate(release)?;
            if operation.prerequisites.windows(2).any(|pair| pair[0] >= pair[1])
                || operation.prerequisites.iter().any(|id| !ids.contains(id))
            {
                return Err(SuccessorError::InvalidPrerequisite);
            }
        }
        let expected_uploads: BTreeSet<_> = slots.iter().filter(|slot| slot.release().is_some()).cloned().collect();
        let uploads: BTreeSet<_> = operations
            .iter()
            .filter_map(|operation| match &operation.id {
                ReleaseOperationId::ArtifactUpload { slot, .. } => Some(slot.clone()),
                _ => None,
            })
            .collect();
        if uploads != expected_uploads {
            return Err(SuccessorError::InvalidProductRoster);
        }
        let registry_operations: BTreeSet<_> = operations
            .iter()
            .filter_map(|operation| match &operation.id {
                ReleaseOperationId::RegistryArtifactPublish { slot, .. } => Some(slot.clone()),
                _ => None,
            })
            .collect();
        let registry_slots: BTreeSet<_> = slots
            .iter()
            .filter(|slot| matches!(slot, ReleaseArtifactSlot::RegistryPackage { .. }))
            .cloned()
            .collect();
        if registry_operations != registry_slots || registry_slots.len() != approved.len() {
            return Err(SuccessorError::InvalidPackageOperation);
        }
        let tags = operations
            .iter()
            .filter(|operation| matches!(operation.id, ReleaseOperationId::ProductTag { .. }))
            .collect::<Vec<_>>();
        let prepares = operations
            .iter()
            .filter(|operation| matches!(operation.id, ReleaseOperationId::ForgePrepare { .. }))
            .collect::<Vec<_>>();
        let publishes = operations
            .iter()
            .filter(|operation| matches!(operation.id, ReleaseOperationId::ForgePublish { .. }))
            .collect::<Vec<_>>();
        if tags.len() != 1 || prepares.len() != 1 || publishes.len() != 1 {
            return Err(SuccessorError::InvalidProductOperation);
        }
        let mut registry_ids = operations
            .iter()
            .filter_map(|operation| {
                matches!(operation.id, ReleaseOperationId::RegistryArtifactPublish { .. })
                    .then_some(operation.id.clone())
            })
            .collect::<Vec<_>>();
        registry_ids.sort();
        if tags[0].prerequisites != registry_ids
            || prepares[0].prerequisites != [tags[0].id.clone()]
            || operations.iter().any(|operation| {
                matches!(operation.id, ReleaseOperationId::ArtifactUpload { .. })
                    && operation.prerequisites != [prepares[0].id.clone()]
            })

item.stdout:
            )));
        }
        Ok(())
    }

    fn create_floating_major(
        &self,
        major_name: &str,
        target_sha: &CommitSha,
        _permit: &ApplyPermit,
    ) -> Result<(), VcsError> {
        let output = self
            .runner
            .run("git", &["tag", "-f", "--", major_name, target_sha.as_str()], &self.root)?;
        if !output.success() {
            return Err(VcsError::Git(format!(
                "`git tag -f` failed in `{}`: {}",
                self.root.display(),
                output.redacted_stderr()
            )));
        }
        Ok(())
    }

    fn observe_remote_annotated_tag(
        &self,
        remote: &str,
        name: &TagName,
        target_sha: &CommitSha,
        annotation_digest: &TagAnnotationDigest,
    ) -> Result<RemoteAnnotatedTagObservation, VcsError> {
        // Ask for both the tag object and its peeled target. `ls-remote`
        // exposes neither a tag annotation nor its object body, so after this
        // cheap absence/target check we fetch only the named tag object with
        // no local ref or FETCH_HEAD update and inspect that exact object.
        let tag_ref = format!("refs/tags/{}", name.as_str());
        let peeled_ref = format!("{tag_ref}^{{}}");
        let ls_remote = self.runner.run(
            "git",
            &["ls-remote", "--tags", "--", remote, &tag_ref, &peeled_ref],
            &self.root,
        )?;
        if !ls_remote.success() {
            return Err(remote_command_error("git ls-remote", &ls_remote));
        }
        let refs = parse_ls_remote_tag_refs(&ls_remote.stdout, &tag_ref, &peeled_ref)?;
        let Some(tag_object) = refs.tag_object else {
            return Ok(RemoteAnnotatedTagObservation::Absent);
        };
        let Some(peeled_target) = refs.peeled_target else {
            return Ok(RemoteAnnotatedTagObservation::Conflict(
                RemoteAnnotatedTagConflict::LightweightTag,
            ));
        };
        if peeled_target != *target_sha {
            return Ok(RemoteAnnotatedTagObservation::Conflict(
                RemoteAnnotatedTagConflict::Target {
                    expected: target_sha.clone(),
                    actual: peeled_target,
                },
            ));
        }

        let fetch = self.runner.run(
            "git",
            &["fetch", "--no-tags", "--no-write-fetch-head", "--", remote, &tag_ref],
            &self.root,
        )?;
        if !fetch.success() {
            return Err(remote_command_error("git fetch", &fetch));
        }
        let tag_object_id = tag_object.as_str();
        let object = self.runner.run(
            "git",
            &["--no-replace-objects", "cat-file", "-p", "--", tag_object_id],
            &self.root,
        )?;
        if !object.success() {
            return Err(remote_command_error("git cat-file", &object));
        }
        let (declared_target, actual_annotation) = parse_annotated_tag_object(&object.stdout)?;
        if declared_target != *target_sha {
            return Ok(RemoteAnnotatedTagObservation::Conflict(
                RemoteAnnotatedTagConflict::MalformedTarget,
            ));
        }
        let actual_digest = TagAnnotationDigest::from_tag_object_message(actual_annotation.as_bytes());
        if actual_digest != *annotation_digest {
            return Ok(RemoteAnnotatedTagObservation::Conflict(
                RemoteAnnotatedTagConflict::Annotation {
                    expected: annotation_digest.clone(),
                    actual: actual_digest,
                },
            ));
        }
        Ok(RemoteAnnotatedTagObservation::Exact)
    }

    fn push_annotated_tag_and_confirm(
        &self,
        remote: &str,
        name: &TagName,
        target_sha: &CommitSha,
        annotation_digest: &TagAnnotationDigest,
        _permit: &ApplyPermit,
    ) -> Result<RemoteAnnotatedTagObservation, VcsError> {
        let tag_ref = format!("refs/tags/{}", name.as_str());
        let refspec = format!("{tag_ref}:{tag_ref}");
        let push = self
            .runner
            .run("git", &["push", "--no-follow-tags", "--", remote, &refspec], &self.root)?;
        if !push.success() {
            // A concurrent producer can turn an initially absent tag into a
            // conflict between observation and push. Re-observe once so that
            // known remote divergence remains typed instead of becoming an
            // opaque command failure; other failures stay VcsError.
            return match self.observe_remote_annotated_tag(remote, name, target_sha, annotation_digest) {
                Ok(RemoteAnnotatedTagObservation::Conflict(conflict)) => {
                    Ok(RemoteAnnotatedTagObservation::Conflict(conflict))
                }
                Ok(_) | Err(_) => Err(remote_command_error("git push", &push)),
            };
        }
        self.observe_remote_annotated_tag(remote, name, target_sha, annotation_digest)
    }
}

struct LsRemoteTagRefs {
    tag_object: Option<CommitSha>,
    peeled_target: Option<CommitSha>,
}
        permit: &ApplyPermit,
    ) -> Result<(), VcsError> {
        if let Some(repo) = &self.native {
            return repo.create_floating_major(major_name, target_sha, permit);
        }
        self.shell.create_floating_major(major_name, target_sha, permit)
    }

    fn observe_remote_annotated_tag(
        &self,
        remote: &str,
        name: &TagName,
        target_sha: &CommitSha,
        annotation_digest: &TagAnnotationDigest,
    ) -> Result<RemoteAnnotatedTagObservation, VcsError> {
        // The invocation-owned ShellGit is canonical here. It preserves the
        // caller's command-routing/credential policy while using the same
        // fetch-and-readback protocol that direct GitRepository calls share.
        self.shell
            .observe_remote_annotated_tag(remote, name, target_sha, annotation_digest)
    }

    fn push_annotated_tag_and_confirm(
        &self,
        remote: &str,
        name: &TagName,
        target_sha: &CommitSha,
        annotation_digest: &TagAnnotationDigest,
        permit: &ApplyPermit,
    ) -> Result<RemoteAnnotatedTagObservation, VcsError> {
        // Push is a mutation and must be paired with the shell transport's
        // mandatory remote readback. Do not try native first: gix cannot
        // provide that paired protocol, and a retry could double-apply it.
        self.shell
            .push_annotated_tag_and_confirm(remote, name, target_sha, annotation_digest, permit)
    }
}

