fn observe_registry(
    session: &mut ObservationSession,
    artifacts: &ValidatedArtifactManifest<'_, '_>,
    validated: &ValidatedReleaseIntent<'_>,
    package: &ReleasePackageId,
    version: &Version,
    registry: callisto_model::RegistryBindingId,
    slot: &ReleaseArtifactSlot,
    endpoints: PreparedRegistryEndpointsView<'_>,
) -> OperationObservation {
    let snapshot = match artifacts.snapshot(slot) {
        Ok(snapshot) => snapshot,
        Err(_) => {
            return OperationObservation::Unverifiable(ObservationFailure::Capability {
                provider: ObservationProvider::ArtifactCapability,
            })
        }
    };
    let expected_digest = ArtifactDigest::from_bytes(snapshot.bytes());
    let expected_length = snapshot.bytes().len() as u64;
    let exact = || {
        OperationObservation::Exact(ReleaseObservationEvidence::registry_artifact(
            package.clone(),
            version.clone(),
            registry.clone(),
            slot.clone(),
            expected_digest.clone(),
            expected_length,
        ))
    };

    match endpoints {
        PreparedRegistryEndpointsView::Cargo { api, .. }
            if matches!(
                slot,
                ReleaseArtifactSlot::RegistryPackage {
                    format: RegistryArtifactFormat::CargoCrate,
                    ..
                }
            ) =>
        {
            let url = match cargo_metadata_url(api, package.name(), version) {
                Some(url) => url,
                None => return malformed(ObservationProvider::Cargo),
            };
            match observe_json_http(validated.runner(), validated.root(), &url, ObservationProvider::Cargo) {
                Ok(None) => OperationObservation::Absent,
                Ok(Some(value)) => {
                    let Some(raw_digest) = value
                        .get("version")
                        .and_then(|version| version.get("checksum"))
                        .and_then(serde_json::Value::as_str)
                    else {
                        return malformed(ObservationProvider::Cargo);
                    };
                    let Ok(observed) = ArtifactDigest::parse(raw_digest) else {
                        return malformed(ObservationProvider::Cargo);
                    };
                    if observed == expected_digest {
                        exact()
                    } else {
                        OperationObservation::Conflict(ExternalConflict::RegistryDigest {
                            slot: slot.clone(),
                            observed,
                        })
                    }
                }
                Err(failure) => OperationObservation::Unverifiable(failure),
            }
        }
        PreparedRegistryEndpointsView::Npm { registry: registry_url }
            if matches!(
                slot,
                ReleaseArtifactSlot::RegistryPackage {
                    format: RegistryArtifactFormat::NpmTarball,
                    ..
                }
            ) =>
        {
            match observe_npm_artifact(
                validated,
                package.name(),
                version,
                registry_url,
                slot.file_name(),
                expected_length,
            ) {
                Ok(NpmArtifactObservation::Absent) => OperationObservation::Absent,
                Ok(NpmArtifactObservation::LengthMismatch(observed)) => {
                    OperationObservation::Conflict(ExternalConflict::RegistryLength {
                        slot: slot.clone(),
                        observed,
                    })
                }
                Ok(NpmArtifactObservation::Bytes(observed)) => {
                    if observed == expected_digest {
                        exact()
                    } else {
                        OperationObservation::Conflict(ExternalConflict::RegistryDigest {
                            slot: slot.clone(),
                            observed,
                        })
                    }
                }
                Err(failure) => OperationObservation::Unverifiable(failure),
            }
        }
        PreparedRegistryEndpointsView::Pypi { metadata, .. }
            if matches!(
                slot,
                ReleaseArtifactSlot::RegistryPackage {
                    format: RegistryArtifactFormat::PythonWheel | RegistryArtifactFormat::PythonSdist,
                    ..
                }
            ) =>
        {
            observe_pypi(
                session, artifacts, validated, package, version, registry, slot, metadata,
            )
        }
        _ => OperationObservation::Unverifiable(ObservationFailure::Capability {
            provider: ObservationProvider::PreparedCapability,
        }),
    }
}

